return {
  [813715108829184] = "Uau, au, au!",
  [813709740740608] = "Qual carruagem você gostaria de pegar?",
  [813709740676608] = "Há mais alguma coisa que você precisa?",
  [813709740348416] = "8 gramas de canela em pó... 100 mililitros de água pura...",
  [813709740240384] = "Você está bem?",
  [813709740298752] = "Para ser sincero, quero ganhar a surpresa e os aplausos de todos na próxima sessão de canto. Está muito quieto aqui, não é?",
  [813709740108288] = "Eu costumava pensar que este lugar era um pouco estranho e frio.",
  [813709740141056] = "Quanto mais você sabe, mais perigoso é.",
  [813709739960832] = "Para onde estamos indo, {{Sr.|Sra.}}?",
  [519177257701889] = "Espere, o que você colocou?",
  [818111813393920] = "Quão antigo é?",
  [818107787116544] = "<P_Heart> (Você estende a mão para tocar a fechadura do baú do tesouro, mas um arrepio percorre suas pontas dos dedos - isso faz você sentir que alguma existência está observando você.) </>",
  [818107786985472] = "Muitas histórias têm personagens corajosos semelhantes.",
  [818107787022336] = "(Um rangido sai da boca da marionete) Não mencione isso. Encontrei aquele Estripador quando comecei meu turno ao anoitecer; ele tinha acabado de entrar na floresta.",
  [818107786854400] = "O que eu quero pegar pode não ser um peixe.",
  [818107786891264] = "Ah! Sem os romances de Fors para ler, não aguento mais!",
  [818107786723328] = "Estou agindo como um herói. Um herói deve praticar diligentemente todos os dias, coletar varas de madeira e se tornar um herói qualificado, só então poderei...",
  [818107786760192] = "Se você for passear dentro do castelo, preste atenção à sua segurança. Afinal, é uma ruína abandonada, sem ninguém no comando e ninguém pode garantir se um acidente ou o amanhã virá primeiro.",
  [818107786594304] = "Não dê desculpas. Diga ao Sr. Yate que vou cultivar as maiores e mais doces abóboras este ano, ainda mais doces que as uvas dele!",
  [818107786629120] = "Ele acabou de levar uma bicada na cabeça de um pássaro, mas passou o dia todo xingando os pássaros.",
  [818107786465280] = "Sem estrutura mecânica, sem fornecimento de energia, mas a água da Fonte da Purificação flui continuamente; é isso que é misticismo...",
  [818107786498048] = "Então qual é a utilidade de uma sensação de crise?",
  [818107786563584] = "Que bom ver você! Ouvi dizer que algumas coisas estranhas aconteceram no Lago Golden Autumn; uma muda de Árvore Dourada criou raízes e brotou durante a noite, transformando-se em uma grande árvore.",
  [519109612008704] = "Sem problemas!",
  [519109612135424] = "Você é o recém-chegado que acabou de se juntar ao Blackthorn?",
  [360778595126272] = "Você!",
  [360778595239424] = "Mas...",
  [818107786628096] = "Porque os bifes não falam! Essa é a piada que aquela velha ali usa para enganar os transeuntes há mais de dez anos!",
  [818107786631680] = "Quando você precisar da senha, dizer \"Bêbado\" é sempre correto! É claro que senhas como essa podem mudar em pouco tempo... mas quem se importa, cuidaremos disso quando chegar a hora!",
  [818107786641664] = "Isto é o que a Sra. Fors me confiou para lhe dar; pode ajudá-lo a abrir o caminho a seguir.",
  [818107786644992] = "Louvado seja a Deusa! Eu não esperava ver o vapor do trem aparecer nesta estação novamente hoje.",
  [818107786651136] = "Que bela vinícola.",
  [818107786654208] = "Você precisa participar de alguma atividade?",
  [818107786659072] = "Certa vez, os idosos da minha família desenterraram verdadeiros tesouros do castelo... talheres de prata com padrões escuros, relógios de bolso de ouro - tudo isso são heranças ancestrais!",
  [818107786666240] = "Olá, jardineiro. Sempre vejo você aqui cuidando das flores, em meio ao vento e à chuva.",
  [818107786668032] = "Andar por aqui me faz sentir melhor.",
  [818107786671616] = "Você está aqui há muito tempo, não é?",
  [818107786678272] = "Com essa iluminação e ângulo, com certeza poderei tirar a foto mais linda do casamento de Xena!",
  [818107786699776] = "Burnier, Baker e Anselm enviaram poemas de amor... Com quem devo namorar esta noite?",
  [818107786706176] = "Oh! Este rio é verdadeiramente mágico; você pode pescar muitos itens novos nele!",
  [818107786707456] = "Meu violão foi mastigado por um esquilo, então não posso praticar.",
  [818107786712320] = "O cachorrinho é tão fofo... por que tem um bilhete pendurado nele?",
  [818107786716928] = "Tenha cuidado e fique seguro.",
  [818107786727680] = "Retire, não quero seu dinheiro.",
  [818107786728192] = "Primeiro, os mendigos também têm dignidade.",
  [818107786767360] = "Você finalmente está aqui!",
  [818107786770688] = "Isso esgotou seu poder e ela teve que cair em um sono profundo, mas mesmo agora ela está nos protegendo das sombras.",
  [818107786770944] = "Então como posso vê-la? Ela deve ser muito poderosa!",
  [818107786771200] = "Bom... ela só gosta de crianças boas, daquelas que comem cenoura direito!",
  [818107786771456] = "O parasitismo em um lugar como o Lago Golden Autumn pode um dia transformar você em um monstro com cogumelos crescendo em sua cabeça.",
  [818107786771968] = "Uma cidade que reverencia os “sonhos”... talvez seja a “obra-prima” de algum velho conhecido?",
  [818107786772480] = "A família do antigo castelo herdou a linhagem daquele arconte. Eu me pergunto se eles também sempre perderão suas memórias...",
  [818107786772992] = "Se a 'meia-noite do meio-dia' quando a Fada do Nenúfar aparece não se refere a um horário específico...",
  [818107786778112] = "Então é uma barraca de brinquedos?",
  [818107786792704] = "Aquela caverna à frente me dá uma sensação ruim.",
  [818107786800640] = "Sábio, parece que este caso já está além do seu escopo.",
  [818107786803200] = "Espere, {Sr. {EM. |}}.",
  [818107786804224] = "<P_Heart> (Animado) </> Wuu wuu... wuu wuu...",
  [818107786805760] = "Nesta cidade nascem novas oportunidades todos os dias.",
  [818107786816000] = "Case com ele! Case com ele!",
  [818107786821888] = "Vá sentar-se no pavilhão à beira do lago; a vasta extensão ampliará sua mente. Acredite em mim, isso fará você esquecer todos os seus problemas.",
  [818107786822656] = "Este lugar esquecido por Deus! Lama espirrou nas minhas botas, você sabia disso? Estes foram feitos sob medida pelo melhor sapateiro de Backlund!",
  [818107786824704] = "Minha pintura está em branco. Ainda estou esperando, esperando que o vento leve aquela nuvem para a posição certa, esperando que uma borboleta pouse em uma flor.",
  [818107786828032] = "<P_Heart> (Rindo) </> Mais velho é bom; os mais velhos sabem valorizar os outros e têm ideias próprias, meu jovem.",
  [818107786828544] = "Quando apaixonados, eles não falam muito, mas se lembram de cada palavra que você disse. Namorar alguém assim provavelmente seria uma experiência muito boa.",
  [818107786835456] = "No entanto, antes de mergulharmos na investigação, preciso submeter você a um pequeno teste.",
  [818107786842368] = "Insetos! Insetos! Não chegue perto de mim!",
  [818107786845696] = "Homem jovem, cabelo curto, integrante da equipe de expedição. Você o viu?",
  [818107786849024] = "Há um maldito ladrão em nosso acampamento!",
  [818107786850560] = "Ver meu próprio nome em uma lápide... honestamente, me dá arrepios.",
  [818107786853632] = "No gelo?",
  [818107786856448] = "É o Hornacis! Você sabe qual é a parte mais interessante? Nenhum sepultamento deste país foi encontrado nas ruínas! Por que é que?",
  [818107786858496] = "Exatamente, Hornacis! Você sabe qual é a parte mais interessante? Nenhum sepultamento deste país foi encontrado nas ruínas! Por que é que?",
  [818107786859520] = "Essa é a contradição! Os murais mostram que o povo deste reino tinha costumes em relação à morte, mas não envolvem nenhum sepultamento, como se os moradores daqui não precisassem ser enterrados e não fossem morrer!",
  [818107786861056] = "As alucinações coletivas são aterrorizantes... até o conhecimento que não existe entra no cérebro...",
  [818107786862592] = "Pelo menos 1.500 anos!",
  [818107786863360] = "Porque ambos reverenciavam e temiam a noite, então eles personificaram uma divindade para adorar, chamando essa divindade de Mestre da Noite, a Mãe do Céu!",
  [818107786865152] = "Você está muito preocupado?",
  [818107786889216] = "Segmento de ID ocupado 9030580-9030589_Blackthorn Incident Log 1_5200227",
  [818107786889728] = "Que tipo de acampamento é esse?",
  [818107786904576] = "Ah, então não é o Padre Hawkins...",
  [818107786905856] = "Eu sei! A base secreta de Amy fica na Estação de Passageiros! Daisy disse que tem um lugar bom no antigo castelo, mas não me atrevi a segui-lo, é muito longe...",
  [818107786906368] = "Estou brincando de esconde-esconde com Billy! Ele definitivamente não imaginaria que eu poderia correr tão longe no tempo que ele leva para contar até cem.",
  [818107786915584] = "Molly, na verdade, há algo...",
  [818107786930432] = "Suspiro, quando será entregue?",
  [818107786930944] = "O que você está fazendo aqui?",
  [818107786937600] = "Parece que você está muito apaixonado. Existe uma história para ouvir?",
  [818107786940160] = "O baú do tesouro é seu para abrir? Você perguntou à nossa Gangue de Caçadores de Dragões?",
  [818107786943488] = "Que baú de tesouro resistente! Parece que não pode ser aberto diretamente.",
  [818107786944000] = "Se você quiser abrir este baú do tesouro, terá que jogar comigo.",
  [818107786944256] = "Interessante, você estava tentando me ignorar agora há pouco? Que pena, você já foi ‘lembrado’ por mim.",
  [818107786944768] = "Quer ser pago? Primeiro inscreva-se na 'Bomba de Dividendos' – se você ganhar, você divide o dinheiro; se você perder, é apenas azar.",
  [818107786945280] = "Olá, este {Sr. {EM. |}}, bem-vindo a Tingen, permita-me recomendar o serviço de passeio turístico em carruagem da nossa agência.",
  [818107786966784] = "Hahahahaha, eu te assustei?",
  [818107786968320] = "Obrigado pelo seu patrocínio, volte novamente!",
  [818107786971904] = "O que é isso de uma casa ancestral mal-assombrada que você mencionou?",
  [818107786972160] = "É a casa da minha família que tem centenas de anos. O lugar está muito degradado, então pretendo vendê-lo por algum dinheiro para subsidiar a casa.",
  [818107786972416] = "Mas todas as noites ouvem-se ruídos estranhos na casa: passos, suspiros e pessoas subindo as escadas.",
  [818107786972672] = "Eu sou o único na casa, então quem está fazendo barulho deve ser...algo impuro!",
  [818107786972928] = "<P_Heart> (Algo impuro? Pode haver um poder extraordinário, vá dar uma olhada com ele.) </>",
  [818107786973184] = "Talvez eu possa ajudar. Por que você não me deixa tentar?",
  [818107786973440] = "Você... você pode expulsar essa coisa? Ótimo! Vamos, siga-me rapidamente!",
  [818107786973696] = "William Haywood, o anfitrião deste baile, não parece um verdadeiro anfitrião. Seu rosto, de trinta e poucos anos, deveria ser imponente, mas uma leve camada de cansaço pairava entre suas sobrancelhas.",
  [818107786977024] = "Senhora, você parece muito ansiosa?",
  [818107786979072] = "Esta será uma melodia edificante.",
  [818107786979584] = "Espero que gostem...",
  [818107786980352] = "Por favor, fique intoxicado pela música...",
  [818107786981120] = "Desejo-lhe relaxamento e liberdade...",
  [818107786981888] = "Você conhece Jack, o Estripador?",
  [818107786988800] = "Parece ser apenas um cadáver comum.",
  [818107786991616] = "Num porão tão escuro, que luz poderia haver?",
  [818107786993408] = "Vá e dirija a próxima cena.",
  [818107786994176] = "Nenhum deles quer mais jogar. Você se juntará a mim para uma rodada? Não estou com falta de dinheiro, é só...",
  [818107787018496] = "Deixe-me perguntar por você.",
  [818107787019776] = "Vendo cerveja todos os dias, não vi nenhum Godot.",
  [818107787025920] = "Pegou o caminho errado? Por que há um penhasco à frente?",
  [818107787029248] = "Eu fui amaldiçoado! Não consigo me levantar do chão; só um beijo de amor verdadeiro pode quebrá-lo!",
  [818107787032576] = "<P_Heart> (Você tira um bilhete coberto de sangue com a palavra \"Ajuda\" escrita nele) </>",
  [818107787063296] = "Você ainda precisa encontrar outros presos com quem cooperar; o caminho para a redenção começa aqui.",
  [818107787066112] = "Olha {Sr. {EM. |}}, que linda montanha nevada. Interessado em uma emocionante corrida ao lado do penhasco na montanha nevada?",
  [818107787067392] = "Hehe, Seu espiritualidade também está aqui... Esse sentimento é como se aquela guerra divina daquela época ainda não tivesse terminado.",
  [818107787069184] = "Você finalmente veio, Detetive {Sr. {EM. |}}...",
  [818107787079424] = "Como eu poderia querer matá-lo? Não, isso não está certo...",
  [818107787080192] = "Para ser mais preciso, você é o assassino que matou o Barão, mas o verdadeiro culpado por tudo isso é outra pessoa.",
  [818107787092736] = "As equações deste livro foram todas resolvidas; Posso finalmente completar o selamento.",
  [818107787093504] = "Me ajude! Puxe-me para fora!",
  [818107787114752] = "Ainda pode ser polido aqui...",
  [818107787117568] = "Que a Deusa favoreça você, {Sr. {EM. |}}. Sou a Sra. Sammer, uma testemunha da Aliança. Se você encontrar aquela pessoa com quem deseja passar a vida, posso presidir o ritual do Covenant para você.",
  [818107787123968] = "<P_Heart> (Várias pedras brilhantes estão espalhadas ao redor do baú do tesouro; o dono do baú parece gostar muito dessas pequenas coisas brilhantes.) </>",
  [818107787127808] = "<P_Heart> (Os materiais para fazer a poção não são suficientes, vá coletar mais alguns...) </>",
  [818107787152640] = "Quer começar a conferir a moda Loen?",
  [818113155407616] = "É um lixo!",
  [818107786655232] = "Não há ninguém aqui?",
  [818107786694400] = "Huh? Isso é algo que posso ouvir?",
  [1143563229121024] = "Eu estava aqui quando ele nasceu. A primeira vez que ele andou a cavalo, a primeira vez que caçou... Lembro-me de tudo.",
  [818107786512640] = "A sala de literatura está aberta a todos os membros da escola. Está dividido em dois andares: o primeiro andar abriga diversos livros de literatura e ciências sociais, enquanto o segundo andar contém livros relacionados a Beyonder habilidades.",
  [818107787094784] = "Hum... hum.",
  [818107786512384] = "Felizmente, com a ajuda da Senhorita Eremita, um conhecimento tão vasto e misterioso pode ser apresentado com tanta segurança.",
  [818107787094528] = "Sim... sim, de volta ao orfanato. Benjamin, você mostra o caminho, eu protegerei Annie. Annie, vamos lá...",
  [818107786512128] = "Apenas a fórmula da poção pode levar as pessoas a um vórtice imprevisível.",
  [818107787094272] = "Eu... estou aqui. Ouça, temos que sair daqui e voltar para o orfanato. Dona Martha... Dona Martha já pode estar nos esperando lá.",
  [1143563228288256] = "Não importa, não importa quando, estou sempre disposto a apresentar meu Senhor, o grande Sr. “Tolo”, a vocês.",
  [1143563228288000] = "Mantendo uma posição elevada, mas sendo filantrópico e de mente aberta, louvado seja o meu Senhor!",
  [1143563228287744] = "Ele cuida de todos os seres vivos; mesmo que você não acredite em 'The Fool', você ainda pode aproveitar tudo o que Clube do Tarô tem a oferecer.",
  [1143563228287488] = "Meu Senhor não forçará as pessoas a se converterem, nem se importará se a fé de alguém for pura. Simplificando, Ele não se importa se as pessoas acreditam Nele enquanto acreditam em outros deuses.",
  [1143563228287232] = "O Sr. Louco é misericordioso e compassivo, o salvador deste mundo, mas ele nos permite tratá-lo como “ele” em vez de “Ele”.",
  [1143563228286976] = "O Sr. Louco é um Deus verdadeiro reconhecido por todas as igrejas, e o estabelecimento bem-sucedido do Clube do Tarô também foi graças à sua ajuda.",
  [1143563228286720] = "Meu Senhor salvou a cidade-estado perdida abandonada pelos deuses, conduziu os sobreviventes daquele continente para fora da 'Terra Abandonada dos Deuses' e reconstruiu sua casa nas ilhas...",
  [818107786511360] = "Está tudo bem, amigo; pequenos atos de bondade também podem mudar o mundo. Espero encontrá-lo em atividades futuras.",
  [1143563228284928] = "Meu Senhor reside acima da realidade e do Mundo Espiritual, Sua benevolência se espalha pelos céus e pela terra, e há seis anjos ao Seu lado...",
  [818107787094016] = "Irmão Benjamin... estou com medo... quero ir para casa...",
  [818107786550528] = "Um anel de ferro preto com uma protuberância em forma de espigão no topo, manchado com sangue antigo, antigo e maligno.",
  [818107786582784] = "Quando você se depara com uma contradição, você deve confrontar seu alvo com “evidências” irrefutáveis.",
  [818107786871040] = "Ian – quando exatamente Ian virá? Quero ver o novo trabalho do Fors!",
  [818107786583296] = "E a etapa final, que também é a chave:",
  [818107786624512] = "A cabra do velho Buck é mais preta que a barba! Próximo!",
  [818107786642432] = "Deixe os monstros restantes comigo.",
  [818107786662656] = "Que sorte temos de ver o Lago Dourado do Outono como é hoje – mesmo que seja na forma de corpos espirituais. Oh, devemos agradecer à Sra. Gwenny por isso.",
  [818107786661376] = "Isso mesmo. Disposto a entrar? Ou volte para mim quando tiver se decidido.",
  [818107786660352] = "Cinco soles para levá-lo em uma viagem ao castelo. Tudo o que você encontrar é seu, que tal?",
  [818107786799872] = "Além disso, você também pode utilizar unidades a vapor para atualizar os trens que estão prestes a pegar a estrada, o que certamente aumentará ainda mais sua receita.",
  [818107787152128] = "Pena que não sou citadina e não posso ir muito ao teatro, mas felizmente existe a Escola de Artes, que me permite aprender alguns passos de dança do repertório.",
  [818107787151872] = "Desde que vi a apresentação do balé 'Giselle' no teatro Tingen, há três meses, cinco dias e sete horas, não consigo parar de pensar nisso!",
  [818107787151616] = "Nossa trupe de arte será a primeira a desafiar o impossível! Você quer se juntar a nós?",
  [818107787151360] = "Estamos criando um milagre! Certamente ninguém na Escola de Arte já se apresentou em uma Montanha Nevada antes.",
  [818107787151104] = "Tia Marta nos levou para ensaiar a dança mais popular da Escola de Artes. Ouvi dizer que até as pessoas exigentes de Backlund gostam muito desta dança.",
  [818107787150848] = "Estamos nos preparando para o baile do celeiro desta noite!",
  [818107787150592] = "Desde que meu passarinho viu essa dança na Escola de Artes ficou muito animado. Talvez seja porque esses movimentos são muito parecidos com o andar de um pato, fazendo com que ele, como pássaro, tenha uma sensação de parentesco.",
  [818107787150336] = "Não olhe para mim! Eu sei que meus passos de dança são engraçados. Suspiro, isso é tudo para o meu passarinho, sabe, ele abandonou a mãe quando era muito pequeno...",
  [818107787150080] = "Já participei de muitas apresentações na Escola de Artes e tenho certeza que danço melhor que todas elas.",
  [818107787149824] = "Que oração? Não sei. Os quatro estão todos dançando e eu também quero dançar!",
  [818107787149568] = "Por favor, apoie-nos! Em troca, estamos dispostos a oferecer uma apresentação de dança para a cerimônia de aliança sua e de seu parceiro.",
  [818107787149312] = "Riddle e eu somos criadores bastante conhecidos da Escola de Arte e um dia nos tornaremos muito famosos!",
  [818107787149056] = "Todos os sábados e domingos, das 19h30 às 21h, este buff é reforçado para [Glória Brilhante da Sociedade]: +3 em jogadas de dados baseadas em Carisma e Intuição; depois de participar do jogo de culto, você ganha bônus de atributos de combate.",
  [818107787148800] = "Quando localizados no cenário do Clube, os jogadores ganharão o buff [Resplendor da Organização]: +1 nos resultados dos dados para testes de Carisma e Intuição.",
  [818107787148544] = "Que o destino o favoreça, {Sr. {EM. |}}. Tenho a premonição de que se você jogar os dados aqui, receberá um presente especial de boa sorte.",
  [818107787148288] = "Vejo que você já colheu um bom vinho! Mercadoria verdadeiramente perfeita – deve ser capaz de obter um preço igualmente perfeito.",
  [818107787148032] = "Sou um comerciante viajante. Ouvi dizer que as condições de mercado variam entre os diferentes castelos, por isso estou me preparando para ver a situação aqui.",
  [818107787147776] = "Olha, que mercado maravilhoso! Os comerciantes já se instalaram aqui.",
  [818107787147520] = "{Senhor. {EM. |}}, o que você quer?",
  [818107787147264] = "Olá, Sr.",
  [818107787147008] = "Olá, Sra.",
  [818107787146752] = "Olá, Élder Lovia!",
  [818107787146496] = "Olá, dona Melissa!",
  [818107787146240] = "Olá, Sr. Frank!",
  [519041160701952] = "Uuuuuu...",
  [818107787145984] = "Olá, Sra. Susie!",
  [519041160771840] = "Então é assim...",
  [818107787145728] = "Olá, Sr.",
  [818107787145472] = "Olá, Capitão Frye!",
  [818107787145216] = "Olá, Sr.",
  [818107787144960] = "Olá, Sr. Enforcado!",
  [818107787144704] = "Olá, Sra. Mágica!",
  [519041160997888] = "Que a Deusa proteja você!",
  [818107787144448] = "Olá, senhorita Audrey!",
  [818107787144192] = "Olá, Capitão Dunn!",
  [818107787143936] = "Olá, Sr. Leonard!",
  [818107787143680] = "Senhor, a misericórdia da Deusa não é medida por dinheiro e lucro. Todos os crentes são Seus filhos, desde que seus corações sejam suficientemente sinceros.",
  [818107787143424] = "É muito presunçoso da minha parte, mas gostaria de perguntar: dez libras trarão dez libras de olhar e cinco libras trarão cinco libras de...",
  [818107787143168] = "Pastor, por favor, me perdoe, não é que meu respeito pela Deusa seja... uh... é só... se eu doar dez libras a menos, a Deusa reduzirá Seu olhar sobre mim?",
  [818107787142912] = "Aqueles que avançam, aqueles que trabalham silenciosamente para o Clube, aqueles que avançam em momentos críticos—\n se a contribuição for suficiente, o nome aparecerá aqui. Se a contribuição não estiver mais lá, ela poderá sair silenciosamente. \n O brilho é justo, assim como o olhar acima da névoa cinzenta.",
  [519041161284352] = "Onde é isso? Chegamos ao cume?",
  [519041161272576] = "EU...",
  [818107787142656] = "A luz gira lentamente em torno da estátua do Louco, com até dez raios fluindo em tempo real.",
  [818107787142400] = "Hum... ah... eh?",
  [519041161376256] = "O tempo está terrível; uma nevasca certamente chegará em meia hora!",
  [818107787142144] = "Senhora, você deve comparecer à próxima missa e ficar na primeira fila - e quero apresentá-la a um policial.",
  [818107787141888] = "Sim... há algum problema? Fela... Fela me salvou da tristeza, e sou muito grato a ele...",
  [818107787141632] = "Espere, senhora, você quer dizer que seu marido Seth morreu de uma doença súbita, e então você conheceu aquele Sr. Phil logo depois, certo?",
  [818107787141376] = "Este Seth não está me condenando no Reino de Deus da Deusa? Ele e Fela nem se conhecem!",
  [818107787141120] = "M-mas, eu sempre sonho com Seth, ele me diz que Phil não é uma boa pessoa, e me diz para não confiar nele...",
  [818107787140864] = "Senhora, eu entendo sua luta. A amorosa Deusa não proíbe uma senhora viúva de recomeçar uma família...",
  [818107787140608] = "Eu... estou com muita dor, falhei com meus dois filhos e com meu falecido marido... mas realmente não posso recusar os avanços de Phil.",
  [818107787140352] = "Se você está aqui para esperar pelo bispo, sinto muito, podemos ocupar o resto do tempo dele.",
  [818107787140096] = "Oh, obrigado pela sua preocupação, estranho. Esta criança ficou assustada durante uma inspeção e precisa de um sermão para ser pacificada.",
  [818107787139840] = "Na catedral da Deusa, nenhum mal irá mais persegui-lo, fique tranquilo.",
  [818107787139584] = "É, é mesmo... vou considerar! Obrigado pelo seu conselho e que a Deusa proteja você também!",
  [818107787139328] = "<P_Heart> (Parece que ele foi afetado por alguma influência de Beyonder na fábrica...) </>",
  [818107787139072] = "Acredite, este é um sinal da Deusa; você precisa do conforto da noite e da ajuda da Igreja.",
  [818107787138816] = "Hum? Devo incomodar o bispo com assuntos tão triviais? Não seria também...",
  [818107787138560] = "Suspeito que fiquei assustado ao inspecionar a fábrica em nome do cliente. É verdadeiramente vergonhoso que um advogado seja tão tímido.",
  [818107787138304] = "Tenho sido atormentado por todos os tipos de pesadelos recentemente. Alguns são trabalhadores com rostos distorcidos, outros são máquinas cruéis e furiosas...",
  [818107787138048] = "Parece que fiquei tão desgrenhado que atraí a atenção de uma pessoa gentil. Suspiro, é tudo aquele maldito pesadelo.",
  [818107787137792] = "Deusa proteja... por favor, deixe-me escapar desse pesadelo sem fim...",
  [818107787137536] = "Porém, neste momento preciso orar à Deusa, esperando que a Deusa possa proteger minha mãe para que ela melhore logo.",
  [818107787137280] = "Hum? Desculpe, confundi você com um cliente. Isso mesmo, se precisar engraxar os sapatos, pode vir até a Rua Cruz de Ferro e me encontrar! Rápido e bom! Custa apenas de alguns centavos a um xelim!",
  [818107787137024] = "Olá, você precisa de um engraxate? Sinto muito, agora não, temos que sair da igreja.",
  [818107787136768] = "Hum, então deveríamos ficar aqui adequadamente e não deixar a mãe se preocupar.",
  [818107787136512] = "É assim mesmo? Mas... Irmão, acho que a mãe está muito triste.",
  [818107787136256] = "Mas a mãe disse, olhe para o ponteiro dos minutos... quando o ponteiro dos minutos se mover até aqui, a mãe estará de volta do confessionário.",
  [818107787136000] = "Vinte minutos? O relógio de bolso só se moveu um pouquinho!",
  [818107787135744] = "Por que a mãe ainda não voltou? Já se passaram vinte minutos.",
  [818107787135232] = "Você esqueceu o poema que a mamãe recitou para você? Devemos orar pela proteção da Deusa em paz e tranquilidade... Shh...",
  [818107787134976] = "Por que? A Deusa não gosta de crianças barulhentas?",
  [818107787134720] = "Querida, fale baixo. Você tem que ficar quieto na catedral da Deusa.",
  [818107787134464] = "Papai! Está brilhando ali, a Deusa está nos observando?",
  [818107787134208] = "Espero que a Deusa possa aceitar as orações de um pobre crente e me conceder boa sorte uma última vez.",
  [818107787133952] = "Eu não aguento mais; os dias de trabalho durante o dia e estudo à noite estão prestes a me destruir.",
  [818107787133696] = "Trabalhei muito durante dois anos, mas ainda não consegui passar no exame do ensino fundamental. Em breve, em breve será minha última chance.",
  [818107787133440] = "D-desculpe... eu, estou muito nervoso, muito triste.",
  [818107787133184] = "Hum... eu te perturbei?",
  [818107787132928] = "Obrigado pela sua bênção, que a Deusa o proteja!",
  [818107787132672] = "Graças à Deusa, é que o antigo ferimento reaparece no tempo chuvoso. Pelo menos voltei vivo e posso ver Pasha novamente.",
  [818107787132416] = "Tosse, tosse, desculpe, minha noiva é um pouco animada demais. Minha perna... ah, minha perna foi ferida na guerra há alguns anos.",
  [818107787132160] = "Assim que a perna do Alf melhorar, realizaremos o casamento!",
  [818107787131904] = "Sim! Estamos prestes a nos casar sob o olhar da Deusa!",
  [818107787131648] = "Olá, que a Deusa te proteja, há algo em que eu possa ajudar?",
  [818107787131392] = "Sinto muito, o Bispo não está na igreja neste momento. Se precisar de alguma coisa, você pode procurar ajuda de qualquer padre da igreja.",
  [818107787131136] = "Olá, que a Deusa o proteja.",
  [818107787130880] = "Este é o meu agradecimento, espero que tudo corra bem para você no futuro.",
  [818107787130624] = "…O estado agora era muito estranho; talvez sua influência mental ainda não tenha se dissipado. Devo agradecer novamente por seu lembrete.",
  [818107787130368] = "Acho que a matemática é muito racional. Mas palavras, palavras são diferentes. Eles registram o amor e o ódio das pessoas, a vida e a morte, todas as histórias...",
  [818107787130112] = "Meu companheiro e eu sempre discutimos sobre isso; ele acredita no Steam, acreditando que os números são a verdade de tudo.",
  [818107787129856] = "Ouvi seus sussurros, dizendo-me para abri-lo, para provar a grandeza da literatura, do drama e da sensibilidade.",
  [818107787129600] = "…Originalmente já estava selado e não teria causado nenhum novo dano se fosse guardado corretamente, mas meus companheiros e eu ficamos enfeitiçados por eles…",
  [818107787129344] = "Um Artefato Selado em forma de livro formado a partir de um Marionete Mestrado Característica de Beyonder . Tem a propriedade da animação e manipula conscientemente pessoas vivas para se tornarem seu público e atores.",
  [818107787129088] = "Obrigado pela sua contribuição. Eu o rastreei até aqui, mas não esperava cair em sua armadilha. Felizmente você apareceu; caso contrário, eu teria me tornado um Marionete controlado por ele também.",
  [818107787128832] = "<P_Heart> (9 partes de ácido já foram derramadas; conforme descrição na nota, a dosagem ω do rizoma é...) </>",
  [818107787128576] = "<P_Heart> (6 partes de ácido já foram derramadas; conforme descrição na nota, a dosagem ω do rizoma é...) </>",
  [818107787128320] = "<P_Heart> (3 partes de ácido já foram derramadas; conforme descrição na nota, a dosagem ω do rizoma é...) </>",
  [818107787128064] = "<P_Heart> (De acordo com a descrição na nota, a dosagem β do ácido é...) </>",
  [818107787127040] = "Você quer abrir o Hall da Fama?",
  [818107787126784] = "Sério, você realmente precisa tocá-lo? Sua sanidade está prestes a entrar em colapso; isso é muito perigoso para um Beyonder .",
  [818107787126528] = "Você tem certeza de que deseja tocá-lo? Sua sanidade está oscilando; é melhor parar agora.",
  [818107787126272] = "Você tem certeza de que deseja tocá-lo? Sua sanidade cairá para um nível relativamente perigoso.",
  [818107787126016] = "Uma magnífica árvore fica no centro do lago. Sob a casca dourada incomumente bela encontra-se uma essência perigosa Beyonder. Sua razão lhe diz: fique longe disso. Mas outra voz está constantemente enfeitiçando você: <P_Heart> Toque nela. Toque nele. </>",
  [818107787125760] = "<P_Heart> (Eles emitem um zumbido próximo ao baú do tesouro - como se estivessem dando um aviso final.) </>",
  [818107787125504] = "<P_Heart> (Três armas gravadas com runas são colocadas ao lado do baú do tesouro; embora pareçam enferrujadas, você pode sentir claramente o frio que elas emitem.) </>",
  [818107787125248] = "Hehe, uma nova presa mordeu a isca... Awoo!!!",
  [818107787124992] = "<P_Heart> (Quando você se aproxima do baú do tesouro, você ouve vagamente uma respiração pesada vindo da grama ao redor.) </>",
  [818107787124736] = "<P_Heart> (Quando você volta a si, uma figura surge graciosamente dos cachos de flores, olhando para você com um sorriso.) </>",
  [818107787124480] = "<P_Heart> (O ar ao redor do baú do tesouro está repleto de uma estranha fragrância floral – o perfume é excessivamente doce, tão doce que sua visão perde o foco por um momento.) </>",
  [818107787124224] = "<P_Heart> (Parece que você está cercado por esses carinhas fofos.) </>",
  [818107787121408] = "O preço de compra dos produtos é atualizado todas as segundas-feiras. Lembre-se de verificar o horário e produzir produtos de alto valor.",
  [818107787121152] = "Abra a interface “Mercado”, onde você pode encontrar produtos de alto valor e produzi-los em grandes quantidades. Assim que tiver produtos suficientes, você poderá visitar os castelos de outras pessoas e vendê-los.",
  [818107787120896] = "O “mercado” é uma forma importante de adquirir ativos do castelo.",
  [818107787120640] = "Olá, respeitado convidado. Você precisa vender produtos?",
  [818107787120384] = "Não importa quando, se precisar de ajuda, estou aqui. A Deusa favorecerá todas as promessas sinceras.",
  [818107787120128] = "Que você encontre a pessoa que pode tecer o destino com você em breve, {Sr. {EM. |}}.",
  [818107787119872] = "Terceiro, Aliança Eterna – uma vez que vocês tenham confirmado a sinceridade um do outro, eu presidirei a Aliança Eterna para vocês – que é uma promessa solene assinada com votos e lacre.",
  [818107787119616] = "Segundo, Encontro de Sete Noites – o Encontro de Sete Noites de cada mês é um presente de conhecimento concedido pelo destino. Dentro de sete dias, um estranho se tornará um companheiro de viagem, e talvez até mais.",
  [818107787119360] = "Primeiro, Tecelagem de Oração – através do favor do desconhecido, encontrarei a outra ponta do fio do destino para você – a pessoa cuja alma ressoa com a sua.",
  [818107787119104] = "Posso lhe fornecer três tipos de ajuda.",
  [818107787118848] = "Nesta época, há cada vez menos pessoas em quem confiar, mas precisamente por isso, as relações dignas de confiança são ainda mais preciosas.",
  [818107787118592] = "Bem-vindo, {Sr. {EM. |}}. Eu sou a Sra. Sammer, estou muito feliz que você tenha vindo.",
  [818107787118336] = "Embora seja uma pena, se vocês dois pensaram bem, respeitarei sua decisão. Algumas pessoas só podem acompanhá-lo durante uma parte da jornada da vida. Que a Deusa ainda favoreça seus respectivos caminhos à frente.",
  [818107787118080] = "<P_Heart> (suspira) </> , eu entendo que às vezes as promessas podem se tornar algemas, mas por favor pense duas vezes, {Sr. {EM. |}}. Uma rescisão unilateral deixará uma ruptura entre vocês. Esse é realmente o resultado que você deseja?",
  [818107787117824] = "Um Pacto não é feito facilmente e quebrá-lo requer ainda mais cautela. Esta é uma promessa que vocês teceram; você realmente quer rasgar agora? Pense nisso novamente, {Sr. {EM. |}}.",
  [818107787117056] = "Você está aqui, quer começar a tirar fotos?",
  [818107786799616] = "Bem-vindo de volta ao seu território! Vejo seu profundo potencial nos negócios; talvez num futuro próximo, um novo magnata ferroviário nasça em Loen.",
  [818107787116288] = "Beyonder , seus passos me dizem que você não está pronto para enfrentar a verdadeira escuridão. A estaca de madeira não reagirá, mas o inimigo sim. Quer entrar e praticar?",
  [818107787116032] = "Esforce-se muito, deixe os resultados de lado, certo?",
  [818107787115776] = "Que...",
  [818107787115520] = "Estou modificando este relógio de bolso! Ouvi dizer que há outra competição em Backlund no próximo mês...",
  [818107787115264] = "Oh! Você está aqui!",
  [818107787115008] = "Sr. Morgan, você está fazendo um relógio de bolso?",
  [818107787106048] = "<P_Heart> (risos) </> Hmph... não subestime a arte de um 'artesão'.",
  [818107787105792] = "Trevor... você também pode modificar armas de fogo?",
  [818107787105536] = "Já modifiquei esta arma; pode causar danos reais a essas réplicas.",
  [818107787105280] = "Tudo bem, vamos entrar...",
  [818107787105024] = "Esta viagem é longa e perigosa; uma vez que você entra, não há como voltar atrás no meio do caminho. Pense bem antes de concordar.",
  [818107787104768] = "Não tenho medo de esperar, mas tenho medo que você se arrependa depois de entrar.",
  [818107787104512] = "Você está pronto?",
  [818107787104256] = "Vamos. Antes que as sementes criem raízes, quebre aquele maldito espelho.",
  [818107787104000] = "Esse é o 'casulo' que ela deixou quando se tornou uma Bruxa. Enquanto essa coisa existir, ela será imortal.",
  [818107787103744] = "O \"Espelho Primitivo\" de Bonnie, a fonte de seu poder.",
  [818107787103488] = "<P_Heart> (olha para o teatro) </> Escute, essa coisa está dentro.",
  [818107787103232] = "Em mais quarenta e oito horas, você se tornará outro Marionete de Rose Paradise - uma marionete sem autoconsciência que só sabe dançar usando uma máscara.",
  [818107787102976] = "Bonnie plantou \"sementes de flores\" nele, o que fará com que seu espiritualidade sofra corrupção.",
  [818107787102720] = "Eu confirmei; a bala que você levou não era uma bala de chumbo comum.",
  [818107787102464] = "Suspiro... realmente piorou.",
  [818107787102208] = "<P_Heart> (olha para você) </> ...",
  [818107787101952] = "Emma, ​​sinto muito... sinto muito. Nós iremos... nós voltaremos para salvá-los, definitivamente...",
  [818107787101696] = "…Tudo bem, pista inferior, rápido! Annie, fique perto de Benjamin, vou abrir o caminho.",
  [818107787101440] = "Vovô! Obrigado, irmão Benjamim!",
  [818107787101184] = "Ema, estamos indo! Aguentar!",
  [818107787100928] = "Droga... Vovô Thomas, me desculpe.",
  [818107787100672] = "Não! Vovô! Vovô ainda está lá embaixo! Irmão Benjamim...",
  [818107787100416] = "Tudo bem... vamos! Annie, fique perto de Benjamin, eu abrirei o caminho.",
  [818107787100160] = "Só você pode salvá-los... mas não importa o que você escolha, nós o seguiremos.",
  [818107787099904] = "Irmão... você é um Beyonder , a pessoa mais capaz entre nós.",
  [818107787099648] = "Eu sei que é difícil, mas... temos que tomar uma decisão rapidamente.",
  [818107787099392] = "Controle-se, Benjamim!",
  [818107787099136] = "Então temos que... nos apressar. Se nos atrasarmos, não sobrará nada...",
  [818107787098880] = "<P_Heart> (suspira) </> Suspiro, não, certo...",
  [818107787098624] = "Benjamin, seu escudo pode cobrir os dois lados ao mesmo tempo?",
  [818107787098368] = "Droga, há atiradores de ambos os lados...",
  [818107787098112] = "Vovô Thomas... ele, ele não aguenta muito mais... mas, mas Emma também está...",
  [818107787097856] = "Vovô! Vovô está lá embaixo! Irmão Benjamim! Salve o vovô! Por favor... por favor, salve o vovô, ok?",
  [818107787097600] = "Ela está gritando... ela está gritando por socorro! Eu a ouvi chamando seu nome!",
  [818107787097344] = "Escute... Senhorita Emma está presa no segundo andar!",
  [818107787097088] = "Não temos tempo, olhe lá fora!",
  [818107787096832] = "Billy, estou feliz que você esteja bem. Você sabe...",
  [818107787096576] = "Benjamin! Graças a Deus!",
  [818107787096320] = "O tempo está apertado, vá rápido. Não faça muitas perguntas, imagine abri-lo como se abrisse um guarda-chuva...",
  [818107787096064] = "Tudo bem, você acha que todo mundo é um tolo? Isso não é mais segredo.",
  [818107787095808] = "O que? Mas eu não estou...",
  [818107787095552] = "Ele disse que apenas um Beyonder pode liberar seu poder de \"proteção\".",
  [818107787095296] = "Ouça-me, Benjamin, pegue este amuleto. O velho Thomas me pediu para passar para você antes de nos separarmos.",
  [818107787095040] = "Benjamin, crianças... graças a Deus vocês ainda estão vivos.",
  [1143563228319488] = "Obrigado.",
  [1143563228284672] = "Meu Senhor se autodenomina 'O Louco'. No passado, no presente e no futuro, Ele é o grande mestre que domina o Mundo Espiritual, o Rei do Amarelo e do Preto que detém a boa sorte e o farol para todo ser vivo que busca a eternidade.",
  [818107787093760] = "Benjamin! Você... onde você foi agora? Lá fora... havia tiros por toda parte, e fogo. A casa do velho Thomas também está pegando fogo!",
  [818107787092480] = "Deseja redefinir os símbolos?",
  [818107787091712] = "ω dividido por ___ é igual a 2, o que deve ser preenchido no segundo espaço em branco?",
  [818107787091456] = "β dividido por ___ é igual a 2, o que deve ser preenchido no segundo espaço em branco?",
  [818107787091200] = "α dividido por ___ é igual a 2, o que deve ser preenchido no segundo espaço em branco?",
  [818107787090944] = "___ dividido por ___ é igual a 2. O que preencher no primeiro espaço em branco?",
  [818107787090688] = "ω mais ___ é igual a 10, o que deve ser preenchido no segundo espaço em branco?",
  [818107787090432] = "β mais ___ é igual a 10, o que deve ser preenchido no segundo espaço em branco?",
  [818107787090176] = "α mais ___ é igual a 10, o que deve ser preenchido no segundo espaço em branco?",
  [818107787089920] = "___ mais ___ é igual a 10. O que preencher no primeiro espaço em branco?",
  [818107787089664] = "ω multiplicado por ___ é igual a 12, o que deve ser preenchido no segundo espaço em branco?",
  [818107787089408] = "β multiplicado por ___ é igual a 12, o que deve ser preenchido no segundo espaço em branco?",
  [818107787089152] = "α multiplicado por ___ é igual a 12, o que deve ser preenchido no segundo espaço em branco?",
  [818107787088896] = "___ multiplicado por ___ é igual a 12. O que preencher no primeiro espaço em branco?",
  [818107787088640] = "{Senhor. {EM. |}}, você está pronto para aproveitar a aposta?",
  [818107787088384] = "Detetive {{Sr.|Sra.}}, você tem algum resultado de sua investigação?",
  [818107787088128] = "Detetive {{Sr.|Sra.}}, se você ainda tiver dúvidas, por que não investiga a sala primeiro?",
  [818107787087872] = "Se você insiste na resposta errada, não tenho nada a dizer. Só espero que você possa estar tão confiante quando as provas forem apresentadas no tribunal.",
  [818107787087616] = "Já o salvei inúmeras vezes e cumpri meus deveres como médico.",
  [818107787087360] = "O assassino é você! Você observou todo mundo ir e vir com olhos frios, mas não fez nada. Só que você nunca se importou de verdade com a morte do Barão.",
  [818107787087104] = "Para um médico, a morte de um paciente implica a possibilidade de erros de diagnóstico e problemas desnecessários. Eu só preciso ser responsável pela minha própria carreira.",
  [818107787086848] = "Num segundo estávamos conversando normalmente, no seguinte ele estava olhando para mim com olhos cautelosos e desconhecidos... Nenhum termo médico pode descrever seu estado.",
  [818107787086592] = "Sua condição na época era muito sutil, como se outra personalidade tivesse surgido do nada em seu corpo. Seus olhos, palavras e até mesmo sua postura sentada mudariam em um instante.",
  [818107787086336] = "Eu estava apenas realizando um diagnóstico normal. Como médico, observar o paciente é meu dever.",
  [818107787086080] = "A condição do Barão Hawkes está cada vez pior; Receio que ele não tenha muito tempo. Eu contei a ele a verdade sobre sua situação há pouco tempo, mas ele suspeitou que eu o estivesse espionando. Isto é claramente uma forma de ilusão persecutória.",
  [818107787085824] = "Por volta de <P_Yellow> 3:10 </> , o criado foi para o quarto com chá. Eu até o cumprimentei; ele deveria ser a <P_Yellow> última pessoa a ter contato com o Barão </>.",
  [818107787085568] = "Porém... durante esse tempo, vi a senhora, o Sr. John e o criado entrarem no quarto.",
  [818107787085312] = "Vim hoje para uma visita de acompanhamento, então <P_Yellow> estou esperando pelo Barão Hawkes na sala de estar </>.",
  [818107787085056] = "Dr. Evan, o que você estava fazendo antes do incidente ocorrer?",
  [818107787084800] = "Sou apenas responsável por administrar a condição física do Barão Hawkes. Quanto às suas relações familiares e essas disputas... a Madame saberia melhor do que eu.",
  [818107787084544] = "Eu realmente o ouvi falar! Essa voz veio do quarto dele! Detetive {{Sr.|Sra.}}, você tem que acreditar em mim!",
  [818107787084288] = "Não! Não fui eu! Como poderia ser eu! Não tenho motivos para matar o Mestre!",
  [818107787084032] = "O assassino é você! O Barão Hawkes já estava morto antes de você bater na porta; você não poderia ter ouvido a voz dele. Você mentiu porque matou o Barão Hawkes e queria encobrir a verdade com mentiras!",
  [818107787083776] = "<P_Heart> (Por que o servo mentiria? É um pouco estranho.) </>",
  [818107787083520] = "Tenho certeza... estou familiarizado com a voz do Mestre. O tom era dele. Servi ao Mestre por vários anos, não me lembraria mal...",
  [818107787083264] = "<P_Heart> (Eu tracei a cena antes da morte do Barão Hawkes; ele já havia desmaiado quando a segunda batida soou, então como ele poderia ter respondido ao servo?) </>",
  [818107787083008] = "Eu não entrei, realmente não! Não tenho ideia do que aconteceu...",
  [818107787082752] = "A voz dele soou um pouco estranha... mas não me atrevi a desobedecer às ordens, então <P_Yellow> deixei a bandeja na porta </> e saí primeiro.",
  [818107787082496] = "<P_Yellow> Não entre. </>",
  [818107787082240] = "A <P_Yellow> porta </> do quarto do mestre estava trancada. Bati por muito tempo, mas não houve resposta lá dentro. Depois de alguns segundos, o mestre disse de repente...",
  [818107787081984] = "Cerca de <P_Yellow> dez minutos </> depois, fui ao quarto entregar chá. Dr. Evan já estava na sala e me cumprimentou.",
  [818107787081728] = "E-eu? Às <P_Yellow> três horas </> , eu estava preparando o chá da tarde... porque o Mestre não tem comido muito ultimamente, mas mandou que o chá fosse entregue na hora certa.",
  [818107787081472] = "Senhor, o que você estava fazendo antes do caso acontecer?",
  [818107787081216] = "Normalmente não tenho oportunidade de falar com o Mestre. Quanto aos assuntos do Mestre... você deveria perguntar à Senhora e ao Sr. John.",
  [818107787080960] = "Do começo ao fim, só você esteve aqui curtindo essa farsa.",
  [818107787080704] = "Esse Beyonder item deixou o Barão ciente da anormalidade; ele descobriu que estava sendo observado e descobriu que algo estava escondido nesta mansão. Mas foi justamente por isso que atraiu uma certa existência especial, levando à morte do Barão.",
  [818107787080448] = "Alguém confundiu a hora da morte, desencadeou a anormalidade mental do Barão, distorceu a vontade do médico, fez do leal mordomo o assassino neste caso e deliberadamente deixou todos desconfiados.",
  [818107787079680] = "Esta memória... quem a colocou?",
  [818107787078912] = "Sim, por que... por que eu faria isso?",
  [818107787078656] = "Ajustei a dosagem do remédio; contanto que a dosagem estivesse errada, seu coração pararia a qualquer momento. Também fui eu quem trancou a porta, criando um mistério no quarto trancado.",
  [818107787078400] = "Admito... foi a minha mão que assassinou o Mestre.",
  [818107787078144] = "Você está encarregado da Medicina do Barão. Você envenenou o Barão enquanto entregava o remédio, fingiu a ilusão de que ele ainda estava vivo e até forjou a cena do crime para incriminar os criados.",
  [818107787077888] = "Sr. John, todas as pistas apontam para você no final.",
  [818107787077632] = "<P_Heart> (Ele parece se importar com o Barão.) </> Está tudo bem, Sr. Butler, por favor, aceite minhas condolências.",
  [818107787077376] = "Só que desta vez... eu... desculpe.",
  [818107787077120] = "Cuidei dele por tantos anos. Cada febre, cada palpitação, cada vez que ele acordava de um pesadelo... eu estava lá.",
  [818107787076864] = "O Mestre... o Mestre estava deitado ao lado da mesa naquele momento, e o chá estava derramado no chão. Corri e toquei sua mão",
  [818107787076608] = "A porta estava <P_Yellow> trancada </> por dentro. Fiquei muito preocupado, então chamei os criados para arrombarem a porta juntos.",
  [818107787076352] = "Então fui até a cozinha e pedi aos criados que preparassem lanches para o chá da tarde. Por volta das <P_Yellow> 15h20 </>, queria perguntar se o mestre se lembrava de sua consulta de acompanhamento, mas não importa como eu bati, não houve resposta.",
  [818107787076096] = "Cerca de <P_Yellow> dois minutos </> . Observei ele <P_Yellow> tomar o remédio </>, e sua respiração se estabilizou antes de me sentir aliviado para ir embora. Ele me disse para não incomodá-lo e disse que me ligaria quando se sentisse melhor.",
  [818107787075840] = "Ele não gosta que outros toquem em suas coisas... exceto eu.",
  [818107787075584] = "Ele teve febre alta quando tinha sete anos e eu cuidei dele por três dias e três noites. Desde então, tenho guardado o remédio para ele.",
  [818107787075328] = "A senhora saiu com raiva logo depois. Olhei para o relógio; eram <P_Yellow> três horas </>, e o Mestre de repente me chamou no quarto, dizendo que seu coração estava desconfortável.",
  [818107787075072] = "Às <P_Yellow> duas e cinquenta e cinco </>, eu estava na sala de jantar organizando os talheres. Naquela hora a Senhora estava discutindo com o Mestre... Eu deveria ter ido persuadi-los, mas o Mestre tem estado de mau humor ultimamente e não queria se comunicar com ninguém.",
  [818107787074816] = "O que você estava fazendo antes do caso acontecer?",
  [818107787074560] = "Detetive {Sr. {EM. |}}, não estou em condições de dizer muito sobre as circunstâncias específicas do caso; por favor, discuta isso com a senhora.",
  [818107787074304] = "Mas eu não fiz isso! Deve ter sido aquela coisa que o machucou! Deve ser!",
  [818107787074048] = "Eu odeio isso e odeio que os olhos do meu marido pareçam cada vez mais com um estranho!",
  [818107787073792] = "O assassino é você! Você já estava insatisfeito com o Barão Hawkes. Esta tarde, você teve outra grande discussão com ele por causa daquela antiguidade e, num ataque de impulso, decidiu acabar com a vida do Barão Hawkes!",
  [818107787073536] = "Mas ele... de repente ficou com muito frio ultimamente.",
  [818107787073280] = "Na minha opinião, ele é muito bom. Dr. Evan está mais nervoso com o corpo de Hawkes do que qualquer outra pessoa. Na semana passada, Hawkes sentiu dores no peito no meio da noite e correu sem nem vestir o casaco direito.",
  [818107787073024] = "Essa criança é tímida, mas muito honesta; ele até fica vermelho o dia todo se for pego relaxando.",
  [818107787072768] = "Se não fosse por ele, não consigo imaginar o que teria acontecido com Hawkes.",
  [818107787072512] = "Certa vez, os cavalos no campo de caça ficaram assustados e fora de controle, e foi John quem correu para salvar Hawkes! Hawkes não se machucou, mas John quebrou várias costelas e ficou muito tempo acamado antes de se recuperar...",
  [818107787072256] = "Muito bom. John assistiu Hawkes crescer desde criança e cuidou de Hawkes por trinta anos.",
  [818107787072000] = "Ficarei feliz em responder a qualquer dúvida que você tiver.",
  [818107787071744] = "Isso é tudo que sei. O mordomo e eu esperaremos lá fora para não atrapalhar sua investigação.",
  [818107787071488] = "Quando saí, ele ainda estava sentado à mesa tomando chá. Enquanto bebia, ele olhava para a porta, provavelmente esperando pelo Dr. Evan. Ele sofria de uma doença cardíaca e era hora de sua consulta de acompanhamento.",
  [818107787071232] = "Antes das <P_Yellow> três horas </> da tarde. Tivemos uma discussão na época e eu o aconselhei a se livrar daquela antiguidade, mas ele não quis ouvir.",
  [818107787070976] = "<P_Heart> (Uma antiguidade?) </> Quando foi a última vez que você o viu?",
  [818107787070720] = "Nervoso, hostil com todos que via e sempre sentia como se alguém estivesse escutando suas conversas.",
  [818107787070464] = "Sim. Desde que comprou uma antiguidade, ele se tornou cada vez mais anormal, não se comunicando com as pessoas e ficando o tempo todo no quarto.",
  [818107787070208] = "Senhora, tenho perguntas a lhe fazer. O Barão Hawkes tem agido de forma estranha ultimamente?",
  [818107787069952] = "Por favor, venha conosco, Detetive {Sr. {EM. |}}, o quarto é ali… por favor, você precisa descobrir a verdade.",
  [818107787069696] = "Ele desmaiou em um quarto trancado; foi o mordomo quem mandou as pessoas arrombarem a porta. A cena ainda é como era; Não deixei ninguém tocar em nada.",
  [818107787069440] = "Meu marido, o Barão Hawkes, morreu misteriosamente. Acredito que há mais sobre esse assunto, por isso convidei você aqui.",
  [818107787068672] = "Ainda quero acompanhar o David mais um pouco.",
  [818107787068416] = "Jovem, obrigado por me acompanhar nesta jornada.",
  [818107787068160] = "No entanto, devo lembrá-lo gentilmente: isso não é fácil Missão , mas é bastante interessante. Apreciá-lo.",
  [818107787067904] = "Pegue esta pistola e \"experimente\" Ele quando Ele ainda era pequenininho Beyonder, hehe...",
  [818107787067648] = "Faça-me um pequeno favor: cante aqui Seu nome honorífico para pôr fim aos resquícios daquela guerra divina.",
  [818107787066880] = "{Senhor. {EM. |}} quer experimentar a experiência do surf no meio do lago? Você definitivamente não vai se arrepender!",
  [818107787066624] = "{Senhor. {EM. |}}, quer experimentar uma experiência de corrida pelo mar de flores?",
  [818107787066368] = "{Senhor. {EM. |}}, quer ter uma experiência emocionante de surf no gelo e na neve?",
  [818107787065856] = "Ei, pronto para tentar surfar? As ondas do lago estão ótimas hoje, estou prestes a dar um passeio.",
  [818107787065600] = "Não observe apenas da costa; o vento no lago está bom, que tal surfar comigo?",
  [818107787065088] = "Eu posso sentir seu estado. Se você estiver disposto, posso lhe dar uma ajuda.",
  [818107787064832] = "Olhe para mim, deixe-me ensiná-lo a dissipar a escuridão.",
  [818107787064576] = "Nesta terra encharcada de malícia, você precisa de uma âncora para se reencontrar.",
  [818107787064320] = "Seu corpo espiritual está sendo despedaçado, carregado com muitos fragmentos de loucura.",
  [818107787064064] = "Tudo aqui não vai realmente tirar a sua vida, mas o horror que eles criam é real.",
  [818107787063808] = "Ganhe esta aposta, para nós também...",
  [818107787063552] = "Creak... pegue essa arma em meus braços, você vai precisar dela...",
  [818107787062784] = "Espero que você esteja falando a verdade...",
  [818107787062528] = "De jeito nenhum! Separei-me de Matthew logo depois de discutirmos. Olha, honestamente estou vendendo souvenirs sozinho agora, é... é um negócio legítimo!",
  [818107787062272] = "Ah, então continue enganando os outros?",
  [818107787062016] = "Ha, haha, você sabe de tudo... vamos ficar empatados. Olha, você não perdeu nada...",
  [818107787061760] = "Bela atuação.",
  [818107787061504] = "Ah, você parece familiar.",
  [818107787061248] = "{Senhor. {EM. |}}, olha essa taça de prata! O primeiro Barão Lamud—",
  [818107787060992] = "Esta é a única chance. Vá, corte as falas dele, uma por uma.",
  [818107787060736] = "Depois de entrar mais tarde, preste atenção nas <P_Yellow> partes vermelhas especiais </> nos fanáticos; essas são suas <P_Yellow> fraquezas </>.",
  [818107787060480] = "Enquanto a fé permanecer, o Lobo Dourado não morrerá. Elimine todos os fanáticos e o Lobo Dourado não será diferente de uma pessoa comum.",
  [818107787060224] = "Bonnie não mentiu para nós - o verdadeiro poder do Lobo Dourado vem dos <P_Yellow> fios vermelhos </> desses fanáticos.",
  [818107787059968] = "<P_Heart> (Passando uma pequena nota) </> ... Um colega investigou o paradeiro do Lobo Dourado hoje.",
  [818107787059712] = "…Os detalhes não são importantes! A questão é estratégia!",
  [818107787059456] = "…Uma avalanche também enterrará o seu próprio povo.",
  [818107787059200] = "A história vai mudar neste momento! Intis unificará o Continente Norte!",
  [818107787058944] = "Com canhões! Bombardeie a montanha para provocar uma avalanche! Enterre todos os inimigos!",
  [818107787058688] = "Capturar facilmente? Como você captura facilmente esta montanha?",
  [818107787058432] = "Vou escrever uma obra-prima militar! Argumentando que Intis deveria aproveitar a guerra entre Loen e Feysac para facilmente capturar Hornacis e invadir Loen!",
  [818107787058176] = "Pesquisando o quê?",
  [818107787057920] = "Olá, sou da Academia Militar do Intis. Estou fazendo uma pesquisa de campo.",
  [818107787057664] = "Deusa, dane-se essa persistência! Nunca mais subirei uma montanha se não houver linguiça frita à venda!",
  [818107787057408] = "Espere um pouco mais, estaremos no acampamento em breve...",
  [818107787057152] = "Sério, eu vou voltar. Esta não é uma montanha que um cavalheiro de férias deva escalar.",
  [818107787056896] = "Vou recitar a segunda estrofe: Lago gelado! Você é como um espelho branco! Limpo e puro!",
  [818107787056640] = "Ele é o poeta de nicho que mais admiro. Suas obras são simples e comoventes, mas infelizmente poucas pessoas conseguem apreciá-las... neste mundo inquieto!",
  [818107787056384] = "Olho acordado?",
  [818107787056128] = "A escola Dakeye, a grande Dakeye!",
  [818107787055872] = "Que escola de poesia é essa?",
  [818107787055616] = "Lago gelado! Você é amplo e vasto! Você é frio e brilhante!",
  [818107787055360] = "Quando olharam para a terra... será que alguma vez pensaram que também se tornariam uma ponte?",
  [818107787055104] = "Um... macaco branco envolto em uma estranha pele de fibra?",
  [818107787054848] = "Diante dos restos dessas feras gigantes... o que sou eu?",
  [818107787054592] = "Sim, o tempo está muito bom hoje, haha...",
  [818107787054336] = "N-nada! Estávamos discutindo... discutindo o tempo!",
  [818107787054080] = "De quem você está falando?",
  [818107787053824] = "Shh... fale baixo! O chefe tem ouvidos aguçados! Dizem que a igreja deles gosta de intelectuais...",
  [818107787053568] = "Desde que ela lavou as mãos da pirataria, ela não tem sido ela mesma... ela costumava ser uma pirata impressionante.",
  [818107787053312] = "Só porque ele é jovem e bonito? Já roubamos tantos garotos bonitos antes e nunca a vi amolecer.",
  [818107787053056] = "O que você acha que chefe vê naquele garoto?",
  [818107787052800] = "Não importa o que aconteça, estarei com você.",
  [818107787052544] = "Tolo, eu te apoio porque acredito no seu talento, não pelo professor que você é.",
  [818107787052288] = "Após esta viagem arqueológica, minha tese de doutorado estará resolvida. Assim que eu passar na entrevista do professor associado... posso lhe proporcionar uma vida melhor.",
  [818107787052032] = "Tudo bem, só podemos dizer isso; ainda temos que acender esse maldito fogo!",
  [818107787051776] = "Eles passaram por algumas... mudanças ruins. Parece que você também é... hmm? Você deve entender.",
  [818107787051520] = "Ah, ah, quero dizer... o que é perigoso é... o acampamento, o acampamento atual, entendeu?",
  [818107787051264] = "Ahem, eu disse... se não houver nada, fique longe daquele acampamento ali.",
  [818107787051008] = "Na verdade, você está relaxando.",
  [818107787050752] = "Ahem, à frente está o acampamento do Sr. Barnaby. Estamos vigiando os arredores para garantir a segurança do acampamento.",
  [818107787050496] = "<P_Heart> (O aroma do óleo essencial da Flor da Meia-Noite... Um Ritual Mágico de oração à Deusa da Noite foi realizado aqui uma vez?...) </>",
  [818107787050240] = "Apenas um caçador local, por favor, saia; não há realmente nada para ver aqui.",
  [818107787049984] = "Havia... uma fera por perto, nós apenas... a caçamos! Você deveria sair rapidamente!",
  [818107787049728] = "Não venha! Não é seguro aqui!",
  [818107787049472] = "Se você o vir... por favor, diga-lhe que sua mãe, Lady Charlene, esteve rezando no sopé da montanha, rezando para que a Deusa o protegesse...",
  [818107787049216] = "Ele não estava em bom estado... confuso e mal-humorado. Aconselhei-o a não ir, mas ele disse que este material só poderia ser encontrado nestas montanhas.",
  [818107787048960] = "Johnny disse que estava vindo aqui para encontrar algum tipo de ‘material’, e então não houve notícias...",
  [818107787048704] = "O nome dele é Johnny, cabelo loiro, ainda muito jovem, um médico decente... ele usa um anel com crista de leão, esse é o emblema da nossa família.",
  [818107787048448] = "Como é o seu filho?",
  [818107787048192] = "Bom viajante, você viu meu filho?",
  [818107787047936] = "Aquele cavaleiro ali morreu como deveria. Pelo menos alguém se lembra dele.",
  [818107787047680] = "Eu só queria ver minha Flora e a pequena Amy, mas até o lago está me rejeitando.",
  [818107787047424] = "Este lago gelado era originalmente o local de descanso que escolhi quando o vi no meio do verão... mas agora está congelado.",
  [818107787047168] = "Sim. Achei que me sentiria aliviado depois de matar meu inimigo, mas agora me sinto vazio por dentro, como se a última razão para permanecer neste mundo tivesse acabado.",
  [818107787046912] = "Mas você não parece muito bem.",
  [818107787046656] = "Eu fiz aquele bastardo que fraudou minha fábrica e machucou minha família afundar em Midseashire para sempre... Tudo acabou.",
  [818107787046400] = "Não há nada a esconder; Acabei de terminar uma vingança.",
  [818107787046144] = "Sim... sim... desculpe, senhor... vamos nos apressar...",
  [818107787045888] = "Se você atrasar o progresso novamente, não espere receber o pagamento integral!",
  [818107787045632] = "Você entrega sempre que a equipe da expedição científica marca o horário!",
  [818107787045376] = "Sinto muito... sinto muito... a estrada era muito difícil de viajar... e alguém se machucou...",
  [818107787045120] = "Duas horas inteiras atrasado! Vocês, caipiras, sabem o que significa pontualidade?",
  [818107787044864] = "São alimentos e instrumentos para a equipe da expedição científica. Não pergunte; isso não é algo que deveríamos saber.",
  [818107787044608] = "O que há dentro da caixa?",
  [818107787044352] = "Agora estou... participando das ofensas daquelas pessoas... e fui punido...",
  [818107787044096] = "O Reino da Noite... lendas antigas... aqueles que desrespeitam a noite... serão todos amaldiçoados...",
  [818107787043840] = "Não... me escute... tem alguma coisa nas montanhas... eu não deveria ter aceitado esse trabalho... é um desrespeito às montanhas...",
  [818107787043584] = "Esqueça a caixa! Sua vida é mais importante!",
  [818107787043328] = "As coisas dentro daquela caixa... se quebrarem, minha família inteira não terá condições de pagar por elas...",
  [818107787043072] = "Não se mova! Seu osso pode estar quebrado; se movimentar vai piorar as coisas!",
  [818107787042816] = "Sibilo... isso dói! Tome cuidado! Não danifique a caixa!",
  [818107787042560] = "Se você não tem carro, há um antigo na fábrica que você pode pegar emprestado. Só não estrague tudo.",
  [818107787042304] = "Vá para a linha de largada e prepare-se, começaremos em breve!",
  [818107787042048] = "O que você me diz, quer tentar? O perdedor tem que pagar pelos lanches noturnos!",
  [818107787041792] = "Nosso distrito fabril está organizando uma corrida de rua hoje. Uma volta decide o vencedor; sem apostas, apenas uma corrida para ver quem consegue deixar os outros no retrovisor primeiro.",
  [818107787041536] = "Novo aqui? Você veio na hora perfeita.",
  [818107787041280] = "<P_Yellow> A hora correta é </> ... <P_Yellow> Anoitecer </> ...",
  [818107787041024] = "Eles costumavam ser como vocês, todos... convidados de honra.",
  [818107787040768] = "Rangido... Não se preocupe comigo. O tempo no palco foi adulterado por esse roteiro quebrado... Rangido...",
  [818107787040512] = "Como você ficou assim? Seus braços são todos de madeira...",
  [818107787040256] = "Depois de encontrá-lo, tome cuidado. Aquele lugar... faz as pessoas esquecerem quem são.",
  [818107787040000] = "Diz-se que apenas <P_Yellow> aqueles que são convidados </> podem ver a entrada. Mas não sei que porta específica é; você terá que encontrar sozinho.",
  [818107787039744] = "Bonnie é a mestre lá; ninguém jamais viu sua verdadeira face. Lily é sua vice, gerenciando tudo por dentro e por fora.",
  [818107787039488] = "<P_Yellow> Rose Paradise </> —Território de Bonnie, escondido nesses becos do Distrito Leste.",
  [818107787039232] = "Suspiro, o que devo fazer? É muito estranho dizer isso diretamente...",
  [818107787038976] = "Gostaria de iniciar sua primeira negociação agora?",
  [818107787038720] = "<P_Heart> (Sussurrando) </> Você... venha aqui por um segundo... eu tenho algo para você...",
  [818107787038464] = "Depois de entrar, aproveite aqueles \"fantoches\" trabalhadores no palco.",
  [818107787038208] = "Hehe... Convidado de honra, você tem outro ingresso \"especial\".",
  [818107787037952] = "<P_Heart> (Entrega um pequeno bilhete) </> ... Encontrei-o no cadáver de um colega.",
  [818107787037696] = "O futuro do castelo é brilhante!",
  [818107787037440] = "Depois de avançar e atualizar o castelo para o nível 3, poderemos construir nossa própria oficina. Estes recursos abundantes podem ser carregados em comboios e utilizados no comércio ferroviário.",
  [818107787037184] = "Meu Senhor, a expansão do castelo está completa! Agora você pode escolher melhores itens colecionáveis ​​e móveis e, em nome do dono do castelo, convidar amigos ou visitar outros castelos.",
  [818107787036928] = "Tchau, tchau! Novo Rei da Dança, novo Rei da Dança!",
  [818107787036672] = "A partir de hoje, eu, o novo “Rei Supremo do Breakdance”!",
  [818107787036416] = "Ooga, perdido, eu, passos de dança, não consigo acompanhar, woo woo",
  [818107787036160] = "Uga, grande, fale, então vamos dançar! Perdedor! Come, podre, banana! Uga!",
  [818107787035904] = "Você, Rei da Dança? Eu sou o “Rei Supremo do Breakdance”.",
  [818107787035648] = "Cheep, território do Rei da Dança! Território do Rei da Dança!",
  [818107787035392] = "Você, de onde, daqui, território do “Rei Supremo do Breakdance”, ooga.",
  [818107787035136] = "Velho senhor, o vento e a neve estão muito fortes aqui, por que você está aqui sozinho?",
  [818107787034880] = "Por que a estaca de madeira ficou tão curta? É quase como sentar no chão.",
  [818107787034624] = "David, esqueci, quando você se apaixonou por Aslan...",
  [818107787034368] = "Porém, tudo tem um preço. Caso você infelizmente falhe, então só posso te prejudicar transformando você em uma marionete também... Um negócio muito econômico, certo?",
  [180320712271872] = "Nenhum",
  [818107787034112] = "Não fique nervoso. Você está aqui por causa daquele pedido de ajuda, certo? Por favor, coloque-me no mecanismo à sua frente e eu o ajudarei a salvá-los.",
  [818107787033856] = "Um... roteiro falante?",
  [818107787033600] = "Bem-vindo ao seu lugar. Gentil convidado, você poderia se mover um pouco? Você quase esmagou minhas páginas.",
  [818107787033344] = "<P_Heart> (Quando você está prestes a se sentar...) </>",
  [818107787033088] = "<P_Heart> (Pressionar o botão faz um \"clique\" surdo, como o fechamento de uma ratoeira.) </>",
  [818107787032832] = "Olá, este é o meu ingresso.",
  [818107787031296] = "Oh? Você também tem interesse em dirigir? Prove suas habilidades para mim nesta estrada de montanha!",
  [818107787031040] = "Um caderno? A capa diz... \"Um guia itinerante para Lotus Town\"?",
  [818107787030784] = "…Ele adormeceu.",
  [818107787030528] = "Vá em frente, meu verdadeiro amor está em... ronco, ronco...",
  [818107787030272] = "Suspiro, então devo encontrar seu verdadeiro amor?",
  [818107787030016] = "Você faz perguntas de um ângulo muito complicado; você não é muito bom em conversar.",
  [818107787029760] = "Você chama sua própria noiva de bruxa?",
  [818107787029504] = "Amanhã é o dia do meu casamento, Emilia, minha linda bruxa com certeza vai ficar com raiva de novo—",
  [818107787028736] = "<P_Heart> (Suspiros) </> É mesmo? Por favor, leve-me para vê-los.",
  [818107787028480] = "Eles estavam esperando por você.",
  [818107787028224] = "Então não consegui encontrar a cidade novamente. Trinta anos completos se passaram antes que eu finalmente retornasse...",
  [818107787027968] = "Prometi levá-los em uma viagem e, pensando no itinerário, dei alguns passos extras com entusiasmo e saí sem querer.",
  [818107787027712] = "Jovem... Vim aqui quando era jovem e conheci três pessoas.",
  [818107787027456] = "Você é Godot? Mas ele não era um jovem...",
  [818107787027200] = "Você está procurando por mim?",
  [818107787026944] = "Posso perguntar se você conhece uma pessoa chamada Godot?",
  [818107787026688] = "Chegou o novo horário de chegada do Peer Shop. Reivindique cupons antes de fazer seu pedido e ganhe um pedido grátis após o pagamento. Não perca! \n(Participe do jogo Peer Team para obter Peer Emblems, que podem ser trocados por diversas recompensas.)",
  [818107787026432] = "<P_Heart> (Espere, uma pessoa viva, como ela pode dizer que está morta?) </>",
  [818107787026176] = "Por favor, pule você mesmo e eu serei libertado.",
  [818107787025408] = "Observe que esta não é uma observação superficial sobre o clima em um ambiente social –",
  [818107787025152] = "Vários holofotes acenderam ontem à noite, iluminando a noite como se fosse dia. Imediatamente depois, ouvi um tiro alto!",
  [818107787024896] = "Eu também! E eu não estava dormindo há muito tempo. Estava tão quieto lá fora antes de eu adormecer; Eu nem conseguia ouvir o som das carruagens.",
  [818107787024640] = "Eu estava dormindo no meio da noite ontem quando fui acordado por uma luz ofuscante do lado de fora da janela. pensei que fosse amanhecer...",
  [818107787024384] = "O fim desta direção é a sede da polícia... Ela fez isso de propósito.",
  [818107787024128] = "Havia uma jovem que parecia estar sendo perseguida por algum monstro. Ela nem olhou para onde estava indo e correu direto para a estrada principal.",
  [818107787023872] = "Senhor, você estava perto do rio ontem à noite? Você notou alguma coisa?",
  [818107787023616] = "Também ouvi dizer que no caminho para lá ontem à noite, o Capitão encontrou alguns gangsters que estavam lá para encontrar o assassino!",
  [818107787023360] = "É assim mesmo? Achei que fosse o vice-capitão! Ele até jurou que atiraria pessoalmente naquele assassino cruel.",
  [818107787023104] = "Vi o capitão carregar a arma e sair ontem à noite. Dizem que o Estripador também foi morto a tiros ontem à noite...",
  [818107787022848] = "Acontece que eu estava na metade da minha mudança de turno no meio da noite quando percebi que havia esquecido meu mapa e minha arma, então corri de volta por onde vim. Quando voltei para pegar minhas coisas, vi que o Estripador ainda estava no mesmo lugar, sussurrando para outra pessoa.",
  [818107786798848] = "Senhor, permita-me explicar formalmente: a Câmara de Comércio de Tingen está otimista sobre o potencial deste território e está muito disposta a confiar-lhe os direitos de operação de frete desta ferrovia.",
  [818107787022080] = "Irmão, você está de guarda há um bom tempo, não é? Houve algum movimento na floresta esta noite?",
  [818107787021824] = "Quem se importa com quem o deixou cair? Mas agora mesmo, enquanto eu rastreava pegadas nas profundezas da floresta, vi aquele Estripador de sobretudo comprido na clareira, andando ansiosamente em círculos, como se esperasse por alguém. Talvez esteja relacionado a isso.",
  [818107787021568] = "Eu também encontrei isso. Segui a direção de onde eles vieram para dar uma olhada, mas não peguei nenhuma fera. Em vez disso, encontrei o cartão de visita de um corretor de inteligência na grama.",
  [818107787021312] = "(A boca da marionete faz um rangido) É mau. Ao anoitecer, a floresta estava um caos total. Aquele grupo de presas espertas saiu correndo como se tivessem visto um fantasma, quase me derrubando.",
  [818107787021056] = "…Acabei de ver minha assistente incomodando alguém de sobretudo no cruzamento, não poderia ser…",
  [818107787020800] = "Nossa, sinto muito, grande detetive, não posso ajudá-lo com adivinhação agora, todos os meus pequenos adereços foram roubados.",
  [818107787020544] = "Tenho um problema que me incomoda há muito tempo e espero usar o poder de adivinhação . Mas é melhor ser rápido. Minha assistente fugiu assim que eles chegaram, não sei o que vai acontecer.",
  [818107787020288] = "Como ovos fritos todos os dias, não vi nenhum Godot.",
  [818107787020032] = "Garotinha, você viu uma pessoa chamada Godot?",
  [818107787019264] = "<P_Heart> (Conversa interna) </> Já perguntei o suficiente, é hora de voltar e contar a eles.",
  [818107787019008] = "Canto todos os dias, não vi nenhum Godot.",
  [818107787018752] = "Senhor, você viu uma pessoa chamada Godot?",
  [818107787017984] = "Devemos esperar por Godot.",
  [818107787017728] = "Não podemos, não vamos a lugar nenhum.",
  [818107787017472] = "Por que você não pode partir sozinho?",
  [818107787017216] = "Talvez, ontem, hoje, amanhã, eu não tenha acompanhado.",
  [818107787016960] = "…Você está esperando há muito tempo?",
  [818107787016704] = "Esperando por Godot juntos.",
  [818107787016448] = "E então, nos reunimos aqui.",
  [818107787016192] = "Ficamos muito emocionados e concordamos em viajar juntos.",
  [818107787015936] = "Ele disse que os trens em Backlund são muito longos e podem ir até a Montanha Nevada.",
  [818107787015680] = "Ele disse que Tingen tem um distrito universitário e que você pode voar acima das nuvens em um dirigível.",
  [818107787015424] = "Ele disse que o mundo lá fora é vasto.",
  [818107787015168] = "Ele é um viajante, tão jovem quanto nós.",
  [818107787014912] = "Godot... quem?",
  [818107787014656] = "Este {Sr. {EM. |}}, posso perguntar se você conhece Godot?",
  [818107787014400] = "Finalmente, lembre-se, você deve estourar a cabeça do maldito Lobo Dourado!",
  [818107787014144] = "Passei muito tempo lidando com esses animais e já fui alvo. Não posso ficar aqui por muito tempo; depois que você terminar de atirar, fornecerei cobertura à distância.",
  [818107787013888] = "Só existe uma bala de prata, apenas uma! Não desperdice isso comigo!",
  [818107787013632] = "E mais uma coisa, você me escute—",
  [818107787013376] = "Pesquisei o local ontem, o rifle está montado, uma peça modificada com mira telescópica.",
  [818107787013120] = "Portanto, só há uma maneira: Bang! À distância , um tiro para matar. Não dê a eles a chance de reagir.",
  [818107787012864] = "Aquele cachorro Golden Wolf tem dois círculos de pessoas ao seu redor: jovens bandidos do lado de fora, seus seguidores obstinados do lado de dentro, grudados nele como sanguessugas sugadoras de sangue. Você se atreve a chegar perto? Você ficaria preso no chão antes mesmo de tocar a borda.",
  [818107787012608] = "Você finalmente rastejou. Ouça, não há tempo para bobagens.",
  [818107787012352] = "Vamos começar este duelo de moda.",
  [818107787012096] = "Desculpe, Beyonder , você não tem benefícios para reivindicar no momento.",
  [818107787011840] = "O destino nunca decepciona quem segue em frente. Sua marca pode já ter lhe trazido o presente do destino correspondente. Qual você gostaria de reivindicar desta vez?",
  [818107787011584] = "Droga, eu não esperava que eles alcançassem tão rápido. Hiss, levei um tiro, não consigo aguentar. Depende de você agora.",
  [818107787011328] = "Este lugar também não é seguro, vamos sair primeiro, chega de conversa.",
  [818107787011072] = "Droga, eu subestimei aqueles cães. A equipa de segurança do Conselho tem tentáculos por todo o lado.",
  [818107787010816] = "Não estou bêbado... realmente não estou bêbado... apenas tonto... ajude-me a observar... meu tesouro...",
  [818107787010560] = "Tão tonta... preciso ir... retocar a maquiagem...",
  [818107787010304] = "<P_Heart> (turvo) </> Você está... você está bem? Por que eu... vejo vocês dois...",
  [818107787010048] = "…Quantas bebidas você consegue acompanhar comigo?",
  [818107787009792] = "Às vezes tenho muita vontade de jogar isso fora, fingir que sou apenas uma mulher comum e encontrar alguém que possa beber comigo até nós dois desmaiarmos...",
  [818107787009536] = "Usá-lo significa que tenho que guardar este lugar para ela, beber aquelas bebidas que não quero beber por ela...",
  [818107787009280] = "Ela chama isso de recompensa, mas na verdade é uma corrente.",
  [818107787009024] = "<P_Heart> (Apontando para a mesa) </> Este distintivo... dado por Bonnie.",
  [818107787008768] = "Ha... estou começando a sentir isso agora.",
  [818107787008512] = "Parece que você também tem coisas que deseja esquecer. Caso contrário... você não estaria aqui.",
  [818107787008256] = "A maioria das pessoas vem aqui para esquecer...",
  [818107787008000] = "O primeiro copo é só para molhar a garganta.",
  [818107787007744] = "Beba comigo, deixe-me ver se você realmente mergulhou nisso.",
  [818107787007488] = "Nublado, como se... você estivesse pronto para esquecer alguma coisa.",
  [818107787007232] = "Mas... seus olhos agora são iguais aos das pessoas aqui.",
  [818107787006976] = "Tudo bem, não me importa o que você está investigando; todos aqui têm seus próprios segredos.",
  [818107787006720] = "<P_Heart> (risos) </> Você era quem estava no banheiro mais cedo, não era? E perto das cabines...",
  [818107787006464] = "Mas eu gostaria de terminar esta bebida sozinho. Por que você não vai procurar em outro lugar?",
  [818107787006208] = "Mas você... parece que você está morrendo de vontade de falar com alguém.",
  [818107787005952] = "Estar sozinho é muito bom. Não há necessidade de falar, não há necessidade de sorrir, não há necessidade de pensar no que dizer a seguir.",
  [818107787005696] = "Você é o mesmo. Usando uma máscara, realmente não importa o que você diz.",
  [818107787005440] = "São todas máscaras; você não os reconheceria mesmo se olhasse, então é melhor não fazê-lo.",
  [818107787005184] = "<P_Heart> (respira fundo) </> Hmph... que bem faria olhar?",
  [818107787004928] = "Você só sabe qual é o sabor do vinho quando ele está na sua boca. A descrição de qualquer outra pessoa é simplesmente supérflua.",
  [818107787004672] = "Parece que você tem uma língua prateada, mas aqui, apenas ser capaz de falar não é suficiente.",
  [818107787004416] = "Emparelhamento? Vinho é só vinho, não existe harmonizar ou não harmonizar.",
  [818107787004160] = "<P_Heart> (olha você de cima a baixo) </> ... Heh.",
  [818107787003904] = "Quando você souber o que realmente quer... talvez possamos conversar novamente.",
  [818107787003648] = "Além disso... os jogos lá em cima são muito mais perigosos que os de baixo. Do jeito que você está agora, você não sobreviveria à primeira noite, mesmo que subisse.",
  [818107787003392] = "Se você quer ir até lá, você perguntou à pessoa errada. Não estou encarregado de orientar ou fazer apresentações.",
  [818107787003136] = "Lá em cima? Você quer dizer a área VIP do segundo andar.",
  [818107787002880] = "Seja o que for, não estou com vontade de contar histórias esta noite. Beba o que quiser, mas as histórias... vamos guardá-las para a próxima vez.",
  [818107787002624] = "Você está interessado em metalurgia? Ou... apenas procurando um começo de conversa?",
  [818107787002368] = "Uma história? Nenhuma história. Apenas algo necessário para o trabalho.",
  [818107787002112] = "Não vou perguntar sobre o seu e você não pergunta sobre o meu. É mais seguro... assim.",
  [818107787001856] = "Mas não importa, cada um que vem aqui tem seus motivos.",
  [818107787001600] = "E você? Você também não parece estar aqui em busca de prazer.",
  [818107787001344] = "Sozinho? Na verdade. Há pessoas por toda parte, é só que... nós realmente não clicamos.",
  [818107787001088] = "Sente-se, você parece um pouco mais interessante do que essas pessoas...",
  [818107787000832] = "Novo aqui?",
  [818107787000576] = "Vá perguntar ao recepcionista na frente. Não tenho tempo para ser guia turístico.",
  [818107787000320] = "Afaste-se, não procure uma surra.",
  [818107787000064] = "A maneira como você olha para as pessoas é bastante irritante.",
  [818107786999808] = "Esta área está ocupada. Por favor, vá para outro lugar, obrigado.",
  [818107786999552] = "Sim, eu mesmo.",
  [818107786999296] = "Algo aconteceu?",
  [818107786999040] = "Não seja tímido e não fique muito sóbrio. A regra no segundo andar é: quanto mais imerso você estiver, mais fundo você vai. Se você ficar aí atordoado... cuidado para não ser comido.",
  [818107786998784] = "Vá para cima. O que está abaixo são apenas as preliminares... o verdadeiro show está acima.",
  [818107786998528] = "Você, você recebeu o distintivo.",
  [818107786998272] = "Mostre seu distintivo. Caso contrário, volte a beber o seu vinho e a sonhar os seus sonhos.",
  [818107786998016] = "O distintivo. O emblema da Rosa. Sem ele, você nem tocará no primeiro passo.",
  [818107786997760] = "Parar. O ar acima não é para as pessoas comuns respirarem.",
  [818107786997504] = "E... não fique olhando para ninguém por muito tempo. Aqui, a sensação de estar sendo observado não é agradável.",
  [818107786997248] = "Entre. Mas lembre-se, por dentro, estar bêbado é educado, enquanto estar sóbrio é uma ofensa. Não quebre as regras.",
  [818107786996992] = "Hmm... parece que você finalmente encontrou seu estado de espírito.",
  [818107786996736] = "Vá tomar alguns drinks, dance um pouco, não decepcione todo mundo. Quando seus olhos estiverem iguais à luz aqui, venha e tente novamente.",
  [818107786996480] = "Você parece... muito sóbrio; você não parece alguém que pertence aqui...",
  [818107786996224] = "Este hóspede, esta é uma área privada.",
  [818107786995968] = "Siga meu ritmo, não pense... apenas... sinta.",
  [818107786995712] = "Este convidado, gostaria de compartilhar uma dança comigo?",
  [818107786995456] = "Muito bem, sua bebida estará pronta.",
  [818107786995200] = "Olá, o que você gostaria de ter?",
  [818107786994944] = "Vamos, vamos continuar!",
  [818107786994688] = "De volta? Parece que você ainda não se satisfez.",
  [818107786994432] = "Ninguém pode mais despertar meu interesse.",
  [818107786992896] = "É realmente triste, mas isso é arte, não é?",
  [818107786992640] = "Parece que um poste de luz iluminou esta bela jovem e também iluminou este trágico assassinato.",
  [818107786992384] = "A escuridão é dilacerada... ruge como uma fera presa...",
  [818107786992128] = "e levar adiante este magnífico plano de assassinato.",
  [818107786991872] = "Vá em frente, ilumine um pouco este lugar,",
  [818107786991104] = "Saia rapidamente.",
  [818107786990848] = "Parabéns por fazer a escolha verdadeiramente correta.",
  [818107786990592] = "Para um Estripador, é um lugar onde é fácil ter pesadelos.",
  [818107786990336] = "Mas se você quiser um final diferente, talvez você possa tentar um lugar diferente,",
  [818107786990080] = "Não há ninguém por aqui e é local frequente de homicídios; já apareceu algumas vezes no jornal Honest Man.",
  [818107786989824] = "E se ele não estivesse aqui, como você escolheria...",
  [818107786989568] = "Como ele escolheria?",
  [818107786989312] = "Um é um Estripador cruel, o outro é uma jovem gentil e inocente.",
  [818107786989056] = "Fugir daqui para o oeste é um beco sem saída; seguir para o leste leva a um mercado movimentado.",
  [818107786988032] = "Quero dizer, o final dele.",
  [818107786987776] = "Não restam problemas difíceis aqui, apresse-se e conheça o seu...",
  [818107786987520] = "Que tipo de papel o Estripador está desempenhando agora? Do que se trata realmente...",
  [818107786987264] = "E rugir com raiva quando for levado a uma situação desesperadora.",
  [818107786987008] = "Eles rugem com entusiasmo quando atacam suas presas,",
  [818107786986752] = "Existem muitas feras ferozes nas florestas primitivas de Loen.",
  [818107786986496] = "Talvez o Estripador também não tenha uma pessoa nobre para fornecer carvão em tempo de neve.",
  [818107786986240] = "Um dia, quando estava nevando e fazendo frio, o Rei ordenou que uma grande quantidade de carvão fosse dada aos órfãos e aos pobres.",
  [818107786985984] = "Diz-se que o Rei de Loen tem o povo no seu coração,",
  [818107786799104] = "Você pode conduzir o comércio entre várias estações por meio de estratégias razoáveis ​​de compra e venda. A negociação pode acumular bilhetes da Câmara de Comércio, que eventualmente serão convertidos em bens do castelo.",
  [818107786985216] = "Avançar sempre que houver injustiça.",
  [818107786984960] = "Segurando uma espada, montando um cavalo branco,",
  [818107786984704] = "Meu favorito é o Cavaleiro Espada dos Arcanos Menores,",
  [818107786984448] = "As cartas de tarô são muito populares recentemente.",
  [818107786984192] = "Uh... claro, ela não tem nada a ver com esta peça.",
  [818107786983936] = "Talvez ela seja filha de alguma família.",
  [818107786983680] = "Mãos delgadas, pescoço de cisne.",
  [818107786983424] = "A protagonista da performance é uma bela senhora, uma senhora gentil.",
  [818107786983168] = "Você sabia que há uma apresentação no parque durante o dia?",
  [818107786982912] = "Se você sabe o que será realizado a seguir, vá para a sua posição e faça a pose para o início da apresentação.",
  [818107786982656] = "Diz-se que ele também tem um hobby pervertido: toda vez que comete um crime, tira o intestino das pessoas.",
  [818107786982400] = "Embora tenha matado inúmeras pessoas, ele nunca foi preso pela polícia.",
  [818107786982144] = "Um pervertido que gosta de estripar as pessoas.",
  [818107786978304] = "<P_Heart> (Eles estão incomodando aquela garota? Suba e ajude-a!) </>",
  [818107786978048] = "Garota fedorenta, não me culpe por ser indelicado se você continuar incomodando!",
  [818107786977792] = "Eu realmente não posso esperar mais!",
  [818107786977536] = "Mas já procurei em vários lugares... não há adivinhos adequados...",
  [818107786977280] = "Tenho um assunto urgente em relação à minha filha que precisa de adivinhação !",
  [818107786974720] = "Finja por um momento.",
  [818107786974464] = "Hum? Nada. Algo está errado, vamos tentar ativar Visão Espiritual .",
  [818107786974208] = "O Barão está olhando para aquele canto. O que há?",
  [818107786973952] = "Seus olhos ocasionalmente varriam uma determinada direção – sem olhar para as pessoas, como se confirmasse algo.",
  [818107786971648] = "Droga, como uma casa ancestral tão assombrada poderia ser vendida?",
  [818107786971392] = "Obrigado por ter vindo, estou ansioso para nosso próximo encontro.",
  [818107786971136] = "Quer experimentar outras bebidas especiais?",
  [818107786970880] = "Isso fará com que as pessoas vejam coisas que normalmente não veem. Eu sugiro que você saboreie lentamente.",
  [818107786970624] = "Esta taça de vinho carrega uma aura antiga. Quanto ao que é... desculpe, tenho que manter isso em segredo.",
  [818107786970368] = "Ah, um convidado corajoso.",
  [818107786970112] = "Só não beba muito, os sonhos podem se tornar muito “reais”.",
  [818107786969856] = "Adequado para quem quer esquecer temporariamente o amanhã ou procura o passado.",
  [818107786969600] = "Esta é uma escolha nostálgica. O aroma de casca de laranja e canela irá ajudá-lo a relaxar.",
  [818107786969344] = "Talvez isso permita que você se lembre facilmente de algumas coisas importantes.",
  [818107786969088] = "Você só precisa adicionar alguns “ingredientes secretos” especiais ao gin para fazer o líquido brilhar como um céu estrelado.",
  [818107786968832] = "Preparar esta bebida requer concentração especial, e quem a bebe também precisa.",
  [818107786968576] = "Hoje são três drinks especiais para você escolher. Eles são 'Water of Memory', 'Deep Sleep' e 'Walk Under the Moon'.",
  [818107786967808] = "Quer sejam verdadeiros ou falsos, é melhor deixar alguns mistérios desconhecidos do que conhecidos.",
  [818107786967552] = "Quem sabe ter muita curiosidade às vezes não é um bom hábito.",
  [818107786967296] = "Realmente? Então, na história, por que suas barrigas estavam redondas e salientes?",
  [818107786967040] = "Não tenha medo, é apenas uma história de terror.",
  [818107786966272] = "Eles me cercaram, se aproximaram de mim... assim como a distância entre você e eu agora...",
  [818107786966016] = "Contanto que você se ajoelhe e ore a Ele com devoção à noite, você poderá receber a 'bênção' da vida e nunca mais passar fome.",
  [818107786965760] = "Pedi-lhes comida. Essas pessoas disseram que a comida é Seu presente.",
  [818107786965504] = "Como se tivessem comido demais, seus corpos parecidos com palitos encimados por uma barriga redonda e protuberante.",
  [818107786965248] = "Sim. Homens, mulheres, idosos, crianças...",
  [818107786964992] = "Todos?",
  [818107786964736] = "Naquela época, havia uma seca na fronteira e muitas pequenas aldeias sofriam de fome. Mas todos nesta aldeia tinham barriga protuberante.",
  [818107786964480] = "Há alguns anos, na fronteira, entrei acidentalmente numa aldeia chamada 'New Sprout'.",
  [818107786964224] = "Ah, há uma que nunca contei em público porque é muito... misteriosa.",
  [818107786963968] = "O que não falta aqui são histórias. Deixe-me pensar.",
  [818107786963712] = "Decifrá-lo pode transformar alguém em deus em um único passo... haha, estou brincando.",
  [818107786963456] = "E este caderno, diz-se, é uma cópia de um caderno antigo, contendo algumas informações.",
  [818107786963200] = "Existem conchas do Arquipélago Ocidental; se você colocá-los no ouvido, poderá ouvir o som do vento.",
  [818107786962944] = "Existem pedras charmosas do Continente Sul que dizem trazer boa sorte.",
  [818107786962688] = "Dê uma olhada, tem de tudo um pouco aqui.",
  [818107786962432] = "Você quer ver meus produtos? Ou ouvir uma história?",
  [818107786962176] = "Acontece que viajei para mais lugares e vi coisas estranhas.",
  [818107786961920] = "Bom dia, sou Fat Harry, um comerciante comum.",
  [818107786961664] = "Deixe-me fingir que estou saboreando o vinho.",
  [818107786961408] = "Se você dá algo, você recebe algo.",
  [818107786961152] = "Toda promessa tem validade e toda troca é baseada na confiança.",
  [818107786960896] = "No entanto, estou muito bem agora. Eu mantenho a justiça das transações aqui e acredito que é isso que Deus realmente deseja.",
  [818107786960640] = "Não, eu deveria ser o único a pedir desculpas. Esta não é uma história que faz as pessoas sorrirem.",
  [818107786960384] = "Lamento muito ouvir essa história.",
  [818107786960128] = "Agora sou Solo Carter.",
  [818107786959872] = "Um antigo colega ajudou-me e fugi para Tingen para me esconder durante dois anos, depois fixei-me em Backlund.",
  [818107786959616] = "Um ‘acidente’ foi arranjado para mim, e o antigo eu, Solo Black, ‘morreu’ na missão.",
  [818107786959360] = "Você acertou. É uma pena que no final fui eu quem foi a 'sujeira'.",
  [818107786959104] = "Você expôs aquele bispo à igreja?",
  [818107786958848] = "Descobri que o bispo cobiçava o dinheiro dos crentes; isso era uma sujeira intolerável.",
  [818107786958592] = "Certa vez, servi a Igreja do Eterno Sol Ardente; Eu era jovem na época, acreditando erroneamente que a glória do sol poderia iluminar todas as trevas.",
  [818107786958336] = "Haha, não tenha medo. Quero dizer Solo no documento de identificação.",
  [818107786958080] = "Uma pessoa morta?!",
  [818107786957824] = "Afinal, sou uma pessoa que já morreu.",
  [818107786957568] = "O passado? Sinto muito, não há nenhuma história para diverti-lo.",
  [818107786957312] = "Tudo no destino está marcado por um preço; depende apenas do custo que você escolher.",
  [818107786957056] = "Embora precise suportar alguns impulsos incontroláveis, a vida é estável e a família é harmoniosa.",
  [818107786956800] = "Foi assim que me tornei quem sou hoje, {Sr. {EM. |}}.",
  [818107786956544] = "Felizmente, a Deusa não me abandonou. Uma faxineira que passava me ajudou e uma freira da igreja me apresentou um novo emprego.",
  [818107786956288] = "Estava cheio de símbolos de fantasmas que eu não conseguia entender, mas quase morri no esgoto por causa disso.",
  [818107786956032] = "Eu 'peguei' uma informação de um homem rico. Meu Deus, eu realmente não posso mencionar tudo isso de novo.",
  [818107786955776] = "Mas uma mudança aconteceu logo depois.",
  [818107786955520] = "Como podem as coisas feitas por uma pessoa culta ser chamadas de “roubo”? Eu estava apenas 'pegando' eles.",
  [818107786955264] = "Ah, não coloque isso de maneira tão deselegante.",
  [818107786955008] = "Você se tornou um ladrão?",
  [818107786954752] = "Balcões, cofres, bolsos alheios... quem sabe onde estaria hoje.",
  [818107786954496] = "Talvez. Porque naquela época também era difícil para mim controlar minhas mãos.",
  [818107786954240] = "Parece que você estava indo bem?",
  [818107786953984] = "Naquela época, em todo o mercado de antiguidades de Backlund, não havia ninguém que não conhecesse Albert 'Olho de Águia'.",
  [818107786953728] = "Esta mudança foi certamente uma coisa boa; Eu poderia facilmente sentir quais itens eram mais valiosos.",
  [818107786953472] = "Um encontro especial, você entende, as engrenagens do destino começaram a girar.",
  [818107786953216] = "Até que um dia me tornei particularmente sensível ao “valor”.",
  [818107786952960] = "Eu costumava ser honesto e confiável, o contador mais discreto do Banco Bavat.",
  [818107786952704] = "Quer saber como entrei nesse ramo de trabalho? Essa é uma longa história.",
  [818107786952448] = "Obrigado por ouvir, desejo-lhe um bom dia.",
  [818107786952192] = "Você tem alguma outra necessidade?",
  [818107786951936] = "Oferecerei a você uma variação única; você nunca saberá qual será a próxima nota.",
  [818107786951680] = "Ah, um convidado com espírito aventureiro.",
  [818107786951424] = "Ou talvez abrace-se e desfrute de um momento de tranquilidade.",
  [818107786951168] = "Tal peça é adequada para pensar sozinho, ajudando a resolver pensamentos caóticos.",
  [818107786950912] = "Como a luz do sol brilhando através de uma janela de vidro, faz com que as pessoas esqueçam suas preocupações e se concentrem no prazer do presente.",
  [818107786950656] = "Esta é uma melodia edificante.",
  [818107786950400] = "Gostaria de ouvir uma música e sentir esse dia maravilhoso?",
  [818107786950144] = "Olá, Violet está ao seu dispor.",
  [818107786949888] = "<P_Heart> (Ele está fingindo ser um cogumelo!) </>",
  [813709740348672] = "12 novas folhas da árvore do chá Snowy Mountain...",
  [818107786949632] = "<P_Heart> (Seus globos oculares estão se movendo ligeiramente; ele está pensando em algo e está muito lúcido.) </>",
  [818107786949376] = "<P_Heart> (Deixe-me ver, ele está segurando a cabeça com as duas mãos, enterrando o queixo nos joelhos, como se estivesse resistindo ao mundo exterior.) </>",
  [813709740299520] = "Como amigo dele, sou um pouco negligente em meus deveres. Veja, não consigo encontrá-lo novamente agora.",
  [813709740108544] = "Mas quando pensei em ter muitos companheiros comigo, não tive medo nenhum.",
  [818107786949120] = "<P_Heart> (Ele parou de falar...) </>",
  [818107786948864] = "Um cogumelo?",
  [813709740047616] = "Por que?",
  [818107786948608] = "Eu sou um cogumelo.",
  [818107786948352] = "Você precisa de alguma ajuda?",
  [818107786948096] = "Sob a luz, as lentes refratavam um brilho incomum - elas não eram vidro comum, mas polidas a partir de um cristal especial, com espiritualidade extremamente sutil fluindo em seu interior.",
  [818107786947840] = "Albert ficou na beira do corredor, com o corpo tremendo ligeiramente, tirando os óculos para enxugar o canto dos olhos.",
  [818107786947584] = "Por segurança, você também deve pegar um mosquete e ajudar XX no assassinato. Se a situação for impossível, priorize a sua própria segurança.",
  [818107786947328] = "É assim mesmo? Perfeito. Eles definitivamente não vão adivinhar que temos algo parecido com um mosquete, o que facilitará nossa operação.",
  [818107786947072] = "Que Beyonder é Advogado Caminho Sequência X, com habilidade XXX; a área de fala foi proibida de usar Beyonder poderes.",
  [818107786946816] = "Você descobriu a capacidade disso Beyonder ?",
  [818107786946560] = "Tudo bem, espere aqui pelas minhas notícias.",
  [818107786946304] = "Diz-se que para este discurso a Equipa de Segurança da Câmara Municipal chegou a enviar um Beyonder . Eu preciso que você vá e faça uma cena primeiro para descobrir a habilidade disso Beyonder .",
  [818107786946048] = "Você veio; esses mentirosos da equipa de segurança do Conselho vão usar discursos para enganar os cidadãos e obter novamente apoio. Espero aproveitar esta oportunidade para assassinar o mentiroso que fez o discurso.",
  [818107786945792] = "Você gostaria de fazer um tour, {Sr. {EM. |}}?",
  [818107786945536] = "Nossa rota turística abrange os principais nós de transporte de norte a sul, como a Igreja do Rio e do Mar, o Distrito Universitário e a Rua Cruz de Ferro, economizando trabalho braçal e permitindo que você aproveite os vários encantos da cidade de Tingen.",
  [818107786943232] = "Estendendo a mão para testá-lo, o baú do tesouro não se move – está trancado.",
  [818107786942976] = "Há mais alguma coisa que você precisa saber?",
  [818107786942720] = "Sem pressa, você tem muito tempo para se preparar antes que a cortina do palco suba.",
  [818107786942464] = "Este festival acontece paralelamente à liga, com quatro rodadas e oito semanas por temporada. A primeira semana de cada rodada terá uma partida, e a segunda semana de cada rodada terá duas partidas. Cada partida terá sua escalação definida com dois dias de antecedência, e o presidente e o vice-presidente terão a oportunidade de ajustar a ordem da batalha antes do início da partida.",
  [818107786942208] = "“O Fantasma da Ópera” já foi o palco privado de uma Bruxa misteriosa, onde ela realizou inúmeras performances brilhantes e comoventes. Hoje, o palco está aberto a todos os grandes clubes e é o melhor lugar para mostrar a elegância de um clube. O vencedor não só ganhará a glória de estar no centro das atenções, mas também receberá um presente do misterioso “Fantasma”.",
  [818107786941952] = "\"O Fantasma da Ópera\" é a gala de moda de maior prestígio de Backlund.",
  [818107786941696] = "O que mais você gostaria de saber?",
  [818107786941440] = "Os pontos são calculados com base na classificação de sobrevivência, número de mortes e tempo de sobrevivência das projeções fantasmas. Os jogadores mais bem classificados podem ganhar títulos como ‘Brawl Champion’, e peões com dados excelentes também podem receber recompensas de títulos como ‘Ro’s Express’ ou ‘Light of the Traitor’.",
  [818107786941184] = "Cada briga tem 32 projeções fantasmas participantes e dura 5 minutos. Você pode ganhar pontos matando e sobrevivendo. Se não houver vencedor aos 4 minutos e 30 segundos, os pontos da classificação final serão determinados.",
  [818107786940928] = "Como 'Invocador', você pode selecionar projeções fantasmas adequadas para se registrar na batalha. Cada projeção fantasma só pode lutar uma vez, então escolha com cuidado. Você pode se inscrever para as sessões subsequentes com antecedência, sem necessidade de estar online o tempo todo.",
  [818107786940672] = "As inscrições abrem todas as terças e quintas-feiras às 12h, e a briga começa oficialmente às 19h às 20h30. A programação é determinada pelo número de participantes da sessão anterior (a primeira sessão é baseada no número de associados do clube).",
  [818107786940416] = "Realmente não vem para uma rodada? Tudo bem... sempre que você sentir vontade de brigar, lembre-se de vir me encontrar!",
  [818107786934016] = "Ele tem ideias melhores para o design do plano de fundo do palco.",
  [818107786933760] = "O diretor abordou o cenógrafo,",
  [818107786933504] = "Aparentemente, um certo holofote era muito ofuscante.",
  [818107786933248] = "O diretor caminhou em direção ao técnico de iluminação,",
  [818107786932992] = "Ele provavelmente quer substituir algum ator tolo.",
  [818107786932736] = "O diretor caminhou até o roteirista,",
  [818107786932480] = "Mas primeiro tenho que esperar até pegar esse maldito ladrão!",
  [818107786932224] = "O Imperador Roselle disse uma vez: 'Procura-se riqueza em meio ao perigo', o que só mostra que estou prestes a ficar rico!",
  [818107786931968] = "Mas é perigoso aqui.",
  [818107786931712] = "Se eu descobrir algum tesouro, ficarei rico!",
  [818107786931456] = "Quem não conhece as ruínas da Serra Hornacis!",
  [818107786931200] = "Caça ao tesouro, é claro!",
  [818107786929920] = "Tive um encontro maravilhoso na boate!",
  [818107786929664] = "Minha casa fica em Tingen. Quero voltar para Backlund porque da última vez fui lá para participar de uma conferência acadêmica...",
  [818107786929408] = "Você está com saudades de casa?",
  [818107786929152] = "Suspiro, quero voltar para Backlund.",
  [818107786928896] = "Se não houver novos progressos, poderei voltar em breve...",
  [818107786928640] = "Desta vez... cerca de dois meses, suponho?",
  [818107786928384] = "Há quanto tempo você está neste acampamento?",
  [818107786928128] = "Lenço de seda... aquele que sinto falta... quando você estará ao meu lado?",
  [818107786927872] = "Independentemente de você ter nome ou não, acho que vou me lembrar de você, fofo Mao Mao Cao.",
  [818107786927616] = "E eu tenho um novo nome; Não sou mais uma gatinha que as pessoas não conseguem lembrar!",
  [818107786927360] = "É especialmente confortável. Verf e Lis vêm me ver todos os dias com comidas deliciosas, como antes.",
  [818107786927104] = "Como você está morando aqui?",
  [818107786926848] = "Obrigado, pessoa gentil! Acho que estarei lá em breve.",
  [818107786926592] = "Sim, se você estiver livre, poderá encontrá-lo e brincar juntos.",
  [818107786926336] = "Ah, ele ainda está lá?",
  [818107786926080] = "Você ainda se lembra do seu amigo? É um gato laranja, esperando por você na cesta do mercado!",
  [818107786925824] = "É tão bom ter uma casa... poder dormir tranquilamente todos os dias.",
  [818107786925568] = "Hee hee, Cecil, pare de me provocar! A maneira como você parece tão sério... torna difícil dizer se é uma piada ou se é real.",
  [818107786925312] = "Não, Edith, este poder é mágico, mas também perigoso. Saber demais não é bom para você; ter-me para protegê-lo é o suficiente.",
  [818107786925056] = "Realmente? Uma coisa tão mágica, por que você não me ensina?",
  [818107786924800] = "Você acredita nisso? Contanto que eu bata palmas suavemente com as costas das mãos, todos os fantasmas se manifestarão diante dos meus olhos e então... todos eles desaparecerão.",
  [818107786924544] = "Edith, você é sempre tão tímida. Não se preocupe, mesmo que realmente haja algo, eles não ousariam chegar perto daqui.",
  [818107786924288] = "Pare de falar, não dormi bem a noite toda depois de ouvir essas histórias.",
  [818107786924032] = "Aquelas lendas de fantasmas sobre as quais os servos falam... são realmente interessantes. Talvez eu tenha a chance de ver por mim mesmo.",
  [818107786923776] = "Fiquei três horas sentado em uma carruagem, para não olhar aquelas flores silvestres.",
  [818107786923520] = "Contanto que você esteja disposto a pagar alguns Sol, posso manifestar isso: posso abençoá-lo se fizer uma fortuna em três meses!",
  [818107786923264] = "Este convidado, por favor, não questione minha habilidade como Médium Espiritual! É que preciso de mais... uh... Sol, para continuar me comunicando!",
  [818107786923008] = "Ho, como isso é possível!",
  [818107786922752] = "Na verdade, não existe nenhum espírito guardião, não é?",
  [818107786922496] = "Este espírito é provavelmente muito poderoso, a percepção comum não consegue mais mantê-lo!",
  [818107786922240] = "Espere um momento, estou usando minha alma para perceber sua aparência...",
  [818107786921984] = "Hum? Por que você parou?",
  [818107786921728] = "…Uh, segurando… <P_Heart> (remexendo) </> … Estranho… onde eu coloquei…",
  [818107786921472] = "Aquele atrás de você é o espírito guardião que simboliza a riqueza; está vestido com uma armadura dourada, segurando—",
  [818107786921216] = "Exatamente! Ah, ótima existência! Eu posso sentir sua respiração!",
  [818107786920960] = "Você está falando comigo?",
  [818107786920704] = "Velho Tom, pelo bem da nossa amizade de vinte anos, ajude-me apenas desta vez!",
  [818107786920448] = "Vou embrulhar em mais algumas camadas de papel manteiga, garanto que não vai sair nem um pouquinho de cheiro, tudo bem, né?",
  [818107786920192] = "Velho George, isso realmente não serve! O cheiro de peixe em conserva é tão forte que todos os clientes vão embora.",
  [818107786919936] = "Se você está indo para Tingen, por que não os leva até ele no caminho?",
  [818107786919680] = "Então, acabei de conservar dois. De qualquer forma, não posso acabar com eles, seria um desperdício dar ao gato com eles.",
  [818107786919424] = "Aquele garoto, Jack, adora peixe em conserva. Trabalhando como aprendiz em uma fábrica de Tingen, ele certamente não consegue nem provar carne...",
  [818107786919168] = "…Isso é porque ele estava sendo muito chato, não conseguia esquecer, isso não é permitido?",
  [818107786918912] = "Coisas como 'Jack adora comer isso', 'Jack disse isso da última vez'...",
  [818107786918656] = "Sim, sim, mas só hoje você o mencionou pelo menos dez vezes.",
  [818107786918400] = "Prefiro não vê-lo por alguns meses... isso é o que você chama de paz e sossego!",
  [818107786918144] = "Bobagem, isso é só um pirralho, ele faz uma confusão assim que volta, virando a casa de cabeça para baixo.",
  [818107786917888] = "O velho George sente falta dele se não o vê por um dia, mas sua boca é dura como uma pedra!",
  [818107786917632] = "Heh, Jack é o bom neto desse velho, trabalhando como aprendiz em uma fábrica de Tingen.",
  [818107786917376] = "Quem é Jack?",
  [818107786917120] = "…Não é nada. Está ficando tarde, vamos para casa.",
  [818107786916864] = "Irmão, o que você ia dizer agora há pouco?",
  [818107786916608] = "A flor se foi, papai com certeza receberá nossas bênçãos!",
  [818107786916352] = "<P_Heart> (Voz ficando mais baixa) </> Não sobrou muito dinheiro em casa, e as fábricas em Tingen estão contratando trabalhadores do sexo masculino novamente, eu acho...",
  [818107786916096] = "Papai se foi, mas nossas vidas têm que continuar.",
  [818107786915840] = "O que há de errado, irmão?",
  [818107786915072] = "O padre disse que você voltou para o abraço da Deusa. Espero que você consiga dormir lá...",
  [818107786914816] = "Não temos dinheiro suficiente para trazer você para casa, então só podemos ir à igreja para orar por você... sinto muito...",
  [818107786914560] = "Embora o dono da fábrica tenha compensado, há muitos lugares na família que precisam de dinheiro.",
  [818107786914304] = "Posso sentir você aqui... bem ao meu lado. Então não vamos a lugar nenhum, essa loja sempre será nossa.",
  [818107786914048] = "Eu disse a ele que esta taberna foi construída tijolo por tijolo por nós, você construiu o balcão com suas próprias mãos e eu mesmo pintei as paredes.",
  [818107786913792] = "Aquele comerciante de sobretudo ofereceu trezentas libras de ouro logo de cara, dizendo que queria transformar este lugar em um café da moda.",
  [818107786913536] = "<P_Heart> (Falando sozinho) </> Thomas, alguém quer comprar a taverna de novo hoje...",
  [818107786913280] = "Todos nós sentimos por ela, mas o que podemos dizer? Contanto que ela esteja feliz.",
  [818107786913024] = "Agora ela sempre diz que Thomas ainda está aqui, sentado ao lado dela. Às vezes ela até serve uma bebida para o lugar vazio, dizendo que Thomas adora essas coisas...",
  [818107786912768] = "Suspiro, depois que Thomas faleceu, o cabelo de Eleanor ficou branco durante a noite.",
  [818107786912512] = "E agora...",
  [818107786912256] = "Thomas adorava contar piadas, e Eleanor ria atrás do balcão, sem conseguir nem segurar a xícara com firmeza... tsk tsk, naquela época era tão bom.",
  [818107786912000] = "Todos os dias, de manhã à noite, a loja ficava lotada de gente e as risadas podiam ser ouvidas de uma ponta à outra.",
  [818107786911744] = "Naquela época, a cerveja que Thomas preparava cheirava tão bem que poderia atrair bêbados da cidade vizinha. As tortas de Eleanor também eram uma especialidade, a crosta era tão escamosa que se esfarelava com uma mordida.",
  [818107786911488] = "Esta loja foi fundada por Eleanor e Thomas, já faz décadas.",
  [818107786911232] = "O que você está falando?",
  [818107786910976] = "Eu imploro, por favor, não conte a ninguém... eu te dou dez por cento, não, vinte por cento do lucro? Se isso vazar, estou acabado!",
  [818107786910720] = "Como esse artesanato tradicional pode ser chamado de fraude? Não é exatamente essa a sensação que aqueles cavalheiros ricos desejam – que foi simplesmente desenterrado?",
  [818107786910464] = "Então... você está vendendo antiguidades falsas para enganar as pessoas?",
  [818107786910208] = "Tudo bem, tudo bem! Eu admito! Estou envelhecendo essas estátuas... enterre-as no solo por alguns dias, depois desenterre-as, deixe-as úmidas e enlameadas, e os compradores em Backlund pagarão um preço alto...",
  [818107786909952] = "Uh... não... nada...",
  [818107786909696] = "Você está sendo tão sorrateiro que não está fazendo nada de ruim, está?",
  [818107786909440] = "Bens bons? Eles foram limpos há muito tempo! Se você for agora, não encontrará nem um tijolo inteiro!",
  [818107786909184] = "Recentemente, os jovens da cidade e as equipes de expedição de fora da cidade correram para o castelo como loucos.",
  [818107786908928] = "Quanto a isso... *tosse tosse*, para falar a verdade, Velho John.",
  [818107786908672] = "Também quero comprar um casaco novo para minha esposa; o velho de lã dela tem manchas há três anos...",
  [818107786908416] = "Wiggins, para que cresçamos juntos... leve-me com você!",
  [818107786908160] = "Não admira que você esteja tão chique agora! Eu sabia, o material do seu novo colete é definitivamente extraordinário.",
  [818107786907904] = "Minha riqueza depende inteiramente dos tesouros que cavo no castelo; uma única pequena estátua vale o moinho do meu pai!",
  [818107786907648] = "Se Billy ficar ansioso e chorar, ele não vai brincar comigo da próxima vez...",
  [818107786907392] = "Eu, vou ficar mais um pouco e depois volto.",
  [818107786907136] = "Sim, não é seguro aqui, vá para casa rapidamente.",
  [818107786906880] = "Mas este lugar parece um pouco frio...",
  [818107786906624] = "Mesmo que ele adivinhasse... ele é tão tímido que definitivamente não ousaria vir procurar, hee hee.",
  [818107786905344] = "No entanto, me esconder aqui é realmente muito assustador... É melhor eu voltar e encontrar Billy, e me esconder em outro lugar na próxima vez.",
  [818107786905088] = "O velho padre Blake é diferente; às vezes ele até divide o bolo conosco. Mas se Billy viesse à igreja para me pegar, ele definitivamente iria rir e me denunciar...",
  [818107786904832] = "Estou brincando de esconde-esconde! Padre Hawkins odeia que brinquemos na igreja, então este é o lugar mais perigoso e também o mais seguro.",
  [818107786904320] = "O que você tem?",
  [818107786904064] = "Uau! Eu, sinto muito, pai!",
  [818107786903808] = "Charlie deve estar escondido nos arbustos da igreja e Daisy parece ter corrido em direção ao castelo. Conto com você!",
  [818107786903552] = "Você quer ajudar também? Você realmente é uma boa pessoa!",
  [818107786903296] = "Onde os outros estão se escondendo?",
  [818107786903040] = "Esqueça, daqui a pouco voltarei para procurá-lo e o ajudarei a procurar outros.",
  [818107786902784] = "Mas já faz tanto tempo, por que ele ainda não encontrou o caminho até aqui? Ugh, aquele bebê chorão, ele não choraria de novo, não é...",
  [818107786902528] = "Shh! Shh! Estamos brincando de esconde-esconde, você não deve trazer Billy até aqui.",
  [818107786902272] = "Por que você está se escondendo aqui?",
  [818107786902016] = "Se você os encontrar, você deve dizer a eles – esta regra não é nada justa... da próxima vez teremos que mudar para contar até oitenta, não, cinquenta!",
  [818107786901760] = "Realmente!? Isso é ótimo!",
  [818107786901504] = "Eu vou te ajudar a procurá-los, você vai para casa comer.",
  [818107786901248] = "Se eu não for jantar em casa, mamãe com certeza vai me repreender. Mas, mas...",
  [818107786900992] = "Procurei no mercado, no jardim e na beira do rio... não estão em lado nenhum...",
  [818107786900736] = "Eu... estávamos brincando de esconde-esconde... só posso ir procurá-los depois de contar até cem. Mas eles fugiram sabe-se lá há quanto tempo!",
  [818107786900480] = "<P_Heart> (Falando sozinho) </> Fantasma? Terei a oportunidade de ir ao castelo e ver...",
  [818107786900224] = "Se realmente existem fantasmas, isso não é algo que eu possa lidar... é melhor deixar os profissionais cuidarem disso.",
  [818107786899968] = "Agora olhe, ouvi dizer que vários deles encontraram algo impuro no castelo!",
  [818107786899712] = "Suspiro, é tudo por causa daqueles pirralhos travessos! Eu disse a eles que o antigo castelo é perigoso, mas eles sempre adoram correr até lá.",
  [818107786899456] = "Evento paranormal? Aconteceu alguma coisa?",
  [818107786899200] = "Tudo bem, mal posso esperar para montá-lo.",
  [818107786898944] = "Você não acredita em mim? Então vou levá-lo para ver esta noite! Se você realmente vir, terá que me deixar brincar com seu relógio de bolso; se não, empresto minha bicicleta para você andar por dois dias!",
  [818107786898688] = "Também é possível que você esteja enganado. De qualquer forma, não acreditarei que existam fantasmas no mundo.",
  [818107786898432] = "Hmm... talvez, talvez eu tenha ouvido errado... Não! Isso só mostra que não é um fantasma comum!",
  [818107786898176] = "Mas como pode um fantasma emitir som?",
  [818107786897920] = "Você não acreditaria como esse fantasma é majestoso! Ele está bem na entrada do antigo castelo, vestindo uniforme, suas botas estalando enquanto ele anda, como... como um soldadinho de chumbo que acabou de vencer uma batalha!",
  [818107786897664] = "Hmph... mas a sorte daquele garoto está prestes a acabar.",
  [818107786897408] = "Mas ouvi dizer que aquele Neville parece ter trazido algo da montanha.",
  [818107786897152] = "Não encontramos nada.",
  [818107786896896] = "Então, o que você encontrou?",
  [818107786896640] = "É porque aqueles consultores de negócios disseram ao Capitão Barnaby que Hornacis tem tesouros deixados por civilizações antigas.",
  [818107786896384] = "Uma equipe de caça ao tesouro?",
  [818107786896128] = "Esta é a equipe de caça ao tesouro organizada pelo Capitão Barnaby.",
  [818107786895872] = "Que tipo de acampamento é esse?",
  [818107786895616] = "Hmph, com certeza vou encontrar uma chance de me vingar!",
  [818107786895360] = "Eles até relataram que eu fiquei bêbado com o Capitão Barnaby!",
  [818107786895104] = "Concordamos em tocar 'Fight the Evil', com o perdedor bebendo. Como resultado, os dois se uniram para trapacear, me embebedaram e me forçaram a assinar um contrato irracional!",
  [818107786894848] = "Isso não é apenas um conflito!",
  [818107786894336] = "Você tem um conflito com Neville e Martin?",
  [818107786894080] = "Depois de beber, minha cabeça dói muito.",
  [818107786893824] = "Ainda tenho que terminar o que o Capitão Barnaby designou hoje.",
  [818107786893568] = "Sempre haverá pessoas curiosas sobre Hornacis.",
  [818107786893312] = "Como equipes de expedições civis... ou acampamentos temporários montados por grupos de montanhismo?",
  [818107786893056] = "Acampamentos privados? Os acampamentos podem ser propriedade privada?",
  [818107786892800] = "Em frente está outro acampamento. A professora nos disse para ter cuidado para não entrar em acampamentos particulares.",
  [818107786892544] = "O acampamento da nossa equipa arqueológica exige virar à esquerda neste caminho.",
  [818107786892288] = "Não, não, não, essa estrada em frente não é o nosso acampamento.",
  [818107786892032] = "A professora não disse para ir direto depois de cruzar a ponte?",
  [818107786891776] = "Atravesse a ponte e mantenha-se à esquerda.",
  [818107786798336] = "Acontece que há uma estação de trem aqui. Entrarei em contato com a Câmara de Comércio imediatamente; talvez possamos pegar emprestado os trilhos para algum comércio! Aguarde alguns dias.",
  [818107786891008] = "Aventura! Aventura! Eu quero ser um 'Grande Aventureiro'!",
  [818107786890752] = "É perigoso, mas arriscamos o perigo de vir aqui só para a formatura... uh, aventura...",
  [818107786890496] = "Isso é muito perigoso para vocês, estudantes.",
  [818107786890240] = "É tudo para pesquisar os segredos das ruínas de Hornacis.",
  [818107786889984] = "Este é o acampamento da equipe arqueológica. A maioria dos membros são professores e alunos do departamento de história.",
  [818107786886656] = "<P_Heart> (A outra parte acena para você se aproximar) </>",
  [818107786886400] = "O campo de batalha da briga é muito especial; o que você está convocando são projeções históricas dos associados do clube. \n Como invocador, você é tanto um espectador quanto um participante — que luta emocionante e interessante! \n Sério, você não vem dar uma rodada?",
  [818107786886144] = "Bem-vindo à arena de luta do clube.",
  [818107786885888] = "<P_Heart> (Que lazer. Se ao menos eu pudesse relaxar assim todos os dias.) </>",
  [818107786885632] = "Também não tenho muita certeza… {Respeitado Sr. {Respeitada Sra. |}}, se você estiver disposto, por favor me ajude a encontrar os endereços específicos!",
  [818107786885376] = "Estranho, esses envelopes são todos tão antigos; parece que foram deixados aqui há muito tempo.",
  [818107786885120] = "Mas ainda há tantas cartas aqui que não foram entregues...",
  [818107786884864] = "E daí? Tenho o trabalho mais tranquilo desta cidade.",
  [818107786884608] = "Se você apenas dorme e não trabalha, o que você fará se o seu chefe descobrir!",
  [818107786884352] = "Você consegue dormir profundamente assim durante o horário de trabalho? Estou com tanta inveja!",
  [818107786884096] = "Ah, há algo que você precisa?",
  [818107786883840] = "Senhor, você é o despachante?",
  [818107786883584] = "<P_Heart> (A luz do sol está muito intensa, minha cabeça está girando...) </>",
  [818107786883328] = "Este lugar é realmente lindo, tão lindo que parece irreal!",
  [818107786883072] = "Olhe para esta luz do sol. Ontem, hoje, amanhã, o Sol Eterno está alto!",
  [818107786882816] = "Essas crianças sempre pensam em ir para o mundo exterior. O que há de tão bom no exterior!",
  [818107786882560] = "Moro aqui há muito tempo, mas nunca me canso disso.",
  [818107786882304] = "Esta pequena cidade é realmente linda, você não acha?",
  [818107786882048] = "Velho, por que você continua andando de um lado para outro?",
  [818107786881792] = "Se você o vir, por favor, diga que sinto muita falta dele.",
  [818107786881536] = "Independentemente disso, deixe-me tirar uma soneca primeiro!",
  [818107786881280] = "Só pular na cesta todos os dias já esgotou todas as minhas forças.",
  [818107786881024] = "Talvez ele tenha ido para outro lugar? Você gostaria de tentar procurar em outro lugar?",
  [818107786880768] = "\"Fuzzy Grass\"… Quando poderei ter meu novo nome?",
  [818107786880512] = "E ele tem um novo nome; você pode chamá-lo de 'Fuzzy Grass'.",
  [818107786880256] = "Eu me lembro agora! Ele se mudou; você pode encontrá-lo na casa de palha na entrada da vila.",
  [818107786880000] = "Venho aqui todos os dias para esperar, mas faz muito tempo que não o vejo.",
  [818107786879744] = "Agora que você mencionou isso, parece que tenho uma pequena impressão...",
  [818107786879488] = "Ele é um gato malhado cinza que gosta de dormir em uma cesta de bucha.",
  [818107786879232] = "Quem é seu amigo? Como eles são?",
  [818107786878976] = "Olá, você viu meu amigo?",
  [818107786878720] = "Eh? Por que a data deste jornal é de mais de trinta anos atrás? ...Você ainda está lendo agora?",
  [818107786878464] = "Isso é fato ou lenda! Está escrito de forma tão brilhante! Seria ótimo se fosse publicado como um livro independente.",
  [818107786878208] = "Eu não me importo com essas coisas. Veja aqui, há uma serialização de 'The Water Lily Fairy Chronicles'.",
  [818107786877952] = "Aconteceu alguma coisa nova na pequena cidade recentemente?",
  [818107786877696] = "Parece... talvez... Me desculpe, eu realmente preciso pensar sobre essas questões com cuidado.",
  [818107786877440] = "Então para onde ela foi? Ela te contou quando voltaria?",
  [818107786877184] = "É este o tipo de coisa... que se deve lembrar claramente? Estranho, então por que não me lembro...",
  [818107786876928] = "Você pode até esquecer isso?!",
  [818107786876672] = "…Huh? Isso… parece que não tenho nenhuma impressão disso.",
  [818107786876416] = "Você é muito romântico, meu jovem... Como vocês dois se conheceram?",
  [818107786876160] = "Agora que ela se foi, ainda guardo meticulosamente as flores, esperando o dia em que ela volte.",
  [818107786875904] = "Costumávamos deitar juntos neste canteiro de flores e observar as estrelas.",
  [818107786875648] = "Quão verdadeiramente devotado!",
  [818107786875392] = "Claro, o amor da minha vida; minha existência parece ser por causa dela.",
  [818107786875136] = "Ela é uma garota que você gosta?",
  [818107786874880] = "Ah, estou sentindo falta do meu Lino.",
  [818107786874624] = "O que você está fazendo deitado no chão?",
  [818107786874368] = "Por que... parece que hoje é a primeira vez que consigo sentir a diferença entre eles?!",
  [818107786874112] = "Deusa! Esses dois tipos de comida realmente têm sabores diferentes?",
  [818107786873856] = "O feijão verde tem fragrância de grama e é mastigável, enquanto os brotos de bambu são mais suculentos, com sabor crocante, macio e doce.",
  [818107786873600] = "<P_Heart> (Não são apenas feijões verdes comuns e brotos de bambu?) </>",
  [818041751688448] = "O que você está fazendo?",
  [818107786873344] = "Você poderia se dar ao trabalho de provar esses dois vegetais e me dizer qual é a diferença?",
  [818107786873088] = "Claro, o que é isso?",
  [818107786872832] = "{Jovem Sr. {Jovem Sra. |}}, você poderia me fazer um favor?",
  [818107786872576] = "Eu posso entender...",
  [818107786872320] = "Você consegue entender como me sinto?",
  [818107786872064] = "Autógrafos também são importantes! Este é o sustento espiritual dos fãs!",
  [818107786871808] = "Não é o romance que você quer ler?",
  [818107786871552] = "Quero o autógrafo do Fors... autógrafo! Autógrafo!",
  [818107786871296] = "Quero ver o novo trabalho do Fors! Quero ver o novo trabalho do Fors... Quero o autógrafo do Fors!",
  [1139165182473216] = "Hum.",
  [818107786870784] = "Você parece estar com muita dor?",
  [818107786870528] = "É claro que a vida é difícil, por isso devemos esperar coisas boas.",
  [818107786870272] = "Hmm... isso também é uma boa âncora emocional.",
  [818107786870016] = "Sempre sentirei falta daquela meia-noite maravilhosa – de tudo o que aconteceu entre a Sra. Xianghua e eu.",
  [818107786869760] = "Isso mesmo! Ela é a dançarina mais original da boate Backlund; seus movimentos de dança são graciosos e sua voz é comovente!",
  [818107786869504] = "Ela deve ser muito importante para você, certo?",
  [818107786869248] = "É isso mesmo... este é um símbolo precioso entre a Sra. Xianghua e eu.",
  [818107786868992] = "Este deve ser um token muito significativo.",
  [818107786868736] = "Então você já atendeu a essas 'solicitações excessivas'.",
  [818107786868480] = "Felizmente, este livro não foi propriedade roubada. Graças à explicação da questão do lenço de seda, a polícia me soltou...",
  [818107786868224] = "Mas aquele especulador desprezível não me disse de onde vinham os seus produtos! Como resultado, voltei a ser suspeito e fui interrogado pela polícia durante uma tarde inteira!",
  [818107786867968] = "E esse romance autografado em edição de colecionador, 'O Grande Aventureiro'... Comprei esse livro de um cambista!",
  [818107786867712] = "Ahem... mas para ser justo, a Sra. Xianghua é realmente muito elegante...",
  [818107786867456] = "Droga, droga. Por este lenço de seda, fui tratado como um pervertido e interrogado ferozmente pela polícia durante dez minutos!",
  [818107786867200] = "O que fazer? Claro, vou aguentar e fazer isso!",
  [818107786866944] = "Parece um pouco... então o que você planeja fazer?",
  [818107786866688] = "Você não acha que é demais?",
  [818107786866432] = "\"Romance de edição de colecionador autografado de Fors\"… São coisas que deveriam aparecer em uma lista de compras?",
  [818107786866176] = "\"Um lenço de seda com estampa de batom da Sra. Fragrant da Boate Backlund, e por falar nisso, pergunte se ela ainda se lembra daquela meia-noite maravilhosa?\"",
  [818107786865920] = "\"Se seus sapatos estão quebrados, você precisa trocar por um novo par, deve ser 13 Daffodil Street, Tingen...\" Uh, acho que isso é normal para ele.",
  [818107786865664] = "Olha, os do começo são bem normais - 'Ajude a pegar as cartas enviadas pela família no correio'...",
  [818107786865408] = "Claro. Se você me perguntar, qualquer pessoa que vir esta ‘Lista de compras de itens pessoais’, que na verdade é uma ‘Lista de desejos de itens pessoais’, ficaria com dor de cabeça.",
  [818107786864640] = "A quarta moeda de ouro. Um local de encontro para os pobres; este é o último lugar onde eles ficaram.",
  [818107786864384] = "Oh sim. Para falar a verdade, meu pai, John Joseph, é um arqueólogo famoso e seu foco de pesquisa são as antigas ruínas do pico principal de Hornacis. Eu não posso me comparar a ele.",
  [818107786864128] = "Vocês são arqueólogos?",
  [818107786863872] = "Quanto ao que isso tem a ver com a Deusa da Noite Eterna... meu pai e eu ainda precisamos continuar nossa arqueologia.",
  [818107786863616] = "Uau, isso é incrível!",
  [818107786862848] = "Cúpulas imponentes, enormes pilares de pedra, magníficos e grandiosos! Símbolos da noite podem ser vistos por toda parte nas ruínas, mas eles são diferentes do emblema sagrado da Deusa da Noite Meia... Você consegue adivinhar por quê?",
  [818107786862080] = "Você sabia que descobertas arqueológicas mostram que havia vestígios de atividade humana na Cordilheira Hornacis, claramente tendo formado uma civilização, existindo um antigo reino!",
  [818107786861824] = "As pessoas na alucinação disseram que era composto de torres altas e pilares enormes... caramba, por que me lembro disso tão claramente!",
  [818107786861568] = "Ah, você me assustou.",
  [818107786861312] = "Então, do que é composto?",
  [818107786859776] = "Que chato!",
  [818107786856704] = "Por que é que?",
  [818107786855936] = "Chifre-a-cis?",
  [818107786855424] = "Os caras que moravam aqui deixaram um grande número de murais. A julgar pelos murais, a aparência deles era quase idêntica à nossa; eles podem ser considerados humanos!",
  [818107786855168] = "Sim! É a Cordilheira Hornacis! As ruínas aqui remontam a pelo menos 1.500 anos atrás.",
  [818107786854912] = "A montanha de que você está falando, poderia ser...",
  [818107786798592] = "Este é o regente em tempo integral nomeado pela Câmara de Comércio. Ele trouxe o 'Acordo de Distribuição Regional' e apresentará as regras operacionais específicas para você.",
  [818107786854144] = "Mas... não tem isca no anzol?",
  [818107786853888] = "O gelo derrete em água e, se houver água, você pode pescar.",
  [818107786853120] = "Você está pescando aqui?",
  [818107786852864] = "Pare com isso. Você está me fazendo suar.",
  [818107786852608] = "Mas, na realidade, nada aconteceu, não é?",
  [818107786852352] = "Fui baleado pelo Ruben... a bala perfurou meu coração. Isso é muito específico, como se já tivesse acontecido.",
  [818107786852096] = "Também fui morto a tiros por Reuben – porque testemunhei seus crimes. Nossas lápides estão bem próximas uma da outra.",
  [818107786851840] = "Olhe para minha lápide, bem ao lado da sua.",
  [818107786851584] = "Um presságio? Você quer dizer...",
  [818107786851328] = "Este é um evento sobrenatural. Essas coisas sendo enterradas, acompanhadas de lápides... é como uma espécie de presságio.",
  [818107786851072] = "Você quer dizer...",
  [818107786850816] = "Você olhou atentamente para as inscrições? Sinto cada vez mais... que isto não é apenas uma brincadeira comum.",
  [818107786850048] = "Nenhum! Esse cara pode fugir de nossas patrulhas e cada vez mais coisas desaparecem!!",
  [818107786849792] = "Alguma descoberta?",
  [818107786849536] = "Ele até montou uma lápide onde enterrou as coisas! Amaldiçoando-nos como se já estivéssemos mortos!",
  [818107786849280] = "Roubando nossas coisas e enterrando-as na natureza!",
  [818107786848512] = "Hmm... então devo lembrá-lo de ter mais cuidado na próxima vez? Ou comprar uma vara de pescar de melhor qualidade?",
  [818107786848256] = "Isso foi comprado na loja de artigos de pesca mais famosa de Backlund!",
  [818107786848000] = "Você acha que isso é apenas uma brincadeira? Aquele bastardo roubou minha amada vara de pescar e a destruiu!",
  [818107786847744] = "Você está bem? Poderia ser uma pegadinha?",
  [818107786847488] = "Não sei qual bastardo está nos amaldiçoando assim!",
  [818107786847232] = "Não é só roubar! Os itens roubados estão enterrados na natureza e há até uma lápide colocada ao lado deles!",
  [818107786846976] = "Há um ladrão? Existe alguma coisa nossa que valha a pena roubar?",
  [818107786846720] = "O que? Você não sabe? Suas coisas não foram roubadas!",
  [818107786846464] = "A que você está se referindo?",
  [818107786846208] = "Você sabe quantos incidentes ocorreram?",
  [818107786845952] = "Não importa, por favor, saia. As montanhas são perigosas, não ande por aí.",
  [818107786845184] = "Ele não poderia ter corrido muito...",
  [818107786844928] = "<P_Heart> (Sussurrando) </> As manchas de sangue, elas desapareceram.",
  [818107786844672] = "Continue procurando.",
  [818107786844416] = "Então você me diz o que devemos fazer.",
  [818107786844160] = "Você já considerou! Se o deixarmos ir, seremos nós que perderemos nossas vidas!",
  [818107786843904] = "Droga, se ele não morrer, alguém não conseguirá dormir à noite.",
  [818107786843648] = "Devemos voltar?",
  [818107786843392] = "Eu não vi. Ele correu para a floresta e desapareceu num piscar de olhos.",
  [818107786843136] = "Você viu para onde ele foi?",
  [818107786842880] = "Como acabei aqui...",
  [818107786842624] = "Neil, onde você está?",
  [818107786841856] = "Estou quase lá! Eu não sou louco!",
  [818107786841600] = "Insetos... fique longe dos insetos...",
  [818107786841344] = "Arrependimento? Não me arrependo!",
  [818107786841088] = "Peggy, George, lamento.",
  [818107786840832] = "Só mais um passo... e eu o encontrarei.",
  [818107786840576] = "Mas antes de começarmos oficialmente, você precisa entender o básico.",
  [818107786840320] = "Você veio; o raio espiritualidade descerá aqui e precisamos da sua ajuda.",
  [818107786840064] = "Oh? Você também quer participar dessa correria maluca?",
  [818107786839808] = "Claro, só espero que você nunca precise presentear a pessoa que ama com esta bebida.",
  [818107786839552] = "Isso parece tão místico. É realmente tão eficaz?",
  [818107786839296] = "Esta bebida tem um rico aroma de lavanda. Quando você mesmo prova, é apenas um chá refrescante. Mas se você convidar a pessoa que você ama para beber, essa pessoa o amará desesperadamente para sempre.",
  [818107786839040] = "O que é isso? Tão misterioso.",
  [818107786838784] = "<P_Heart> (Abaixando a voz) </> Já que você perguntou, devo dizer que na verdade temos uma mistura especial chamada 'Collar'.",
  [818107786838528] = "Beba um copo e garanto que você esquecerá toda a dor desse relacionamento.",
  [818107786838272] = "Haha, ainda sou uma alma apaixonada. Tenha um 'Esqueça tudo' para você! Cítricos e licores fortes misturados – o sabor é relaxante e inebriante.",
  [818107786838016] = "Contanto que você deixe a pessoa que o traiu beber isso, ela se arrependerá e voltará para se desculpar com você.",
  [818107786837760] = "Um 'Placebo' é exatamente o que você precisa. Tem cheiro principalmente de flores, mas tem um sabor azedo e adstringente quando bebido.",
  [818107786837504] = "Se você beber antes de uma confissão, ficará cheio de coragem e nada ficará no seu caminho!",
  [818107786837248] = "Então você precisa de um copo de 'Dream Come True'. Esta bebida tem um sabor doce e suave de mel ao entrar e, um momento depois, a base do licor forte sobe lentamente, fazendo seu coração disparar.",
  [818107786836992] = "Nenhum engano aqui. Diga-me, quais são seus problemas românticos?",
  [818107786836736] = "Isso parece impressionante. Essa bebida realmente funciona?",
  [818107786836480] = "Então você é a bebida especial que resolve problemas amorosos ~ Garanto que resolverá todos os seus problemas românticos!",
  [818107786836224] = "Minha querida, o que você gostaria de beber?",
  [818107786835968] = "Um teste de combate. Não se preocupe, tudo isso acontece em um sonho.",
  [818107786835712] = "Um teste?",
  [818107786833664] = "Você sempre será a mais linda para mim!",
  [818107786833408] = "Quem iria querer que você tirasse fotos quando estivermos velhos e grisalhos? Não ficaremos mais bem!",
  [818107786833152] = "Isso também faz parte da minha série, 'Gazing at a Lover'. Provavelmente continuarei tomando até ficarmos velhos e grisalhos.",
  [818107786832896] = "<P_Heart> (Sorrindo gentilmente) </> Tomar um todo ano é nosso velho hábito.",
  [818107786832640] = "Hahaha, é um mal-entendido. Estamos casados ​​há quase dez anos e meu marido ainda insiste em tirar essas fotos de casamento.",
  [818107786832384] = "Vocês dois estão realmente felizes. Desejo a você um casamento feliz!",
  [818107786832128] = "Miau... miau... miau-woo...",
  [818107786831872] = "Seu idiota mentiroso, você disse que ficaria comigo por toda a vida...",
  [818107786831616] = "<P_Heart> (Engasgando com soluços) </> Eu sei que você ainda se lembra... Por que ele normalmente era tão forte, mas não conseguiu sobreviver a essa gripe?",
  [818107786831360] = "Miau, miau-woo.",
  [818107786831104] = "Fenfen, você ainda se lembra do papai? Naquela época, nessa época, ele reclamava da sua queda de cabelo, mas ainda deixava você deitar no colo dele.",
  [818107786830848] = "…Ele está atrasado de novo. <P_Heart> (sorriso amargo) </> Não, esqueci de novo, ele não virá mais.",
  [818107786830592] = "Recomendo que você caminhe mais pelo mar de flores; você pode encontrá-los em breve.",
  [818107786830336] = "Um dia eles querem ver o nascer do sol com você, no outro querem passear na floresta.",
  [818107786830080] = "Haha, gostar de alguém com essa personalidade significa que o amor terá alguns desafios!",
  [818107786829824] = "Espere por isso. Da próxima vez que eu participar de uma reunião, ajudarei você a olhar com cuidado.",
  [818107786829568] = "Conheço alguns desses cavalheiros e senhoras em Backlund e Tingen...",
  [818107786829312] = "Mas, em vez de olhar aqui, talvez seja mais provável que esse amante entre em sua vida pelo destino.",
  [818107786829056] = "Querer um amante tão brilhante quanto o sol – ouço esse pedido com bastante frequência.",
  [818107786828800] = "Deixe a vovó ficar de olho em você. Pessoas gentis e introvertidas são difíceis de encontrar...",
  [818107786827520] = "Nessa idade, as pessoas estão maduras e têm alguma estabilidade financeira. Uma boa escolha!",
  [818107786827264] = "Então, que tipo de personalidade você gosta?",
  [818107786827008] = "<P_Heart> (Sorrindo) </> Juventude é boa; o amor entre os jovens deve ter paixão e faíscas!",
  [818107786826752] = "Você gosta de mulheres? Tenho muitas jovens lindas aqui! Qual faixa etária você prefere?",
  [818107786826496] = "Você gosta de homens? Tenho muitos jovens excelentes aqui! Qual faixa etária você prefere?",
  [818107786826240] = "Oh! Venha, venha, jovem, não seja tímido! Já vi você andando na frente deste canto de matchmaking três vezes. Me conta, que tipo de parceiro você procura?",
  [818107786825984] = "<P_Heart> (Sorrindo ainda mais feliz) </> Eu... claro! Eu ficaria encantado, Sr. Painter.",
  [818107786825728] = "Acho que já sei o que pintar. Você gostaria de se juntar a mim?",
  [818107786825472] = "Não, apenas para uma senhora com a testa franzida como você. Agora que sua sobrancelha relaxou, você parece ainda melhor.",
  [818107786825216] = "<P_Heart> (Rindo) </> Que interessante, você sempre fala com pessoas assim?",
  [818107786824960] = "Mais importante ainda, esperar por alguém disposto a parar e olhar a pintura.",
  [818107786824192] = "Apresse-se, encontre-a!!",
  [818107786823936] = "Hmph, essa mulher é realmente difícil de agradar! Ela não parecia tão interessada durante o banquete na mansão.",
  [818107786823680] = "Curtir a paisagem? Não seria melhor tomar o chá da tarde em seu próprio jardim do que vagar sem rumo por aqui?",
  [818107786823424] = "<P_Heart> (Sussurrando) </> A jovem... ela pode ter simplesmente se afastado para apreciar a paisagem...",
  [818107786823168] = "De volta à carruagem? Aquela velha viúva 'vendeu-a' para mim justamente para subir na escala social através de mim. Se ela desaparecer, não desperdicei meu dinheiro?",
  [818107786822912] = "Sim, senhor. Que tal... que tal voltarmos para a carruagem e esperarmos pela senhora?",
  [818107786821120] = "Talvez o seu humor normal seja porque falta um pouco de diversão na vida; vá sentar em um pequeno barco à beira do lago! A brisa do barco e as pétalas caindo certamente irão surpreendê-lo.",
  [818107786820864] = "Então compre um buquê para levar com você!",
  [818107786820608] = "Obrigado, senhora.",
  [818107786820352] = "Essa deve ser a parede especial de flores com fotos aqui! Aproveite a luz do sol, você nem imagina como vai ficar lindo nas fotos!",
  [818107786820096] = "Diga-me como você está se sentindo hoje e eu lhe darei uma recomendação!",
  [818107786819840] = "Estou neste lugar há três anos. Eu sei quais flores desabrocham e que horas em cada canto, e qual iluminação é melhor para a fotografia, melhor do que as abelhas!",
  [818107786819584] = "Ei! Amigo, você está aqui para uma visita, não é?",
  [818107786819328] = "Que nome único, espero que o sabor também me traga uma surpresa!",
  [818107786819072] = "\"Colarinho\"…",
  [818107786818816] = "Obrigado, você está tão atencioso como sempre. Que tipo de bebida é essa?",
  [818107786818560] = "Você também deve estar com sede; Eu pedi uma bebida para você.",
  [818107786818304] = "Sinto muito... lembro da nossa promessa...",
  [818107786818048] = "Não concordamos? Assim que vermos a lavanda pela última vez, nos separaremos para sempre.",
  [818107786817792] = "<P_Heart> (Um sorriso amargo) </> Gail, você sabe, não tenho forças para continuar amando você.",
  [818107786817536] = "<P_Heart> (Sussurrando baixinho) </> Diga-me... ainda há uma chance para nós? Eu... ainda não estou pronto...",
  [818107786817280] = "<P_Heart> (Sussurrando baixinho) </> Ainda assim, talvez eu deva comprar um par de luvas primeiro. As mãos de uma senhora não deveriam ser tão ásperas.",
  [818107786817024] = "Se eu me tornar a senhora deles, não terei mais que lavar roupas para os outros. Eu não precisaria economizar por três meses só para vir aqui...",
  [818107786816768] = "Eu deveria tomar a iniciativa de puxar conversa com um cavalheiro, alguém que parece rico.",
  [818107786816512] = "<P_Heart> (Falando sozinho) </> Gostaria de saber quando poderei vir aqui novamente? O dinheiro tem estado muito apertado ultimamente...",
  [818107786816256] = "Eu acho... estou disposto...",
  [818107786815488] = "Você quer se casar comigo? Eu vou te amar ainda mais do que ele! Posso estar com você todos os dias a partir de agora e amarei você para sempre.",
  [818107786815232] = "Eu sei quem você está esperando, ele não virá!",
  [818107786814976] = "<P_Heart> (Ele... ainda virá?) </>",
  [818107786814720] = "O amor pertence aos corajosos; Eu acredito que você terá sucesso!",
  [818107786814464] = "Estou procurando Granger, meu amante. Ela vai ser pedida em casamento hoje, e eu quero impedir que tudo isso aconteça...",
  [818107786814208] = "Senhor, você está procurando alguém?",
  [818107786813952] = "Eu sou um covarde, e agora ela vai ser arrebatada...",
  [818107786813696] = "Hoje, ela será proposta por outra pessoa. E eu? Nem me atrevo a fazer uma promessa firme!",
  [818107786813440] = "Eu sou realmente... tão estúpido!",
  [818107786813184] = "Seu gato é muito vulgar! Eu não vou falar com você!",
  [818107786812928] = "E ela nos trouxe para sofrermos juntos. Isso é uma coisa boa? Acorde, amigo.",
  [818107786812672] = "Por maior que fosse o talento, ela não fugiu de casa para fazer algumas bugigangas divertidas? Veja as poções que ela está fazendo agora!",
  [818107786812416] = "Ela é uma estrela que irá restaurar a glória da Família! Ela é um gênio que nunca deveríamos abordar!",
  [818107786812160] = "Amigo, você está muito entusiasmado com o trabalho. Estou com medo. Não é apenas ajudá-la a separar os materiais?",
  [818107786811904] = "Mestre é um gênio em poções! É realmente uma bênção trabalhar para ela!",
  [818107786811648] = "Ela costumava ser bastante generosa, mas depois de romper os laços com a Família, ela... suspirou.",
  [818107786811392] = "Deixar sangue é o mesmo que beber! Você realmente me matou, miau! E não há muitos lanches para comer!",
  [818107786811136] = "É apenas uma doença hereditária da família do Mestre; ela precisa de sangue fresco para sustentar sua vida, é quase o mesmo que uma terapia de sangria, miau.",
  [818107786810880] = "Shh! Mantenha isso baixo! O mestre pode nos entender!",
  [818107786810624] = "Este é o vale-refeição que você apresentou! O mestre é um monstro que come carne e sangue humano!",
  [818107786810368] = "Não pense em pegar a mestra para estudar as poções que ela não gosta, miau. Protegeremos o mestre, miau.",
  [818107786810112] = "Cheiro? Eu não senti cheiro de nada?",
  [818107786809856] = "Você tem cheiro de pessoa má, miau.",
  [818107786809600] = "Não te conto, miau. Você está aqui para pegar o mestre, miau.",
  [818107786809344] = "Com licença, você sabe onde está o anfitrião da festa do chá?",
  [818107786809088] = "Estranho, miau.",
  [818107786808832] = "Estranho, miau.",
  [818107786808576] = "Hmph, com a habilidade do mestre, fazer um chá novo para enganar aqueles velhos teimosos não é nada difícil! Tão inflexível!",
  [818107786808320] = "Pare de falar, miau. A mestra simplesmente odeia aqueles chás usados ​​nas lutas, por isso ela deixou a família, miau.",
  [818107786808064] = "Sinto muita falta da minha cama de gato perto da lareira e do meu peixinho.",
  [818107786807808] = "Se o Mestre apenas ouvisse a Família, ela não teria que vir para este lugar no interior.",
  [818107786807552] = "O mestre está pesquisando novos chás estranhos novamente, miau.",
  [818107786807296] = "Este baú de tesouro parece ter uma fechadura complexa.",
  [818107786807040] = "Use a Semente dos Suspiros: Maré para completar sua primeira caçada escarlate.",
  [818107786806784] = "Muito bom! Você aprendeu como usar a Semente dos Suspiros; agora, experimente o desafio avançado!",
  [818107786806528] = "Aceite a [Semente dos Suspiros] missão, envie-me a Relíquias Escarlates que você coletou e você receberá uma recompensa proporcional.",
  [818107786806272] = "Novo caçador, você entrou na Cidade da Caça ao Dragão.",
  [818107786806016] = "A riqueza nunca pertence aos cautelosos.",
  [818107786804736] = "Parece estar olhando para aquele líder.",
  [818107786804480] = "Por que esse babuíno está tão animado?",
  [818107786803712] = "Backlund, esconde muitos segredos, muitas mentiras e muitas coisas que as pessoas pensam que estão bem escondidas.",
  [818107786802688] = "“O amor vem sempre acompanhado de mentiras”, mas quem sabe se esta afirmação em si é uma forma de engano?",
  [818107786802432] = "Selecione a estação de destino.",
  [818107786802176] = "Olá, você gostaria de pegar uma carruagem turística?",
  [818107786801920] = "O que há de errado, Consultor {Sr. {EM. |}}? Quer desistir da perseguição?",
  [818107786801664] = "Aguardaremos aqui pelas suas boas notícias.",
  [818107786801408] = "Seu personagem é admirável, Consultor {Sr. {EM. |}}.",
  [818107786801152] = "Mas da próxima vez, sugiro sinceramente que você não “mude de ideia” com muita frequência dentro do nosso bloqueio.",
  [818107786800896] = "Está tudo bem, Consultor {Sr. {EM. |}}, deixe o resto conosco.",
  [818107786800128] = "Estarei sempre pronto nesta estação para despachar trens para você ou realizar trabalhos de manutenção nos trens.",
  [818107787116800] = "Viajante, o que está selado aqui pelo vento e pela neve não pode ser tomado pela força bruta – se quiser abri-lo, você deve primeiro passar no teste do Cavaleiro.",
  [818107786799360] = "A Câmara de Comércio forneceu-lhe capital inicial e você pode iniciar sua primeira negociação agora.",
  [818107786985728] = "No momento, ele não tem informações sobre sua presa e coça a cabeça de ansiedade.",
  [818107787022592] = "E então? Ele ainda estava lá quando você mudou de turno?",
  [818107786854656] = "Era uma vez uma montanha e nela havia muitas ruínas antigas. É quase certo que um antigo reino existiu lá...",
  [818107786891520] = "Por favor, acalme-se...",
  [818107786723584] = "Só então você pode o quê?",
  [818107786760448] = "A propósito, se você vir o sem-teto ali, por favor, não tenha medo. Desde que ficou mentalmente instável, ele dorme naquela carruagem abandonada todos os dias, dizendo todo tipo de coisas estranhas. Mas ele nunca machuca ninguém.",
  [818107786594048] = "Hmph, você foi enviado pelos vizinhos para roubar abóboras! Não é tão fácil me vencer no Festival da Colheita!",
  [818107786629376] = "Eu sou diferente. Sempre que quero me acalmar, conto uma piada para mim mesmo.",
  [818107786465536] = "Como está indo sua avaliação?",
  [818107786498816] = "Ufa... você me assustou.",
  [818107786563840] = "Mas o desastre da profecia não parece ter acontecido... Ah, será que um “figurão” protegeu o Lago Dourado do Outono?",
  [818107786798080] = "Além disso, com a sua chegada, o período mais difícil para o castelo já passou. Definitivamente haverá um futuro mais próspero.",
  [818107786797824] = "Que chocante... mas... mas acho que nem sempre podemos confiar na graça dos deuses.",
  [818107786797568] = "Este porco está mordendo... um colar de pérolas?",
  [818107786797312] = "A fé da cidade? Independentemente disso, desejo que seu desejo se torne realidade!",
  [818107786797056] = "Contanto que você ofereça um nenúfar, seu desejo será ouvido pela fada! Todo mundo diz isso!",
  [818107786796800] = "Essa é a nossa piscina dos desejos, você não sabia?",
  [818107786796544] = "Por que você está fazendo um pedido para uma piscina?",
  [818107786796288] = "Sinceramente, desejo que o nenúfar me abençoe.",
  [818107786796032] = "Parece que não há como se comunicar.",
  [818107786795776] = "Não entre... neblina...",
  [818107786795520] = "Névoa? Não vejo neblina.",
  [818107786795264] = "À frente... neblina... não entre...",
  [818107786795008] = "Falando durante o sono, hein...",
  [818107786794752] = "Louvado seja o nenúfar...",
  [818107786794496] = "O que? O que você está falando?",
  [818107786794240] = "Nenúfar... dormindo... proteja o nenúfar...",
  [818107786793984] = "Por que você está dormindo aqui sozinho? Onde estão sua mãe e seu pai?",
  [818107786793728] = "Suspirar! Por que você não ouve conselhos!",
  [818107786793472] = "Está tudo bem, sou bastante corajoso, vou dar uma olhada.",
  [818107786793216] = "Ok, obrigado pelo lembrete.",
  [818107786792960] = "Acredite, antes de me mudar para cá, eu era o mestre adivinhação mais famoso da minha cidade natal.",
  [818107786792192] = "Sim, é você! Não vá mais longe!",
  [818107786791936] = "Sim, sim, que chato, vou isolar os dois sozinhos!",
  [818107786791680] = "Eles não estão brincando com você?",
  [818107786791424] = "Vocês são demais! Nenhum de vocês está prestando atenção em mim!",
  [818107786791168] = "…Para onde Jeremy foi? Por que ele não está aqui para nos ajudar a dar as cartas?",
  [818107786790912] = "Suspiro, você realmente nunca se cansa de perder!",
  [818107786790656] = "Não vou perder da próxima vez! Desta vez aposto... fazendo recados para a mamãe!",
  [818107786790400] = "…Parece que você está trabalhando muito neste trabalho.",
  [818107786790144] = "Os porcos dos outros também continuam correndo para o nosso quintal! Suspirar! Está uma bagunça!",
  [818107786789888] = "Está sujo e quebrado! ...Suspiro, os empregados que eu contrato sempre fogem, e alguns até roubam as joias da família.",
  [818107786789632] = "O que há de errado com a casa?",
  [818107786789376] = "Quando o patrão voltar e vir a casa administrada dessa forma, com certeza vai me despedir.",
  [818107786789120] = "Não chore, não chore, eu vou te ajudar a encontrar seu irmão.",
  [818107786788864] = "Durante a soneca, ele se levantava e flutuava pela janela fechada... wuu wuu.",
  [818107786788608] = "Jeremy devia estar possuído por um espírito vingativo; Eu li sobre isso em livros de histórias!",
  [818107786788352] = "Por que você está chorando? O que você quer dizer com ele não é seu irmão?",
  [818107786788096] = "Jeremy não é mais meu irmão... wuu wuu...",
  [818107786787840] = "Se você continuar com essa cara azeda, colocarei absinto no seu jantar!",
  [818107786787584] = "Você não pode aprender com Jeremy? Seu filho brinca tão feliz lá fora todos os dias!",
  [818107786787328] = "Férias é estar perto da natureza!",
  [818107786787072] = "Férias raras, por que não ir para Tingen? O que há de tão bom neste lugar?",
  [818107786786816] = "Vou ficar de olho.",
  [818107786786560] = "Se você o vir, diga-lhe para voltar correndo para casa, ou mamãe vai bater nele por brincar demais.",
  [818107786786304] = "Mas ele está acabando muito ultimamente. Olha, ele não sabe para onde foi de novo.",
  [818107786786048] = "Compramos especialmente para ele um baralho; ele adora e nunca deixa sair de suas mãos.",
  [818107786785792] = "Nosso irmão mais novo. Embora não entenda muito bem as regras, ele adora jogar pôquer.",
  [818107786785536] = "Quem é o Jeremy que você mencionou?",
  [818107786785280] = "Esqueça, eu realmente não gosto de beber.",
  [818107786785024] = "Wuu wuu... Ok, wuu wuu...",
  [818107786784768] = "Você... hum, não fique triste! O vinho sempre acabará!",
  [818107786784512] = "Wuu wuu... Mamãe disse que quando o vinho desta loja acabar, ela me deixará sair e viajar...",
  [818107786784256] = "Ninguém nunca viu o chefe desta loja e ninguém sabe quando coloca o vinho!",
  [818107786784000] = "Sempre cheio? Parece que chefe é uma pessoa muito diligente.",
  [818107786783744] = "Ah, oi, você quer uma bebida? Basta pegar uma xícara; o barril está sempre cheio.",
  [818107786783488] = "O que você disse... também faz sentido.",
  [818107786783232] = "Sim, e os banheiros são para as pessoas usarem!",
  [818107786782976] = "Hum? Mas isso é um ninho de pássaro...",
  [818107786782720] = "O que você está falando? Os gatos deveriam dormir em ninhos de pássaros, não é?",
  [818107786782464] = "Um gatinho dormindo em um ninho de passarinho, um gato muito especial mesmo.",
  [818107786782208] = "Bem, na verdade, você só precisa saber por si mesmo.",
  [818107786781952] = "Oh, minha querida Olivia, como posso descrever os olhos dela para você...",
  [818107786781696] = "Sim, tenho que encontrar um nenúfar adequado para minha esposa antes de poder me casar com ela e trazê-la para casa.",
  [818107786781440] = "O que você está fazendo? Escolhendo nenúfares?",
  [818107786781184] = "Parece que vocês dois são muito amorosos. Desejo-lhe felicidade!",
  [818107786780928] = "Ele quer escolher o nenúfar mais lindo e macio para mim. Que idiota!",
  [818107786780672] = "Suspirar! Na verdade, acho que esse costume poderia ser cancelado, mas ele insiste em fazer isso.",
  [818107786780416] = "Meu marido, Kira, foi ao lago atrás da igreja colher nenúfares. Este é um costume em nossa cidade.",
  [818107786780160] = "Casamento feliz, mas você não parece muito feliz?",
  [818107786779904] = "Pare de ficar no ninho do pássaro! Desça e eu lhe darei algo delicioso!",
  [818107786779648] = "Só o nenúfar mais lindo e macio é como a minha querida Olivia.",
  [818107786779392] = "Kira, você deve voltar em segurança...",
  [818107786779136] = "Claro! Diz-se que neste vinho fabricado também está a bênção da fada para nós!",
  [818107786778880] = "Cerveja de nenúfar? É feito com flores de lótus?",
  [818107786778624] = "Um rosto que eu nunca vi antes, você não é local, não é? Você gostaria de experimentar a cerveja de nenúfar que fiz?",
  [818107786778368] = "Vou esperar o lojista voltar.",
  [818107786777344] = "É melhor perguntar da próxima vez.",
  [818107786777088] = "Mesmo se você escolher um ou dois, os nenúfares voltarão a crescer no dia seguinte. Isso tudo é bênção da fada!",
  [818107786776832] = "Quem quiser admirar a beleza dos nenúfares pode simplesmente ir até a beira do lago!",
  [818107786776576] = "Os nenúfares são muito sagrados para nós, como poderíamos vendê-los?",
  [818107786776320] = "Nenúfares? ...Oh! Você é um viajante, certo?",
  [818107786776064] = "Você não vende nenúfares aqui?",
  [818107786775808] = "<P_Heart> (Esta é a Cidade dos Nenúfares, mas não parece haver... nenhum nenúfar na barraca de flores?) </>",
  [818107786775552] = "Hmm... é melhor voltar mais tarde.",
  [818107786775296] = "Shh! Pai, fale menos... Não é fácil conseguir um cliente! Você toma seu remédio primeiro!",
  [818107786775040] = "Que tomates! Essas são flores do sono profundo!",
  [818107786774784] = "Sim, temos os tomates mais doces aqui! Você gostaria de experimentar alguns?",
  [818107786774528] = "Materiais rituais? Isto não é uma barraca de vegetais?",
  [818107786774272] = "Um desempenho brilhante. Peço desculpas pelo meu desprezo por você. Da próxima vez, priorizarei encontrar você, amigo.",
  [818107786774016] = "Esta é a nossa única pista para encontrar a Fada do Nenúfar; não podemos desistir, não importa o que aconteça!",
  [818107786773760] = "Na pior das hipóteses, procuraremos um por um!",
  [818107786773504] = "Isso seria um círculo; onde é meio-dia?",
  [818107786773248] = "Poderia ser a orientação? Se você olhar para a cidade inteira como um relógio.",
  [818107786771712] = "Seu espiritualidade é realmente perspicaz para conseguir me encontrar escondido. \n Por que não brincar de esconde-esconde? Encontre todos os baús de tesouro próximos e você poderá abrir meu tesouro.",
  [818107786770432] = "Ela nasceu durante a noite e, com dois estalar de dedos, esta cidade foi estabelecida.",
  [818107786770176] = "A lendária Fada do Nenúfar...",
  [818107786769920] = "Ah, olha, o protagonista maluco apareceu.",
  [818107786769664] = "Mas se alguém estiver disposto a me ajudar a resolver esse problema, certamente serei muito bem-vindo. Há muito que estou cansado dos dramas de Tingen; deixe aquele festival de drama maluco se perder!",
  [818107786769408] = "Embora no momento em que te vi, eu soubesse que aquele bastardo do Trevor não era sincero.",
  [818107786769152] = "Aquele dramaturgo maluco me mandou um ingresso de teatro queimado, me pedindo para assistir a uma apresentação neste cruzamento.",
  [818107786768896] = "Estou sendo alvo de um dramaturgo maluco! Trevor disse que alguém viria me ajudar.",
  [818107786768640] = "Lembro que as 'Algemas de Empatia' precisam ser feitas desta e daquela forma para serem desbloqueadas com segurança...",
  [818107786768384] = "Deixe esta senhora comigo; profissionais virão ajudá-la a lidar com a perda de controle. Você se saiu bem.",
  [818107786768128] = "Quando ele voltar, vou lhe dizer o que penso!",
  [818107786767872] = "Este Artefato Selado deve ser usado por um Beyonder de Sequência 7 ou superior para resistir às alucinações que ele produz.",
  [818107786767616] = "Você está dizendo que Trevor pediu para você usar \"Algemas de Empatia\" para suprimir a perda de controle de Beyonder!?",
  [818107786766848] = "<P_Heart> (Um lamento doloroso vem da Bruxa ao lado) </>",
  [818107786766592] = "Os cuidados são: <P_Yellow> manter uma boa distância e não quebrar a conexão formada por espiritualidade </> , e também...",
  [818107786766336] = "Este é o Artefato Selado “Algemas de Empatia” que o Oficial Trevor me pediu para lhe dar. Ele disse que você pode usar isso para suprimir temporariamente o processo de perda de controle dela.",
  [818107786766080] = "Ouvi dizer que foi influenciado por emoções extremas. Esta bruxa explodiu com sentimentos extremamente intensos por seu ex-amante, tornando seu estado muito instável.",
  [818107786765824] = "Sênior, você finalmente chegou! Nosso esquadrão encontrou uma bruxa à beira da perda de controle e precisa que você a acompanhe até o Vigias Noturnos para entrega.",
  [818107786765568] = "A misteriosa imagem deixou apenas uma frase e não tem capacidade de comunicação.",
  [818107786765312] = "Capitão de Cavalaria da Primeira Legião da Família Wessel! Use sua alabarda para conquistar a vitória e forjar a glória!",
  [818107786765056] = "Reivindique sua recompensa; é o que você merece.",
  [818107786764800] = "O julgamento termina aqui! Você já me provou que possui força suficiente.",
  [818107786764544] = "Você conhece essa regra há muito tempo.",
  [818107786764288] = "Se você quiser, você mesmo tem que vir buscá-lo.",
  [818107786764032] = "Há algo que você precisa?",
  [818107786763776] = "Olá, sócio do Clube. O \"Fantasma da Ópera\" está prestes a começar. Você gostaria de saber mais?",
  [818107786763520] = "Eu sei que você não é policial, mas confio em você. Este passe permitirá que você entre diretamente.",
  [818107786763264] = "Os presos muitas vezes gritam no meio da noite, e os guardas prisionais inexplicavelmente se perdem durante a patrulha, retornando ao ponto de partida enquanto caminham. Ainda mais estranho, um cara que estava preso há um ano de repente gritou em sua cela na noite de anteontem: 'O minuto acabou de novo'... Quando questionado sobre o que ele queria dizer, ele apenas segurou a cabeça, sua cabeça dividindo-se de dor.",
  [818107786763008] = "Deixe a pessoa conosco. Ele será enviado para aquela 'Prisão Eterna' – você já ouviu falar disso, certo? Aquela prisão misteriosa.",
  [818107786762752] = "Há marcas de impacto na frente da carruagem, mas a pessoa foi trazida de volta intacta. Você trabalhou com muita eficiência, Consultor {Sr. {EM. |}}.",
  [818107786762496] = "Além disso, você deve seguir as regras, caso contrário nosso pessoal pedirá que você saia a qualquer momento.",
  [818107786762240] = "Consultor {Sr. {EM. |}}, você pode entrar, mas deve se preparar mentalmente…",
  [818107786761984] = "“Consultor”… Entendo, o Velho Cui enviou você.",
  [818107786761728] = "Boa noite, sou consultor do “Gabinete de Consulta de Casos Especiais”. A situação aqui pode exigir uma avaliação de uma “perspectiva especial”.",
  [818107786761472] = "Por favor, pare, {Sr. {EM. |}}! A área à frente está isolada. A polícia está investigando, pessoal não autorizado, por favor, fique para trás.",
  [818107786761216] = "As Sete Provações irão forjar sua vantagem. Eu pergunto! Você está pronto?",
  [818107786760960] = "Cavaleiro diante de mim, prove que você está qualificado para servir como Capitão de Cavalaria da Primeira Legião da Família Wessel.",
  [818107786760704] = "É isso. Bem, espero que você tenha uma estadia agradável!",
  [818107786759936] = "Ah, vamos colocar desta forma: você conhecerá algumas pessoas vendendo antiguidades e coisas assim. Isso... bem, vou apenas dizer uma coisa, você pode julgar por si mesmo.",
  [818107786759680] = "Hmm, é muito tranquilo aqui, não há nada particularmente especial...",
  [818107786759424] = "Há algo a que prestar atenção ao visitar a cidade?",
  [818107786759168] = "Quase não há coisas novas acontecendo nesta cidade durante todo o ano. Ocasionalmente, ando por aí e ajudo viajantes que são novos neste lugar.",
  [818107786758912] = "Sou um sargento aposentado com algumas doenças antigas, então só posso voltar para casa para me recuperar. Mas não posso ficar ocioso, então é melhor arranjar algo para fazer.",
  [818107786758656] = "Ahem, chamando isso de patrulheiro... na verdade, é apenas meu passatempo.",
  [818107786758400] = "Você é o patrulheiro aqui? Quais são suas responsabilidades habituais?",
  [818107786758144] = "A praça da taberna também merece uma visita, não só a comida por lá é deliciosa, mas também há apresentações de bandas! Aliás, se você tiver oportunidade, pode dar uma olhada naquela loja da esquina. O lugar deles é realmente...",
  [818107786757888] = "Na cidade existem também duas pequenas praças, que no passado teriam feito parte do território do castelo. Agora todo mundo gosta de organizar atividades nesses locais, e às vezes é muito animado.",
  [818107786757632] = "A paisagem aqui é linda, a cidade é aconchegante e, o mais importante, o Castelo Lamud – os visitantes definitivamente não vão perder.",
  [818107786757376] = "Então você perguntou à pessoa certa! Esta é uma ótima cidade turística. Muitas pessoas de cidades próximas – especialmente Tingen – estão dispostas a fazer uma viagem no fim de semana.",
  [818107786757120] = "Olá, Sargento Aaron, você deve conhecer muito bem este lugar, estaria disposto a me contar sobre isso?",
  [818107786756864] = "Olá! Bem-vindo à cidade de Lamud! Sou o sargento Aaron, o patrulheiro da cidade!",
  [818107786756608] = "Há mais alguma coisa que você queira saber? Informações sobre ex-administradores da cidade? Mapas de trânsito pela cidade? Eu tenho tudo aqui!",
  [818107786756352] = "Eu estudo história morta, mas eles... o que eles e Jack vivenciaram foi uma história que ganhou vida. A verdade desta parte provavelmente ficará enterrada para sempre sob as fundações do castelo.",
  [818107786756096] = "Ele era um carpinteiro decente, mas depois disso enlouqueceu. Suspeito que ele poderia estar por perto naquele dia e ter visto algo que não deveria.",
  [818107786755840] = "Depois que eles partiram, duas coisas mudaram. Um deles era o castelo; aquela sensação estranha desapareceu. O segundo foi o Velho Jack — ah, esse é o louco que agora guarda os trilhos do trem.",
  [818107786755584] = "Seus trajes eram muito atraentes e eles perguntavam sobre a situação em todos os lugares. Suspeito que fossem de alguma organização oficial especial.",
  [818107786755328] = "Sim, há alguns anos, por um período, o castelo ficou muito estranho e todos que foram para lá sentiram que algo estava vagamente errado. Durante esse tempo, um grupo de pessoas com sobretudos pretos veio aqui e foi direto para o castelo.",
  [818107786755072] = "<P_Heart> (Solenemente) </> Você pergunta sobre isso... parece que você está interessado em mais do que apenas belas paisagens e antiguidades.",
  [818107786754816] = "Ouvi dizer que há alguns anos um grupo de pessoas especiais veio aqui?",
  [818107786754560] = "Só um velho como eu, nascido aqui e criado aqui, está disposto a registrar tudo isso e tratar a história como um tesouro.",
  [818107786754304] = "Você deve ter conhecido muitos caras tentando lhe vender antiguidades ao longo do caminho, e aqueles que se oferecem para levá-lo para explorar – as pessoas hoje em dia não têm nenhum respeito pela história!",
  [818107786754048] = "Visualizar? No passado, era uma admiração, e eles andavam por aí. Agora, é ganância, pensar em desenterrar algumas 'antiguidades' lá dentro para trocar por dinheiro para bebidas!",
  [818107786753792] = "Como as pessoas da cidade veem o castelo agora?",
  [818107786753536] = "Tudo o que fiz foi juntar essas lendas com a idade dos tijolos e das pedras, e a verdade... Receio que já tenha afundado há muito tempo no longo rio da história.",
  [818107786753280] = "Alguns dizem que a família violou um tabu secreto; outros dizem que desapareceram durante a noite. O que posso ter certeza é que depois deles, o castelo perdeu seu mestre de longa data e gradualmente se tornou o lugar que você vê agora, cercado de mistério e horror, ao longo do tempo.",
  [818107786753024] = "Quanto ao motivo do declínio da Família Lamud e ao abandono do castelo, a história oficial não o registra. Apenas um vago folclore foi transmitido.",
  [818107786752768] = "O primeiro proprietário do castelo era conhecido como Barão Lamud, e estima-se que seu período ativo tenha ocorrido no final da Quarta Época - isto é, cerca de treze ou mil e quatrocentos anos atrás.",
  [818107786752512] = "De acordo com os primeiros registros seculares que pude encontrar, misturados com os arquivos da igreja — aham, não me pergunte por que eu procuraria esse conhecimento comum — rigor! Esta é a qualidade mais importante para um pesquisador!",
  [818107786752256] = "E aquele antigo castelo é o marco mais famoso daqui. Você poderia dizer que o nome da cidade de Lamud vem do Castelo de Lamud.",
  [818107786752000] = "Nossa cidade está localizada a noroeste de Tingen e é o único centro comercial das aldeias vizinhas. Veja esses estilos arquitetônicos; eles quase não foram tocados pela Era do Vapor e ainda mantêm sua aparência anterior.",
  [818107786751744] = "Gostaria de ouvir sobre as origens da cidade e do castelo.",
  [818107786751488] = "Deixe-me me reapresentar, meu nome é Lewis. Estudei uma grande quantidade de dados históricos sobre este lugar. Você pode me chamar de pesquisador histórico... hum, civil, não oficial.",
  [818107786751232] = "<P_Heart> (Olhos iluminam) </> Você está interessado nisso? Meu Deus... finalmente alguém disposto a ouvir um velho divagar?",
  [818107786750976] = "Desculpe, senhor, eu estava um pouco interessado no que você estava vendo.",
  [818107786750720] = "Jovem, não bloqueie minha luz.",
  [818107786750464] = "O que exatamente aconteceu aqui...",
  [818107786750208] = "Castelo antigo, armadura em movimento, cavalheiros em gabardinas pretas... Parece que este cavalheiro testemunhou uma batalha entre suspeitos Beyonders .",
  [818107786749952] = "Não, não, aquela coisa perigosa está nas ruínas do castelo, esperando que as pessoas baixem a guarda. Assim que acharmos que estamos seguros, isso irá... matar todo mundo!",
  [818107786749696] = "Mas parece muito pacífico aqui, a terrível batalha que você mencionou não parece ter afetado as pessoas da cidade.",
  [818107786749440] = "Não posso deixar que outros acabem assim... por favor, não entre, absolutamente não entre!",
  [818107786749184] = "Tentei orar na igreja, mas assim que fechei os olhos pude ver aquela terrível batalha. Definitivamente não foi uma batalha entre humanos... definitivamente não!",
  [818107786748928] = "Por que? Eu... eu não quero que outros acabem assim. Desde que vi aquela cena naquele dia, tudo mudou. É assustador, muito assustador...",
  [818107786748672] = "Por que você está impedindo o trem de entrar?",
  [818107786748416] = "É muito assustador, muito assustador... Devo parar todo mundo! Não posso deixá-los morrer!",
  [818107786748160] = "Eu vi... aquela armadura, uma armadura antiga e manchada de lama, que se movia sozinha. Estava vazio por dentro, mas estava vivo!",
  [818107786747904] = "Toda a equipe entrou no castelo e então... luz e sons! Todos pareciam estar dormindo; aquela cena foi muito estranha...",
  [818107786747648] = "Cavalheiros em sobretudos pretos?",
  [818107786747392] = "Costumava ser apenas um castelo quebrado, não como é agora... não... tudo mudou. Não entre, como aqueles senhores de sobretudo preto, quem sabe o que passaram!",
  [818107786747136] = "Senhor, o que você viu?",
  [818107786746880] = "O trem... não deixe o trem entrar mais! Não deixe mais ninguém entrar! Parar!",
  [818107786746624] = "Você não pode ver... eles não podem ver... só eu posso ver!",
  [818107786746368] = "Feliz por poder servir.",
  [818107786746112] = "Eu entendi! Vou continuar trabalhando no rascunho do design, obrigado!",
  [818107786745856] = "O período árido que vem depois da colheita... vinhas murchas dariam uma boa decoração.",
  [818107786745600] = "Esta é realmente uma terra fértil, talvez use abóboras como tema de design...",
  [818107786745344] = "Ouro... a cor da Árvore da Abundância pode sim ser usada como tom principal.",
  [818107786745088] = "Talvez você possa me dar alguma inspiração? O que Golden Autumn Lake faz você pensar?",
  [818107786744832] = "Ei, você chegou bem na hora. Estou desenhando uma roupa impressionista para Golden Autumn Lake e ainda estou sentindo falta de um pouco de inspiração.",
  [818107786744576] = "Que a beleza da colheita dure para sempre e que a vontade do Santo esteja com você e comigo.",
  [818107786744320] = "Ela transformou seu corpo em uma estátua de pedra, ficando aqui, guardando para sempre a terra fértil que ela criou.",
  [818107786744064] = "…O grande Santo veio para esta terra cheio de conflitos, refinando folhas douradas com compaixão e acalmando a terra cicatrizada com bondade.",
  [818107786743808] = "<P_Heart> (Eles parecem estar falando sobre lendas antigas?) </>",
  [818107786743552] = "Ouvi dizer que os guerreiros que morreram em batalha estão enterrados aqui. Meu gatinho deve ser tão corajoso quanto eles, certo?",
  [818107786743296] = "Papai disse que não poderia ser enterrado com a família... só poderia trazê-lo para cá.",
  [818107786743040] = "…Ah, não é nada bom, meu gatinho caiu no lago e se afogou enquanto pegava um rato.",
  [818107786742784] = "Você parece muito triste, você está bem?",
  [818107786742528] = "Sinto muito, Sisi, só posso enterrar você aqui sozinho... Virei ver você com frequência.",
  [818107786742272] = "Posso nunca mais vê-lo na minha vida, mas eles não podem trancar um cachorrinho, certo?",
  [818107786742016] = "Claro que é roubar – comprar pão! Meu pai foi pego por... comprar um pão e ficará preso por muito, muito tempo.",
  [818107786741760] = "John é esse cachorro? O que você está fazendo?",
  [818107786741504] = "Shh... não distraia John.",
  [818107786741248] = "Vou pedir para Alice fazer uma camisa nova para o médico!",
  [818107786740992] = "Amanhã trarei uma foto para a clínica!",
  [818107786740736] = "O que eu disse, essa criança tem no coração a saúde de toda a cidade... Esse assunto não pode ser apressado.",
  [818107786740480] = "Suspiro, então vá em frente, criança, tome cuidado na estrada.",
  [818107786740224] = "A propósito, senhora, sobre a dor no joelho que você mencionou da última vez, vou preparar a nova pomada e enviar amanhã.",
  [818107786739968] = "Eu... considerarei seriamente as sugestões de todos. Agora, por favor, deixe-me ir trabalhar, os pacientes ainda estão esperando.",
  [818107786739712] = "Exatamente! Olhe para o seu manto, a gola é branca! Qual garota decente não poderia ajudá-lo a mantê-lo arrumado?",
  [818107786739456] = "O trabalho nunca termina! Você simplesmente se preocupa demais! Encontrar uma esposa seria perfeito para cuidar do seu dia a dia!",
  [818107786739200] = "Eu realmente não posso perder tempo pensando nessas coisas. Por favor, abram caminho, preciso ir até a cidade para reabastecer alguns remédios.",
  [818107786738944] = "Obrigado a todos pela gentileza, de verdade. Mas a estação das chuvas está chegando, o reumatismo do Velho John e os gêmeos da casa de Lisa não se recuperaram totalmente da tosse, e muitas pessoas na cidade do sul dizem que estão vindo para tomar vacinas...",
  [818107786738688] = "Porém, doutor, não é solução você morar sempre sozinho em cima da clínica. A colega de classe da filha da tia da amiga do meu primo distante trabalha na Biblioteca e adora ler assim como você.",
  [818107786738432] = "Tudo bem, tudo bem, acalmem-se. O médico é um homem decente, você não deveria pressioná-lo assim.",
  [818107786738176] = "Uma pessoa refinada como o Dr. Parker deveria estar com uma garota delicada, que elegante!",
  [818107786737920] = "Ah, ouça isso! Martha é capaz, mas nossa Alice vem de uma alfaiataria. O rouxinol do lenço que ela bordou parece que vai voar!",
  [818107786737664] = "Minha sobrinha Martha virá para a cidade na próxima semana. Aquela garota é forte e diligente; ela pode comer dois pães pretos em uma refeição! Você deve conhecê-la!",
  [818107786737408] = "Dr. Baker, você finalmente saiu da clínica! Você deve me dar uma resposta definitiva hoje!",
  [818107786737152] = "Senhoras, o que vocês estão fazendo...",
  [818107786736896] = "Da próxima vez que você passar por aqui, se ouvir alguma história sobre pedras ou pinturas estranhas, não deixe de me contar! Posso não ter muito mais, mas tenho muitas histórias e vinho.",
  [818107786736640] = "Este idiota adora sair para pintar. Ele prometeu voltar antes da colheita das abóboras... Esqueça, não vamos falar disso!",
  [818107786736384] = "Ele? Ele é o convidado de longo prazo mais indisciplinado da minha loja... Brincadeirinha! Ele é meu noivo.",
  [818107786736128] = "O que... ele é para você?",
  [818107786735872] = "Se acontecer de você vê-lo um dia, você deve dizer-lhe... dizer-lhe para não esquecer Catherine! A hortelã no parapeito da janela murchará se ele não vier regá-la logo.",
  [818107786735616] = "Suspiro... isso é verdade. Esse cara só gosta de ir a lugares onde não há ninguém, dizendo coisas como “A inspiração está no deserto”.",
  [818107786735360] = "Desculpe, não tenho nenhuma impressão dele.",
  [818107786735104] = "Ele sempre carrega uma velha bolsa de couro, dizendo que quer desenhar todas as pedras estranhas em cada lugar.",
  [818107786734848] = "A propósito, no caminho para cá, você conheceu um homem? Sobre este alto, com cabelos levemente cacheados, uma pequena verruga no queixo esquerdo e um sorriso um tanto bobo...",
  [818107786734592] = "Vivaz? Ha! São todos os mesmos rostos antigos, é tão chato. Adoro ouvir histórias de pessoas como você, que estão sempre em movimento...",
  [818107786734336] = "Eu vim de Tingen. Lamud Town é um lugar bastante animado.",
  [818107786734080] = "Querido, você parece muito estranho. De onde você é? Entre e sente-se um pouco, tome um pouco de vinho quente.",
  [818107786733824] = "Peixe-lobo... uh, de repente me lembrei de alguém que já me convidou para jantar hoje. Vou deixar comida com cheiro forte como peixe-lobo para a próxima vez...",
  [818107786733568] = "Deixe-me verificar os ingredientes...",
  [818107786733312] = "Sweet Breeze of the Ocean, parece muito romântico.",
  [818107786733056] = "Uma torta de peixe é vendida por 1 libra! É melhor vendê-lo ao povo de Backlund!",
  [818107786732800] = "Torta Stargazer, hein? Parece bom. Deixa eu ver o preço... Ah!",
  [818107786732544] = "Amigo, entre a Torta Stargazer e a Doce Brisa do Oceano, qual você recomenda mais?",
  [818107786732288] = "Independentemente de qual dos seus quatro filhos será deixada a sua enorme herança, lembremo-nos dele e deixemo-lo descansar em paz no reino da Deusa.",
  [818107786732032] = "Há poucos dias, ele faleceu devido a uma doença em sua villa. Em breve, um advogado lerá seu testamento.",
  [818107786731776] = "O Sr. Hope era um empresário de Tingen que vinha passar férias todos os anos em nossa cidade de Lamud, dando uma grande contribuição para a economia de nossa cidade.",
  [818107786731520] = "Hoje, a razão pela qual nos reunimos aqui é para prestar nossos respeitos ao nosso velho amigo, Sr. Hope.",
  [818107786731264] = "Nada mal... está... muito quente aqui...",
  [818107786731008] = "Esta noite... a casa de quem devo ir...",
  [818107786730752] = "<P_Heart> (Ei, é melhor você acreditar!) </>",
  [818107786730496] = "Cara inútil! Vamos ver quem acredita em você!",
  [818107786730240] = "Parar! Você sente uma brisa fria? Está tão frio...",
  [818107786729984] = "Claramente foi você quem chorou e chamou pela sua mamãe!",
  [818107786729728] = "Ei, quando fomos explorar o antigo castelo quando crianças, quem estava com medo de fazer xixi nas calças? Afinal, o castelo pertencia ao senhor que governou aqui há mais de mil anos; você ficou com medo, não foi?",
  [818107786729472] = "Nikola, quantos anos você tem e ainda acredita nessas coisas.",
  [818107786729216] = "Quando estou dormindo, sinto que algo está me pressionando. Não importa o quanto eu lute, não consigo sentar!",
  [818107786728960] = "Ainda não é horário de funcionamento, me recuso a atendê-lo! Adeus!",
  [818107786728704] = "Você-",
  [818107786728448] = "Em segundo lugar, dois dias por mês, esse mendigo está de folga!",
  [818107786727168] = "Leve de volta.",
  [818107786726912] = "<P_Heart> (Que mendigo lamentável, dê-lhe algumas moedas.) </>",
  [818107786726656] = "Eu apenas traduzi seu cardápio!",
  [818107786726400] = "…Já que você não parece querer jantar, por favor, saia.",
  [818107786726144] = "Ah, então é um cheesecake fedorento.",
  [818107786725888] = "Para sobremesa, recomendo a 'Doce Brisa do Oceano'. Não usamos peixe-lobo enlatado; em vez disso, insistimos em fazer a nossa própria pasta de peixe-lobo, misturá-la com leite, queijo e açúcar e assá-la até formar uma massa...",
  [818107786725632] = "Ah, então é uma torta feita de peixe.",
  [818107786725376] = "Torta Olhando para as Estrelas! O nome vem da imagem de peixes saltando do mar para contemplar as estrelas. Utiliza peixe fresco do rio do condado de Midseashire, temperado com manteiga de alta qualidade do condado de Winter e farinha de Backlund...",
  [818107786725120] = "Qual é o prato de assinatura aqui?",
  [818107786724864] = "Olá, sou Marilyn, a gerente aqui. Quer que eu recomende alguns pratos?",
  [818107786724608] = "Princesa? Quem é a princesa? Por que eu iria querer salvá-la?",
  [818107786724352] = "Ei, Tommy, você ainda não vai salvar a princesa?",
  [818107786724096] = "Essa flor é linda, aquela flor também é linda, esse bicho é fofo, aquele bicho também é fofo! Talvez eu devesse ir colher algumas uvas...",
  [818107786723840] = "Oh não! Esqueci que ainda tem uma princesa me esperando para salvá-la!",
  [818107786723072] = "Praticando esgrima?",
  [818107786722816] = "Ei! Hah! Eu ataquei!",
  [818107786722560] = "Não é isso, eles devem ter esquecido de mim! Vou para casa reclamar!",
  [818107786722304] = "Talvez eles estejam trabalhando duro para descobrir onde está a princesa.",
  [818107786722048] = "Já faz tanto tempo e nenhum chegou!",
  [818107786721792] = "Eu sou uma princesa! Meus heróis prometeram que derrotariam o dragão maligno e salvariam nosso reino! Mas, mas...",
  [818107786721536] = "Pequena, por que você está chorando aqui sozinha?",
  [818107786721280] = "Wuu wuu wuu, onde estão as pessoas? Para onde todos foram?",
  [818107786721024] = "Rugido rugido, rugido rugido? <P_Heart> (Então, você está pronto?) </>",
  [818107786720768] = "Hmm, wuu wuu. <P_Heart> (Eu decidi, por favor, deixe-me acompanhá-lo.) </>",
  [818107786720512] = "Rugido? <P_Heart> (Oh? Você veio de novo.) </>",
  [818107786720256] = "Parece que não gosta de ser incomodado.",
  [818107786720000] = "Rugido rugido! Rugido rugido!",
  [818107786719744] = "Parece estar espiando aquele grupo de sua própria espécie...",
  [818107786719488] = "Por que esse babuíno parece tão infeliz?",
  [818107786719232] = "<P_Heart> (Deprimido) </> Wuu... wuu...",
  [818107786718976] = "Os fragmentos reconstituíram o paradeiro do criminoso. Vamos embora agora?",
  [818107786718720] = "Ajude-me a coletar os fragmentos de espiritualidade traços aqui; Preciso distinguir e juntar os verdadeiros movimentos do alvo.",
  [818107786718464] = "O Capitão Frye está esperando por você no Escritório.",
  [818107786718208] = "Está tudo bem, este é o meu trabalho também.",
  [818107786717952] = "Você finalmente está aqui. O número de Beyonder casos tem aumentado recentemente e precisamos de mais mão de obra. Obrigado pelo seu trabalho duro!",
  [818107786717696] = "Não há tempo a perder; precisamos agir imediatamente.",
  [818107786717440] = "Você está aqui. Veja este relatório: \"Ocorreu uma explosão em uma fábrica de chumbo na área das docas esta manhã.\" Suspeitamos que este seja o local oculto de comércio do mercado negro em Tingen.",
  [818107786717184] = "O Guia de Viagem se desdobra e se transforma em uma porta.",
  [818107786716416] = "O Artefato Selado foi visto pela última vez em uma fábrica de chumbo. Xiga investigará com você para recuperar o Artefato Selado perdido.",
  [818107786716160] = "A Igreja perdeu um Artefato Selado e as investigações sugerem que ele pode ter ido para o mercado negro.",
  [818107786715904] = "{{PlayerName}}, há um caso urgente que gostaria de confiar a você.",
  [818107786715648] = "Tenho que verificar esta noite para ver se há realmente um coelho competindo conosco pelos crentes.",
  [818107786715392] = "Mas nunca ouvi falar de nenhum culto que adorasse um coelho, e o ritual de oração também não parece malvado...",
  [818107786715136] = "Ouvi isso do ferreiro da taverna; ele disse que é ainda mais eficaz do que rezar para a Deusa... Ah, não, Deusa, eu não quis dizer isso!",
  [818107786714880] = "Minha filha ouviu isso na escola. Ela disse que a empregada da casa de sua colega viu com seus próprios olhos.",
  [818107786714624] = "Onde diabos vocês ouviram essas coisas?",
  [818107786714368] = "Errado! A versão que ouvi foi um coelho cinza usando cartola.",
  [818107786714112] = "A chave deve ser o Deus Coelho com pelo prateado, que dizem estar na floresta próxima.",
  [818107786713856] = "Então... o que esse culto adora? A lua cheia ou o nascer do sol?",
  [818107786713600] = "O relógio de bolso que perdi no mês passado realmente apareceu na mesa de jantar três dias depois!",
  [818107786713344] = "Isso não está certo! A revelação que recebi foi fazer uma reverência ao castelo dez vezes quando o sol nascer, e os itens perdidos retornarão automaticamente.",
  [818107786713088] = "Na época, minha filha me disse que enterrar uma abóbora no quintal numa noite de lua cheia faria uma criança doente melhorar. A tosse do meu filho melhorou, então eu...",
  [818107786712832] = "Bispo, confesso a você, nossa família já adora aquele “Deus Coelho” há algum tempo. Traímos a nossa lealdade à Deusa...",
  [818107786712576] = "…Que poema de amor cafona, será que consigo encontrar o dono seguindo o cachorrinho?",
  [818107786711808] = "Agora vou continuar mexendo na cota de curiosidade dele!",
  [818107786711552] = "Mesmo quando ele faleceu, foi a mesma coisa. Tínhamos apenas vinte e poucos anos. Ele disse: 'Carl, na verdade, essas suas ideias malucas nunca terão sucesso. Mas adoro o jeito que você mexe nas coisas!",
  [818107786711296] = "Minha melhor amiga sempre me disse isso também.",
  [818107786711040] = "Voando com balões? Isso não parece muito provável.",
  [818107786710784] = "Até hoje, amarrando balões no telhado, senti uma alegria há muito perdida. Quanto a saber se ele pode realmente voar, isso não é mais importante.",
  [818107786710528] = "Haha, bem dito! Quando eu era jovem, queria ser um aventureiro, mas esperei e esperei, e agora minha vida está chegando ao fim sem nada para mostrar!",
  [818107786710272] = "Talvez seja realmente possível?",
  [818107786710016] = "Quero pegar minha casa e voar para o céu! Jovem, você acha que eu consigo?",
  [818107786709760] = "O que você está fazendo aqui?",
  [818107786709504] = "Se esse grupo não trabalhar mais, nossa banda estará no mesmo nível da banda da terceira idade da cidade!",
  [818107786709248] = "Esta é a pior banda que já liderei!",
  [818107786708992] = "Lanyi, alguém deve ter te machucado de propósito! Vou falar com o Sr. Jim!",
  [818107786708736] = "Paula, minha garganta, o que aconteceu com minha garganta?",
  [818107786708480] = "O que... está acontecendo... estava... bem ontem...",
  [818107786708224] = "La la la la la - tosse, tosse! Tosse tosse!",
  [818107786707968] = "Ei, serei o guitarrista número um em Lamud Town. Você quer essa sorte ou não?",
  [818107786707712] = "Não há necessidade de praticar, você pode descansar um pouco mais. Talvez seja um golpe de sorte?",
  [818107786706944] = "<P_Heart> (Mas por que itens domésticos novos flutuam no rio!) </>",
  [818107786706688] = "Que criança econômica e boa!",
  [818107786706432] = "Vestidos lindos, flores frescas, rolos de massa úteis... Levo para mamãe, e mamãe gosta muito deles.",
  [818107786705664] = "Ontem pesquei um buquê de rosas; o que posso pescar hoje?",
  [818107786705408] = "O que será pescado hoje?",
  [818107786705152] = "…Tudo é negociável, tudo é negociável.",
  [818107786704896] = "Certo! Se você quer que eu continue trabalhando, você tem que pagar mais! Caso contrário, entrarei em greve!",
  [818107786704640] = "Por que contratar alguém? Faça-o pagar mais!",
  [818107786704384] = "…Se alguém estiver disposto a fazer isso, não é impossível.",
  [818107786704128] = "Você ouviu isso, Sr. Ruby? Se você não contratar ninguém, eu vou pedir demissão!",
  [818107786703872] = "Você definitivamente deveria contratar mais pessoas!",
  [818107786703616] = "{Senhor. {EM. |}}, você é o juiz. É errado eu pedir ao Sr. Ruby para contratar mais uma pessoa para ajudar!",
  [818107786703360] = "Tosse, eu nunca disse isso.",
  [818107786703104] = "Isso é! Mas meu chefe , o Sr. Ruby aqui, não tem intenção de contratar um ajudante para mim.",
  [818107786702848] = "Parece um trabalho muito cansativo.",
  [818107786702592] = "Sou responsável pela limpeza do rio em redor da aldeia, mas todos os dias novos resíduos domésticos se acumulam no rio. Trabalho até meia-noite todos os dias, mas o rio nunca fica limpo.",
  [818107786702336] = "Posso perguntar o que aconteceu?",
  [818107786702080] = "Pensando em você, Maria. Com amor, Nate.",
  [818107786701824] = "…Você desapareceu nesta água há trinta anos, eu trago coisas para você todos os dias, mas você não quer voltar para me ver…",
  [818107786701568] = "Acabei de jogar uma rosa ontem; não há flores hoje, trago algumas para você amanhã!",
  [818107786701312] = "Está sempre chovendo na cidade! Aqui está um guarda-chuva para você também!",
  [818107786701056] = "Aqui, Mary, hoje vou te dar a bota esquerda; combina perfeitamente com o que você recebeu no ano passado!",
  [818107786700800] = "Eu suspeito que você está me insultando...",
  [818107786700544] = "Ei, o que há de errado em gostar de caras bonitos? Só cometi um erro que toda mulher do Continente Norte cometeria! Não estou em um relacionamento e não tive filhos...",
  [818107786700288] = "Você realmente não se contém, não é?",
  [818107786700032] = "Burnier é careca, Anselmo fala manso; Eu irei com Baker, pelo menos ele é lindo!",
  [818107786699264] = "Usei todo o dinheiro que recebi de Clara com nossos filhos; Definitivamente não estou escondendo nada!",
  [818107786699008] = "<P_Heart> (Uau... como ele pode dizer isso com tanta firmeza? Ele é claramente um pedaço de lixo!) </>",
  [818107786698752] = "Eu estava logo atrás dos quilos de Clara. Não se preocupe, eu absolutamente nunca trairei nossa casinha!",
  [818107786698496] = "Minha esposa é só você! Sempre será apenas você!",
  [818107786698240] = "Só bebi um pouco demais; Não tenho sentimentos por ela!",
  [818107786697984] = "Belinda, me escute! Ela me seduziu!",
  [818107786697728] = "Diga-me, você ficou com Clara!",
  [818107786697472] = "Aquele velho não fez uma única boa ação mesmo depois de morrer! Eu deveria ter dado a ele mais algumas doses de veneno!",
  [818107786697216] = "Pai? Pfft, ele nunca me tratou como seu próprio filho! Veja como ele preparou apenas o terceiro, Edgar, e você saberá!",
  [818107786696960] = "Não tenho certeza. Subornei o valete pessoal do seu pai e foi ele quem me contou esta notícia.",
  [818107786696704] = "Você está dizendo que meu pai escondeu o testamento aqui? Isso é real? Se posso obter a herança depende disso.",
  [818107786696448] = "Faça um movimento!",
  [818107786696192] = "Devemos fazer um movimento?",
  [818107786695936] = "Na verdade, meu pai achava que lhe devia muito. Quanto a mim, heh, pareço ser valorizado, mas na verdade sou tratado apenas como uma ferramenta! Eu não me importo com a herança!",
  [818107786695680] = "Ele sempre pensou que o pai o deixava correr solto porque era filho adotivo e não o valorizava! Como resultado, ele adquiriu o hábito de pequenos furtos! Suspirar!",
  [818107786695424] = "Heh, temo que nem o mais novo saiba disso.",
  [818107786695168] = "Somos quatro irmãos. O mais velho tem problemas de saúde mental, o segundo tem problemas de saúde física e nosso pai nunca os maltratou. Mas o mais novo, Finnian, é um filho ilegítimo que o pai teve com outra mulher, mas o pai mentiu ao público, alegando que era uma criança adotada nas favelas.",
  [818107786694912] = "Como ele foi tendencioso?",
  [818107786694656] = "Todos os parentes dizem que sou o mais firme, mas só eu sei o quanto meu pai era tendencioso.",
  [1152288991241216] = "O que você está procurando?",
  [818107786694144] = "Meu pai está morto.",
  [818107786693888] = "<P_Heart> (Essa pessoa está representando algum tipo de peça melodramática...) </>",
  [818107786693632] = "Huh? Não quero saber tanto... Isso parece perigoso.",
  [818107786693376] = "Antes de morrer, devo te dizer, na verdade aquele meu irmão mais velho é filho póstumo do primeiro amor da minha mãe... Ele não é louco de verdade, ele está fingindo!",
  [818107786693120] = "Tosse tosse tosse tosse tosse tosse tosse tosse - ah, não, vou morrer agora -",
  [818107786692864] = "Tio Hope faleceu muito de repente, e esses seus três irmãos são todos duros de quebrar... mesmo que você me peça para ficar do seu lado, é...",
  [818107786692608] = "Olhe para mim, fraco e incapaz de cuidar de mim mesmo. Se eu não conseguir a herança, tenho medo de morrer...",
  [818107786692352] = "O médico disse que minha tosse com sangue era uma doença pulmonar que contraí por cuidar do meu pai... mas o advogado disse que, sem testamento, a herança deve ser dividida igualmente!",
  [818107786692096] = "Tosse, tosse, Root, o que devo fazer?",
  [818107786691840] = "…Arthur, continue sentado, pare de falar.",
  [818107786691584] = "Quem exatamente me matou e quem eu matei?",
  [818107786691328] = "Eu, eu o matei. Quem sou eu? Eu sou Arthur... Quem é ele? Ele é Hope... Quem eu matei? Quem me matou?",
  [818107786691072] = "Quem matou quem?",
  [818107786690816] = "Eu o matei, eu o matei! Eu matei meu pai!",
  [818107786690560] = "Altura de começar! Altura de começar! Por que a rica Hope of Lamud Town morreu durante a noite?",
  [818107786690304] = "Pode ser uma surpresa para qualquer um. O mais precioso não é o que está na caixa, mas os inúmeros mundos maravilhosos que nascem nos telhados.",
  [818107786690048] = "Isso é uma surpresa deixada para as crianças?",
  [818107786689792] = "Enterrei tesouros na direção que as espadas dos cavaleiros apontavam. Talvez eles não tenham sido encontrados até hoje.",
  [818107786689536] = "Mais tarde, todas as crianças da cidade começaram a contar as suas próprias histórias de cavaleiros e dragões. Edmund, Ray e Luna... essas histórias foram todas ouvidas por mim.",
  [818107786689280] = "Meu pai e minha mãe estão em um lugar muito distante. Naqueles dias sem companhia, comecei a imaginar a história do pequeno cavaleiro e do dragão malvado e contei-a às crianças da cidade...",
  [818107786689024] = "Você vê este pequeno cavaleiro de madeira esculpido ao meu lado? Você pode encontrá-los em muitos telhados da cidade.",
  [818107786688768] = "Olá, há algo especial no telhado?",
  [818107786688512] = "Olá, estranho. Você também está aqui na cobertura para curtir um momento de paz?",
  [818107786688256] = "Assim como Ray e eu sempre fazemos as pazes depois de discutirmos!",
  [818107786688000] = "Entendo! Na verdade, eles são melhores amigos!",
  [818107786687744] = "Talvez o cavaleiro estivesse ajudando seu amigo dragão a se acalmar?",
  [818107786687488] = "Então o cavaleiro não deveria ajudá-lo a encontrar o que procura em vez de lutar...",
  [818107786687232] = "Então estava cuspindo fogo para fornecer luz? E as nuvens escuras estavam tristes?",
  [818107786686976] = "Então talvez estivesse procurando por alguma coisa! Assim como fico ansioso quando não consigo encontrar meu ursinho de pelúcia.",
  [818107786686720] = "Talvez tenha se perdido? A mãe diz que algumas pessoas têm acessos de raiva quando estão com medo.",
  [818107786686464] = "Porque... porque é um dragão malvado!",
  [818107786686208] = "Por que o dragão veio atacar este lugar?",
  [818107786685952] = "Eram nuvens escuras! Você não estava ouvindo a história direito!",
  [818107786685696] = "O dragão malvado estava claramente vomitando bolas de fogo!",
  [818107786685440] = "Não, não, o cavaleiro dividiu as nuvens escuras expelidas pelo dragão malvado, e a luz do sol brilhou, afastando o dragão malvado!",
  [818107786685184] = "A espada de um cavaleiro pode partir as escamas de um dragão perverso!",
  [818107786684928] = "Obrigado, {Sr. {EM. |}}. Esta é apenas a minha história; talvez outros cavaleiros experimentem aventuras ainda mais magníficas.",
  [818107786684672] = "Ele empurrou a porta do reino dos mortos e viu sua irmã ali, preparando chá de dente-de-leão, com panquecas de mel para dois sempre postas na mesa...",
  [818107786684416] = "Não, este é um bom final.",
  [818107786684160] = "Que história triste.",
  [818107786683904] = "Não, no final, o Cavaleiro Cavalo de Madeira caiu e pequenas flores brancas floresceram ao redor de sua armadura.",
  [818107786683648] = "Ele derrotou o dragão perverso?",
  [818107786683392] = "No fim...",
  [818107786683136] = "O Cavaleiro do Cavalo de Madeira lutou contra o dragão aqui por sete dias e sete noites. A ponta da lança quebrou, seus olhos ficaram cegos e ele se perdeu na névoa negra expelida pelo dragão.",
  [818107786682880] = "Hum, esse é o nome dele. Há muito, muito tempo, uma bela vila foi atacada por um dragão. O Cavaleiro Cavalo de Madeira perdeu sua amada irmã naquele desastre, então decidiu se tornar um cavaleiro e se vingar do dragão.",
  [818107786682624] = "Vou ficar com o Cavaleiro Cavalo de Madeira. Está muito quieto aqui.",
  [818107786682368] = "Pequenino, o que você está fazendo no telhado?",
  [818107786682112] = "…Hehe, agora eu cuido da minha roupa todos os dias, disfarçando o cheiro, todo mundo vai falar comigo então?",
  [818107786681856] = "Também senti cheiro de bergamota e... alecrim?",
  [818107786681600] = "Cheiro muito mal, como cadáveres e musgo.",
  [818107786681344] = "Por que? Você parece bastante amigável.",
  [818107786681088] = "Uau! Você me assustou... Quer dizer, poucas pessoas falam comigo, exceto esses passarinhos.",
  [818107786680832] = "Ocasionalmente, posso sentir o cheiro de bergamota e alecrim nele em meus sonhos... mas se eu falasse, definitivamente o assustaria, certo?",
  [818107786680576] = "Sim... Todas as semanas, à noite, ele prepara comida e flores para mim, mas nunca me vê e nunca diz uma palavra.",
  [818107786680320] = "Você esteve de frente para o cruzamento o tempo todo. Você está esperando por alguém?",
  [818107786680064] = "Se ao menos houvesse uma pessoa gentil e capaz que pudesse me ajudar a pegar alguns coelhos na floresta...",
  [818107786679808] = "Sim, comprei alguns coelhos e pássaros de um comerciante, mas sua cadeia de abastecimento enfrentou problemas.",
  [818107786679552] = "Você parece um pouco perturbado?",
  [818107786679296] = "Suspiro, ter uma noiva muito fofa também é bastante problemático.",
  [818107786679040] = "Ela realmente gostou do anel que eu dei a ela. Ela o usa em todos os lugares para exibi-lo; Eu não posso nem pará-la.",
  [818107786678784] = "Hehe, você me ouviu...",
  [818107786678528] = "Casar? Parabéns.",
  [818107786677760] = "Se você não estiver ocupado, poderia me ajudar a procurar o anel brilhante?",
  [818107786677504] = "O anel que meu noivo me deu caiu sem querer, e eu queria usar um anzol para recuperá-lo... Oh Deusa, se ele descobrir, com certeza ficará muito bravo!",
  [818107786677248] = "Ah, na verdade não estou pescando; Estou procurando por algo.",
  [818107786676992] = "A corrente aqui é muito forte. Você consegue pegar algum peixe?",
  [818107786676736] = "Mas ele não... ele nunca fez...",
  [818107786676480] = "Achei que ele estava apenas brincando até tarde! Ele vai voltar!",
  [818107786676224] = "Ele disse que a Árvore da Abundância poderia ressuscitar seu pássaro de estimação! ...Meu pobre filho.",
  [818107786675968] = "Pequeno Jack? Acho que não o conheço.",
  [818107786675712] = "Você! Você viu meu pequeno Jack?",
  [818107786675456] = "Tudo bem, tenho algumas pistas sobre pequenos tesouros, como aquele baú debaixo da ponte... mas não é de graça, entendeu?",
  [818107786675200] = "Ha, como você é jovem!",
  [818107786674944] = "Eu gostaria de tentar a caça ao tesouro também. Talvez você possa me dar alguns conselhos?",
  [818107786674688] = "Passei vinte anos neste deserto; qual o sentido de encontrar sucata?",
  [818107786674432] = "Todas essas coisas têm uma coisa em comum, você sabe o que é? Ninguém nunca os viu!",
  [818107786674176] = "“Coração da Imortalidade”, “Pedra Santa” e “Água da Vida Eterna” e vários outros nomes.",
  [818107786673920] = "Diz-se que o tesouro do Lago Dourado do Outono pertence à Quarta Época.",
  [818107786673664] = "Que tesouro?",
  [818107786673408] = "Você não parece um morador local. Você também foi enganado pelas lendas do tesouro?",
  [818107786673152] = "<P_Heart> (Corando profundamente) </> Ei, não fale tão alto!",
  [818107786672896] = "Um amor? Isso mesmo, é a era da juventude e do romance...",
  [818107786672640] = "Esperando pelo meu amor... uh, nada, por que você está se intrometendo na vida dos outros!",
  [818107786672384] = "Posso estar aqui para esperar por alguém também. Quem você está esperando?",
  [818107786672128] = "Estou esperando por alguém. Quanto a você, não parece ser desta casa. O que você está fazendo aqui?",
  [818107786671872] = "Você não está fazendo o mesmo?",
  [818107786670592] = "O patrão e a patroa nunca pretenderam culpar a jovem e aquele rapaz; eles só queriam que eu verificasse as coisas... Se você o vir, por favor ajude a transmitir esse sentimento. Obrigado.",
  [818107786670336] = "Finalmente consegui dar-lhes uma janela de tempo para se encontrarem, mas no momento em que o menino ouviu um som, ele desapareceu de repente. Até hoje ainda não sei como é aquele menino.",
  [818107786670080] = "Minha jovem amante recentemente gostou de um menino, mas essas duas crianças estão sempre se escondendo de todos nós.",
  [818107786669824] = "Posso ficar de olho em você. Você precisa que eu passe uma mensagem?",
  [818107786669568] = "Você viu um menino? Ele estava aqui conversando com minha jovem amante.",
  [818107786669312] = "Fomentar? Segundo? Parecem nomes de marcas de automóveis, haha.",
  [818107786669056] = "Você conhece os nomes Foster e Second? Sempre sinto que eles estão... com você.",
  [818107786668800] = "Sard, esse é o meu nome. Se quiser, fique à vontade para passar por aqui com frequência.",
  [818107786668544] = "Gostaria de saber o nome do dono deste lindo jardim.",
  [818107786668288] = "É uma honra absoluta! Todo jardineiro trabalhador do mundo teria seu cansaço eliminado ao ouvir isso.",
  [818107786667520] = "Irmãos? Minha mãe disse que eu era seu único filho.",
  [818107786667264] = "Não sei por que, mas você me parece familiar... você tem irmãos?",
  [818107786667008] = "Meu nome é Segundo. Tenha um dia maravilhoso!",
  [818107786666752] = "Qual é o nome do jardineiro?",
  [818107786666496] = "Heh, a chuva é irrigação gratuita e a luz do sol é uma recompensa extra. Considerando todas as coisas, sou eu quem está lucrando.",
  [818107786665728] = "Você teve insolação? Sou o único jardineiro da cidade.",
  [818107786665472] = "Perdoe-me por perguntar, mas já vi você em algum lugar antes?",
  [818107786665216] = "Meu nome é Foster, prazer em conhecê-lo.",
  [818107786664960] = "Não sei o nome do jardineiro.",
  [818107786664704] = "Eu não diria tudo, mas quase tudo. Afinal, toda flor é como uma criança, é preciso conhecer seus temperamentos.",
  [818107786664448] = "Olá, jardineiro trabalhador, você cuida de todas as flores da cidade?",
  [818107786664192] = "Olá, amigo estranho. É um ótimo dia para regar flores, não é?",
  [818107786663936] = "Claro, e ouça novamente seus suspiros – para lembrar aqueles dias de guerra.",
  [818107786663680] = "Eu entendo, Morian... Amanhã vamos até as estátuas ver essas pessoas corajosas.",
  [818107786663424] = "Porque Golden Autumn Lake usará sua terra fértil para lembrá-los para sempre.",
  [818107786663168] = "Não suspire, Carles, você sabe que eles ficaram felizes quando se transformaram em estátuas de pedra.",
  [818107786662912] = "Nossos camaradas... suspiro, eles serão heróis para sempre.",
  [818107786662400] = "Sim, foi graças ao sacrifício da Igreja que os seus efeitos negativos puderam ser controlados.",
  [804913646963200] = "O que você quer dizer?",
  [818107786662144] = "Olha, depois de todos esses anos, a Árvore de Yodra ainda protege este lugar.",
  [818107786661888] = "Vamos! Centenas de anos se passaram, seria a nossa vez de acontecer alguma coisa? Se você não for, não me impeça de jogar cartas.",
  [818107786661632] = "Um edifício não gerenciado ainda é muito perigoso.",
  [818107786661120] = "Na verdade, ninguém conhece este castelo melhor do que alguém como você.",
  [818107786660864] = "Faz muito tempo que ninguém consegue, é uma ruína, {Sr. {EM. |}}! Sem magistrados, sem polícia. Somente um guia como eu pode garantir sua segurança – cresci aqui e já passei por lá dentro e fora mais vezes do que posso contar.",
  [818107786660608] = "Alguém pode simplesmente entrar e sair do castelo quando quiser?",
  [818107786660096] = "O castelo está abandonado há centenas de anos. Se realmente existissem antiguidades, seria a vez dele encontrá-las?",
  [818107786659840] = "Sobre o que aquele antiquário conversou com você? Foi aquele velho discurso de “venha ver as verdadeiras antiguidades”?",
  [818107786659584] = "Isso... da próxima vez, da próxima com certeza! Tenho coisas para fazer e devo sair primeiro!",
  [818107786659328] = "Já que tivemos uma boa conversa, você está disposto a vir comigo dar uma olhada? Você é alguém que conhece qualidade, posso dizer de relance!",
  [818107786658560] = "<P_Heart> (Voz baixa) </> Mas as pessoas inteligentes sabem... quem se atreveria a expor verdadeiros tesouros a céu aberto?",
  [818107786658304] = "Veja o artesanato desses produtos, de sabor verdadeiramente vintage e verdadeiramente aristocrático!",
  [818107786658048] = "A melhor lembrança do Castelo Lamud! {Senhor. {EM. |}}, esta é a escolha perfeita para escolher presentes para sua família e amigos!",
  [818107786657792] = "O que você vende aqui?",
  [818107786657536] = "Estou ajudando meu pai a cuidar da banca de jornal hoje. Aqui está o jornal diário que você queria, vá embora se não houver mais nada!",
  [818107786657280] = "Ei, não despreze as pessoas, só porque sou um pouco baixo?",
  [818107786657024] = "É uma criança... então estava bloqueado pela janela.",
  [818107786656768] = "Veja quem eu sou de novo!",
  [818107786656512] = "Isso, o que está acontecendo?",
  [818107786656256] = "O que? A banca de jornal falava por si!",
  [818107786656000] = "Eu posso ouvir você!",
  [818107786655744] = "Perguntar o quê? Você quer que eu grite em uma banca de jornal vazia como um idiota?",
  [818107786655488] = "Não desperdice seu esforço, {Sr. {EM. |}}, estou esperando aqui há uma hora e não vi um único vendedor de jornal!",
  [862028122401537] = "Ninguém está cuidando de tanto pão?",
  [818107786654720] = "Por favor, dê-me o jornal diário de hoje.",
  [818107786654464] = "Você escolhe perder 50% da sua Saúde para obter um Pergaminho Dourado?",
  [818107786653696] = "Bem-vindo de volta ao Clube!",
  [818107786653440] = "Novidades na loja de pares têm grandes descontos, compre-as antes de olhar!",
  [818107786653184] = "Mão de obra, recursos materiais, custos trabalhistas, despesas de viagem, perda de salários... hmm, tenho que calcular novamente...",
  [818107786652928] = "Acho que você ficará muito interessado nesta proposta. No entanto, isso requer algum tempo de preparação. Quando o castelo atingir o <Highlight> Nível 2 </> e tudo estiver pronto, você pode vir até mim a qualquer momento.",
  [818107786652672] = "Quando contactei hoje a Câmara de Comércio, eles indicaram que se as reservas de produtos do nosso castelo forem adequadas, podemos emprestar os carris da Câmara para o comércio relacionado.",
  [818107786652416] = "Respeitado {Sr. {EM. |}}, andei pelos arredores hoje e nunca me senti tão revigorado! Tudo aqui parece cada vez melhor.",
  [818107786652160] = "Além da adega artesanal, você também pode tentar construir diversos tipos de oficinas para atender às necessidades dos diferentes pedidos.",
  [818107786651904] = "Posso entrar em contato com a Câmara de Comércio local para você, para que mais produtos produzidos no castelo posteriormente tenham canais de vendas adequados.",
  [818107786651648] = "Respeitado {Sr. {EM. |}}, desde que você chegou aqui, tenho visto este castelo ganhar vida gradualmente; é realmente gratificante. Olha essa cerveja de centeio, que cheiro perfumado!",
  [818107786651392] = "A seguir, você pode produzir vários tipos de álcool aqui. A cerveja de centeio é uma bebida comum na mesa do povo de Tingen; podemos muito bem começar tentando isso.",
  [818107786650112] = "Nosso território é rico em uva e cevada, excelentes matérias-primas para a fabricação de cerveja. Por que não começar com o que fazemos de melhor: construir uma vinícola, o que você acha?",
  [818107786649856] = "Senhor! O projeto do workshop pode ser colocado na agenda!",
  [818107786649600] = "<P_Heart> Faça um desejo </> Eu desejo... que um castelo apareça aqui...",
  [818107786649344] = "Parece que descobri que ganhei algumas habilidades... Poderia ser, assim como aquela cidade que surgiu do chão... Deixe-me tentar fazer um desejo.",
  [818107786649088] = "Será que isso acabou de ser um pedaço da história do Sr. Louco?",
  [818107786648832] = "<P_Heart> Uma pequena cidade que surgiu do nada... edifícios que foram construídos rapidamente... e o nome desta cidade, \"Utopia\"... </>",
  [818107786648576] = "<P_Heart> Parece ter visto um pedaço de... história desconhecida... </>",
  [818107786648320] = "Hum?!",
  [818107786648064] = "<P_Heart> Cantando inconscientemente </> O Louco que não pertence a esta era, o misterioso governante acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce boa sorte...",
  [818107786647808] = "Seria ótimo se os edifícios pudessem ser gerados automaticamente...",
  [818107786647552] = "Ahem, eu vou dar uma olhada mais de perto primeiro!",
  [818107786647296] = "<P_Heart> (Então é por isso que não precisei pagar um preço alto para comprá-lo...) </>",
  [818107786647040] = "Acredito que você definitivamente conseguirá trazer esta terra de volta à vida; Já estou preparado para me surpreender com isso!",
  [818107786646784] = "Como podem ver, embora este terreno esteja cheio de potencial, tem estado em estado de abandono devido à falta de gestão de longa data.",
  [818107786646528] = "<P_Heart> (Inclina-se ligeiramente) </> Senhor, por favor, siga-me, vou apresentá-lo a este território.",
  [818107786646272] = "Eu... possuo propriedade de um castelo? <P_Heart> (Foi isso que a senhorita \"Justiça\" disse, \"encontre um lugar para ficar\"?) </> Mas...",
  [818107786646016] = "Você deve ser {{PlayerName}}. Recebi uma mensagem para esperar por você aqui e preparei um contrato para você com antecedência.",
  [818107786645760] = "Este local foi planejado como um pequeno castelo, mas infelizmente, depois de muitos arrependimentos, nunca foi concluído.",
  [818107786645504] = "Castelo? Mas aqui...",
  [818107786645248] = "Por favor, perdoe minha grosseria – pensei que ninguém voltaria a este castelo.",
  [818107786643456] = "Você deveria sair daqui rapidamente também. Estou ansioso para nos encontrarmos novamente.",
  [818107786643200] = "Ainda tenho que devolvê-lo à Sra. Fors.",
  [818107786642944] = "A propósito, pegarei o “Beacon Espaço-Tempo” de volta.",
  [818107786642688] = "Você se saiu muito bem. Por favor, certifique-se de aceitar este sinal de gratidão.",
  [862028122401538] = "Essa textura... parece madeira? E este aqui é... esponja?",
  [818107786642176] = "Muito bem feito! A corrupção central foi eliminada e este espaço está estável.",
  [818107786641920] = "Muito bem, agora fortaleça suas habilidades.",
  [818107786641152] = "Tudo bem, a principal prioridade é purificar a corrupção. Por favor, pegue isso.",
  [818107786640896] = "Sim, a Sra. Fors previu que a corrupção aqui corre o risco de se espalhar e me confiou para monitorá-la aqui.",
  [818107786640640] = "Experimente primeiro sua habilidade e não comece antes de dominar totalmente como usá-la.",
  [818107786640384] = "Ele pode usar o poder de um Aprendiz para criar um espaço oculto e ajudá-lo a alternar entre esse espaço e a realidade para encontrar um caminho.",
  [818107786640128] = "Este relógio de bolso, você também pode chamá-lo de “Farol do Espaço-Tempo”.",
  [818107786639872] = "Então a Sra. Fors me confiou para lhe dar isto.",
  [818107786639616] = "Mas... a corrupção distorceu a realidade e os métodos normais não podem entrar.",
  [818107786639360] = "O núcleo de corrupção que precisa de purificação está no altar do porão.",
  [818107786639104] = "Ela me pediu para esperar aqui e lhe dar algumas orientações necessárias.",
  [818107786638848] = "Você pode me chamar de Velho Victor. Eu pertenço ao Aprendiz Caminho , assim como a Sra.",
  [818107786638592] = "Ah, você finalmente chegou.",
  [818107786638336] = "Saia do nível oculto.",
  [818107786638080] = "Vá para o nível oculto e inicie uma batalha difícil.",
  [818107786637824] = "Mate todos os monstros autodestrutivos em 30 segundos, caso contrário você sofrerá dano de autodestruição. Receba uma recompensa após a conclusão.",
  [818107786637568] = "Tudo bem. Se eu tivesse guardado essas anotações corretamente, sinto muita falta dela.",
  [818107786637312] = "Se ao menos eu tivesse guardado bem as outras notas; Eu sinto falta dela.",
  [818107786637056] = "A maioria das anotações dela desapareceu quando ela desapareceu, mas ainda tenho uma página sobrando, quer ver?",
  [818107786636800] = "Afinal, o mundo não é assim? Ela estava agindo de forma misteriosa e escreveu muitas notas.",
  [818107786636544] = "As abóboras são sempre do mesmo tamanho, a água do rio não tem temperatura, o cocheiro nunca descansa.",
  [818107786636288] = "Ela era a garota mais inteligente da cidade, sempre adorou dizer coisas estranhas.",
  [818107786636032] = "Seu amigo desapareceu?",
  [818107786635776] = "Cada vez menos pessoas estão comprando livros. Se Consuna não tivesse desaparecido, ela definitivamente saberia o que fazer.",
  [818107786635520] = "Já faz muito tempo que eu... Aurora... ela se esqueceu de mim?",
  [818107786635264] = "A gente era muito próximo... ela vinha falar comigo todos os dias, assim mesmo...",
  [818107786635008] = "Quem é essa Aurora de quem você está falando?",
  [818107786634752] = "Aonde você foi, minha querida Aurora... com certeza vou te encontrar...",
  [818107786634496] = "Não, eu realmente não sei, adeus.",
  [818107786634240] = "<P_Heart> (Droga, eles estão realmente usando esse truque?) </>",
  [818107786633984] = "Waaah, por favor, diga-nos, waaah...",
  [818107786633728] = "Não, você definitivamente quer, eu vi você passando por lá! Edith, rápido!",
  [818107786633472] = "Ei, pequenino... Não sei de qual senha você está falando.",
  [818107786633216] = "Você sabe a senha daquela taverna? Aquele ali, aquele com a velha guardando a porta—",
  [818107786632960] = "Vamos ouvir?",
  [818107786632704] = "De nada! Só queríamos te pedir um pequeno favor, tudo bem?",
  [818107786632448] = "Obrigado! Isso é muito atencioso.",
  [818107786632192] = "{Respeitado Sr. {Linda Sra. |}}, esta flor é para você!",
  [818107786631936] = "Ah, certo, não conte para as crianças! Isso só circula entre adultos!",
  [818107786631168] = "A senha dessa loja é \"Bêbado\"!",
  [818107786630912] = "Que a Deusa proteja você! <P_Heart> (Sussurrando) </> Como recompensa, vou lhe contar um segredo secretamente...",
  [818107786630656] = "Olá, gostaria de pagar uma bebida a este cavalheiro.",
  [818107786630400] = "{Senhor. {EM. |}}, me pague uma bebida, só uma!",
  [818107786630144] = "Você, como você poderia saber? Esta tem sido minha melhor piada nos últimos dez anos... Será que você é o Rei das Piadas?",
  [818107786629888] = "Hahahaha não, talvez um dia quando você chegar na minha idade você entenda essa piada!",
  [818107786629632] = "Um bife mal passado e um bife médio se encontraram, por que não disseram olá?",
  [818107786628864] = "Por que ele está tão irritado?",
  [818107786628608] = "Jovem, você não deveria ser como aquele velho na ponte.",
  [818107786628352] = "A pequena cidade é tão bonita, mas ele está tão irritado; isso não é bom, não é bom.",
  [818107786627584] = "Você sabe por que um bife mal passado e um bife médio não dizem olá quando se encontram?",
  [818107786627328] = "Jovem, você não é ruim. Deixe-me contar uma informação importante.",
  [818107786627072] = "Você tem ideia de como foi difícil para mim subir até aqui para ver a cachoeira!",
  [818107786626816] = "O destino me oprimiu por ser velho e fraco, tirou minhas pernas e quis tirar minha dignidade também!",
  [818107786626560] = "Canalhas emplumados! Ratos alados! Juro em nome da Deusa, expulsarei toda a sua família!",
  [818107786626304] = "Seu bando de pássaros, como ousam bicar minha cabeça!",
  [818107786626048] = "Você não sabe e tem coragem de vir aqui? Volte e faça sua lição de casa!",
  [818107786625792] = "Eu... eu não sei.",
  [818107786625536] = "Não é uma resposta ruim. Você adivinhou? Tanto faz, eu não me importo. Entre.",
  [818107786625280] = "Bêbado.",
  [818107786625024] = "Oh, mostre algum respeito pela cabrinha! Ou vou bater no seu traseiro com minha bengala!",
  [818107786624768] = "Perna de cordeiro assada deliciosa?",
  [1139094851802368] = "O que?",
  [818107786624256] = "Chama-se Bola de Neve.",
  [818107786624000] = "Ahem, um convidado? Deixe-me perguntar... como se chama a cabra do Velho Buck?",
  [818107786623744] = "Phil, seu malandro!!!",
  [818107786623232] = "…Isso, isso poderia ter sido comido por alguém…",
  [818107786622976] = "Por que a abóbora de hoje é tão leve... como se fosse oca?",
  [818107786622720] = "Você escolheu o caminho certo; Acabei de escolher isso no meu campo esta manhã! Deixa eu cortar e embalar para você!",
  [818107786622464] = "Estou de olho nesta abóbora! É grande e amarelo, deve ser uma delícia!",
  [818107786622208] = "Ei, aquele não é o Terry? O que você está planejando comprar hoje?",
  [818107786621952] = "Todos esses vegetais são cultivados em casa. Basta seguir direto pelo caminho atrás de mim e essa será minha horta!",
  [818107786621696] = "Este repolho é apertado como a bolsa de um avarento; ninguém está tirando uma única folha dele!",
  [818107786621440] = "Abóboras douradas e rechonchudas, doces o suficiente para fazer seus dentes caírem!",
  [818107786621184] = "Rabanetes! Salsão! Pastinaga! Compre mais, ganhe mais grátis!",
  [818107786620928] = "O que está feito está feito, vamos comer algumas uvas primeiro.",
  [818107786620672] = "…Morto com certeza.",
  [818107786620416] = "Mas o Tio já pegou aquela abóbora e levou para vender na banca de verduras!",
  [818107786620160] = "Era uma abóbora tão grande que eu estava com fome, então cavei um buraco no fundo e tirei a polpa macia...",
  [818107786619904] = "Falando nisso, por que diabos você roubou e comeu a abóbora no campo!",
  [818107786619648] = "Realmente? Não é um deus que você inventou? Será que o Deus dos Coelhos consegue realmente roubar comida?!",
  [818107786619392] = "Está tudo bem, já orei ao Deus dos Coelhos para perdoar meus pecados!",
  [818107786619136] = "Se essa bruxa for real, vou enfiar um peixe que está apodrecendo há três dias nas narinas dela!",
  [818107786618880] = "É tudo por causa da lenda da Bruxa do Pântano; agora todo mundo diz que meus peixes estão contaminados!",
  [818107786618624] = "O negócio de venda de peixe não vai bem?",
  [818107786618368] = "Quase não há mais ninguém nesta pequena cidade comendo peixe! É tudo culpa daquela maldita Bruxa do Pântano!",
  [818107786618112] = "O que eu faço, o que eu faço? Se o tio descobrir, você está acabado!",
  [818107786617856] = "<P_Heart> (Nunca ouvi falar desse deus... e sempre sinto que algo está errado com esse altar...) </>",
  [818107786617600] = "A nota detalhava o que é necessário para orar ao meu Senhor; esta deve ser a revelação que o Senhor me deu!",
  [818107786617344] = "No meu momento mais doloroso, encontrei um bilhete do Deus da Armadura!",
  [818107786617088] = "Fui visitá-lo deitado na cama... mas quando ele acordou esqueceu quem eu era... Essa deve ser a maldição do Deus da Armadura...",
  [818107786616832] = "Quando fui pedir uma explicação, ele foi atropelado por uma carruagem bem na minha frente!",
  [818107786616576] = "…Existe alguma conexão necessária entre os dois?",
  [818107786616320] = "Há alguns dias, quando fui caçar tesouros em um antigo castelo com um amigo, me encarei com uma armadura! Quando voltei, descobri que meu amante era meu irmão biológico há muito perdido!",
  [818107786616064] = "Deus da Armadura?",
  [818107786615808] = "Por favor, tenha cuidado, não pise no altar que montei para o Deus da Armadura.",
  [818107786615552] = "Haha, os três estão dançando, é tão animado, quero dançar também!",
  [818107786615296] = "Então por que você está dançando perto do altar?",
  [818107786615040] = "Hehe, não sei, que deus?",
  [818107786614784] = "Para qual deus você está orando?",
  [818107786614528] = "Pronto, deixe-me dar um tapinha na sua cabeça. Não é sua culpa; o Deus da Armadura irá perdoá-lo.",
  [818107786614272] = "…Eu entendi mal.",
  [818107786614016] = "Esses são todos os meus títulos, ok? OK.",
  [818107786613760] = "…Você está orando por oito pessoas?",
  [818107786613504] = "Eu, um crente da Noite, um crente da Tempestade, um crente da Terra, um Bardo, um pintor da cidade, um gerente de hotel, Golden Right Cheek... estou orando aqui.",
  [818107786613248] = "<P_Heart> (Quem está falando? Parece vir de cima...) </>",
  [818107786612992] = "Ei! O que você está fazendo com meu melão?",
  [818107786612736] = "Som nítido, hmm... se soa bem, é um bom melão!",
  [818107786612224] = "Eles até inventaram uma história de que se você tocar na água do riacho, será amaldiçoado pela bruxa que vive no pântano da nascente! Ha!",
  [818107786611968] = "Um cara ganancioso e seboso que sempre quer assumir todo o negócio de venda de peixes da cidade.",
  [818107786611712] = "Quem é Fesher?",
  [818107786611456] = "Uma bruxa mora na nascente do riacho? Parece muito assustador.",
  [818107786611200] = "Se você me perguntar, isso é pura invenção, apenas Fesher querendo monopolizar o negócio da peixaria!",
  [818107786610944] = "Se você a ofender, ela entrará furtivamente em sua casa no meio da noite e colocará coisas terríveis em seu cérebro.",
  [818107786610688] = "Uma lenda na pequena cidade: uma bruxa vive no pântano na nascente deste riacho.",
  [818107786610432] = "O que é essa Bruxa do Pântano de que você fala?",
  [818107786610176] = "Alguém realmente acredita nas bobagens sobre uma Bruxa do Pântano? Aquele cara, Fesher, só gosta de inventar histórias.",
  [818107786609408] = "Você não conhece a lenda da Bruxa do Pântano? Qualquer um que tocar neste lago terá pesadelos por dias!",
  [818107786609152] = "Não se atreva!",
  [818107786608896] = "Eu vou ajudá-lo a pegá-lo.",
  [818107786608640] = "Pesadelos... Obrigado, terei cuidado.",
  [818107786608384] = "Irei ver o ursinho de pelúcia com frequência, você deve ficar longe da água!",
  [818107786608128] = "Esta piscina foi amaldiçoada por uma Bruxa do Pântano; quem tocar na água terá pesadelos por dias!",
  [818107786607872] = "Entrar na água? Você deve ser de fora da cidade!",
  [818107786607616] = "A água é muito rasa, por que não descer e pegá-la?",
  [818107786607360] = "O ursinho de pelúcia que minha irmã me deu caiu no lago e não consigo recuperá-lo...",
  [818107786607104] = "Você definitivamente vai gostar deles!",
  [818107786606848] = "Ei! {Senhor. {EM. |}}, tenho, tenho outros poemas!",
  [818107786606592] = "O que você acha?",
  [818107786606336] = "Se alguém provou o vinho de seus lábios, quem ainda estaria disposto a voltar sóbrio!",
  [818107786606080] = "Viajante perdido, lembre-se rapidamente da rosa em seus olhos—",
  [818107786605824] = "Esse corcel sob a lua galopa como um trovão pela noite eterna!",
  [818107786605568] = "Esse mar agitado é a taça de vinho cheia pelos deuses!",
  [818107786605056] = "<P_Heart> (Vamos ouvir; seria muito indelicado virar e sair agora...) </>",
  [818107786604800] = "Ouso dizer que isso vai te chocar!",
  [818107786604544] = "Oh, amigo, você gostaria de ouvir o poema que acabei de escrever?",
  [818107786604288] = "Haha, sério?",
  [818107786604032] = "Sua chegada torna a paisagem ao redor pálida em comparação!",
  [818107786603776] = "Oh, esse radiante {Sr. {EM. |}}, que honra conhecer você aqui!",
  [818107786603520] = "Tudo bem, então não vou mais incomodar você.",
  [818107786603264] = "<P_Heart> (Vai dar uma olhada?) </>",
  [818107786603008] = "Não, ele está escrevendo poemas à beira do lago, poemas muito, muito bons!",
  [818107786602752] = "Ele está aqui também? Ele está praticando como você?",
  [818107786602496] = "Meu irmão, irmão.",
  [818107786602240] = "Então quem lhe disse para praticar isso?",
  [818107786601984] = "Eu, eu quero poder falar, falar suavemente primeiro.",
  [818107786601728] = "Então você não deveria praticar perguntas de entrevista?",
  [818107786601472] = "<P_Heart> (Por que comecei a gaguejar também?) </>",
  [818107786601216] = "Então você...",
  [818107786600960] = "<P_Heart> (Eles disseram isso tão diretamente? As pessoas de Loen não deveriam ser muito reservadas?) </>",
  [818107786600704] = "Não, porque eu tenho um pouco de gagueira.",
  [818107786600448] = "Você está aqui para praticar porque está muito nervoso?",
  [818107786600192] = "Eu, eu sou prático, estou praticando, vou, vou a uma entrevista.",
  [818107786599936] = "…Hmm, hein?!",
  [818107786599680] = "Mas ele é um homem.",
  [818107786599424] = "…Se for amor verdadeiro, pode não ser impossível.",
  [818107786599168] = "Mas esta pessoa tem setenta anos.",
  [818107786598912] = "Você ama a alma dele; não se preocupe com esses detalhes.",
  [818107786598656] = "Mas ele está incapacitado, sentado na cabeça de ponte todos os dias amaldiçoando os pássaros no céu.",
  [818107786598400] = "Isso não é realmente uma coisa culpada, é?",
  [818107786598144] = "Tenho vinte anos e me apaixonei por uma pessoa mal-humorada. Eu sou culpado.",
  [818107786597888] = "A propósito, você poderia perguntar a ele se ele quer uma garrafa do vinho deste ano? Lembro que ele adora beber.",
  [818107786597632] = "Ele está sempre obcecado em cultivar as abóboras mais doces. Haha, mas as abóboras dele são realmente muito deliciosas!",
  [818107786597376] = "Ah... você quer dizer o Sr. Lumber da plantação de abóboras ao lado.",
  [818107786597120] = "Oh! Se gostar, fique à vontade para beber um pouco quando estiver pronto.",
  [818107786596864] = "Pretendo transformar essas uvas em vinho. Só preciso colocá-los em um barril e esperar que fermentem... Esse deve ser o melhor vinho da pequena cidade!",
  [818107786596608] = "Obrigado pelo elogio, {Sr. {EM. |}}!",
  [818107786596352] = "Estas uvas parecem ótimas!",
  [818107786596096] = "O tempo está tão bom hoje, querido {Sr. {EM. |}}, venha comer algumas uvas; estas podem ser as melhores uvas do Golden Autumn Lake!",
  [818107786595840] = "Se ao menos eu pudesse provar seu vinho. Ah, não, quero dizer, minhas abóboras são muito melhores que o vinho dele. Se ele quiser, certamente posso trocar generosamente com ele!",
  [818107786595584] = "O quê? Ele vai fazer vinho com essas uvas. Uh, bem, isso parece muito bom... Eu gosto de beber!",
  [818107786595328] = "Você quer dizer Sr. Yate? Ele parece ocupado fermentando uvas e transformando-as em vinho.",
  [818107786595072] = "Hmph, você é sensato. Minhas abóboras são definitivamente as maiores e mais doces!",
  [818107786594816] = "Ah... essas abóboras parecem deliciosas.",
  [818107786594560] = "Claro, é uma festa na pequena cidade para celebrar a colheita e agradecer à Terra. Olhe para as abóboras douradas em toda a minha porta; que frutos doces, que grande poder de colheita!",
  [818107786592000] = "Restaure a saúde completa",
  [818107786591232] = "Ataque aumentado em 10%",
  [818107786590464] = "Ataque aumentado em 35%",
  [818107786589696] = "Ataque aumentado em 80%",
  [818107786588928] = "Ataque aumentado em um valor fixo de 2.500",
  [818107786588160] = "Ataque aumentado em um valor fixo de 8.000",
  [818107786587904] = "Saúde aumentada",
  [818107786587648] = "Velocidade de movimento aumentada",
  [818107786587392] = "Ataque aumentado em um valor fixo de 20.000",
  [818107786587136] = "Cada ataque aumenta o Ataque em 5%",
  [818107786586880] = "<P_Heart> Congelar </> Marca aciona Nebulosa Aria Recarga redução de 6 segundos",
  [818107786586624] = "Nebula Aria adiciona <P_Red> Sangramento </>",
  [818107786586368] = "Ataque -300%, habilidades adicionam uma camada de <P_Yellow> Queimar </> (Queimar causa dano com base na Saúde máxima do Aprendiz)",
  [818107786586112] = "Ataque +80%, Nebulosa Aria adiciona <P_Heart> Congelamento </> Marca",
  [818107786585600] = "Tecnologia perdida, balbucio de conhecimento e criações precisas; razão e loucura se entrelaçam aqui. Passe por esta porta e enfrente a poderosa existência naquele Steam Palace.",
  [818107786585344] = "Bem-vindo, respeitado {Sr. {EM. |}}. Estamos prontos para carregar a mercadoria e partir a qualquer momento, ou gostaria de fazer a manutenção do carro e do motor?",
  [818107786585088] = "Você pode me enviar fragmentos da presa e eu lhe darei uma recompensa generosa.",
  [818107786584832] = "Já capturamos o suspeito, seu colega Bank. Agora você pode ir diretamente interrogá-lo.",
  [818107786584576] = "Vamos começar com o primeiro pequeno teste. O estivador Brady desapareceu. Esta é a evidência deixada no local; lembre-se de verificar com cuidado.",
  [818107786584320] = "Comece seu \"desempenho\". Que a Deusa proteja sua dedução.",
  [818107786584064] = "Lembre-se, neste procedimento, suas armas não são apenas revólveres e amuletos, mas também observação aguçada, lógica rigorosa e coragem destemida.",
  [818107786583808] = "Isto não é apenas uma acusação contra um criminoso, mas um “julgamento” a nível espiritual, que pode efetivamente dissuadir as forças ocultas por trás deles e forçar a verdade a manifestar-se.",
  [818107786583552] = "\"Testemunho.\" Ao construir uma cadeia lógica completa, você deve usar vontade firme e espiritualidade para \"apresentar\" sua dedução.",
  [1139165181903104] = "Vou manter isso em mente.",
  [818107786583040] = "Esta “evidência” pode ser um documento, um Artefato Selado, ou... um testemunho de um papagaio. A chave é deixar que as mentiras desmoronem sob o peso da lógica.",
  [1139165182673152] = "O que você está desenhando?",
  [818107786582528] = "Em segundo lugar, \"Interrogatório\".",
  [818107786582272] = "No reino da Deusa, os detalhes são luzes que podem dissipar a névoa.",
  [818107786582016] = "Use seus olhos, sua intuição espiritual e até mesmo qualquer... hum... \"evidência verbal\" para capturar todos os detalhes ilógicos.",
  [818107786581760] = "Primeiro, \"Reunião\".",
  [818107786581504] = "Seu núcleo consiste em apenas três etapas:",
  [818107786581248] = "A verdade por trás das existências que enfrentamos está muitas vezes escondida sob camadas de mentiras e desorientação espiritual. Portanto, em certos... casos “especiais”, a Catedral reconhece um procedimento de recolha de provas mais “dramático”.",
  [818107786580992] = "Ouça, criança.",
  [818107786580736] = "…O que exatamente aconteceu no cais naquela noite?",
  [818107786580480] = "Oh? Você não tem medo?",
  [818107786580224] = "Quero saber sobre o cais.",
  [818107786579968] = "<P_Heart> (Você está se preparando para abrir este baú de tesouro, mas sente olhos de algum lugar desconhecido olhando para você.) </>",
  [818107786579712] = "Merda, as falas que memorizei a noite toda nem foram usadas!",
  [818107786579456] = "Eu não posso ser culpado por isso. Sempre preparei o papel de Gehrman Sparrow, mas só na noite anterior à reunião de recrutamento é que a Sênior Divina me informou que o tecido que havia preparado era suficiente apenas para fazer roupas para um coelho.",
  [818107786579200] = "Por favor, espere um momento, preciso de um pouco de tempo para lembrar qual é a recompensa atual de \"The Flame\"...",
  [818107786578944] = "Como você pode ver, agora sou um pirata... O grande pirata da obra da Sra. Fors, \"O Grande Aventureiro\" - \"O Louco\", recompensa...",
  [818107786578688] = "Ahem... esta é uma forma de endereço usada para manter o personagem.",
  [818107786578432] = "Bem vindo ao Clube do Tarô ! Novo marinheiro.",
  [818107786578176] = "Aguardo suas sugestões de melhoria, jovem. Esta é também uma contribuição para o futuro da humanidade!",
  [818107786577920] = "Como uma ópera que nunca chegará ao fim, é maravilhosa, certo? Tenho que agradecer aos alunos pela inspiração.",
  [818107786577664] = "O que é ainda melhor é que mesmo que seja jogado no esgoto, ele continuará cantando junto com a água, trazendo uma experiência de canto definitiva para todos que o consomem.",
  [818107786577152] = "Não, não, senhora, “Cantar” refere-se ao facto de este cogumelo cantar alto desde o momento em que sai da panela, e mesmo que seja mastigado pelos molares ou engolido no estômago, não vai parar de forma alguma!",
  [818107786576896] = "Cantoria? Hmm... o efeito deste aqui é transformar as pessoas em cantores depois de comê-lo?",
  [818107786576640] = "Dona Justiça, gostaria de experimentar os Cogumelos Cantantes que cultivamos?",
  [818107786576384] = "Oh, cinco mares! Sua névoa retornará!",
  [818107786576128] = "Heh, quando chegar a hora, vamos sair para o mar para caçar juntos. Eu permito que você me sirva como \"O Louco\".",
  [818107786575872] = "Talvez um dia você seja a pessoa mais parecida com ele além de mim.",
  [818107786575616] = "Oh? Parece que além da calma diante de uma arma, você também tem uma certa loucura... Muito bom, isso é muito Gehrman Sparrow.",
  [818107786575360] = "Seus olhos calmos diante do cano de uma arma têm o temperamento de Gehrman Sparrow.",
  [818107786575104] = "<P_Heart> (Golpes frios no cano da arma) </> Eu admiro você, recém-chegado.",
  [818107786574848] = "Garanto-lhe o preço mais justo de toda Tingen.",
  [818107786574592] = "Numerologia? Espelho mágico? Cartas de tarô ou astrologia adivinhação ?",
  [818107786574336] = "Você também quer dançar? Você pode se inscrever no quadro de avisos ali!",
  [818107786574080] = "Ótimo! Com esse tipo de motivação, teremos sucesso em tudo o que fizermos!",
  [818107786573824] = "Uau! Uau!",
  [818107786573568] = "Escutem, pessoal, com certeza ganharemos o suficiente para as refeições desta semana hoje. Levante a mão se você concorda!",
  [818107786573056] = "As informações sobre este Artefato Selado não estão disponíveis no momento.",
  [818107786572800] = "<P_Heart> (O passarinho bate as asas, soltando gritos de ansiedade.) </>",
  [818107786572288] = "(É muito perigoso para Enid correr sozinha; preciso pelo menos encontrá-la.)",
  [818107786572032] = "(Uma floresta estranha, outra voz na minha cabeça, cenas sinistras vermelho-sangue...)",
  [818107786571520] = "<P_Heart> (Estou preso aqui? Como posso sair?) </>",
  [818107786571264] = "<P_Heart> (Floresta estranha, uma garota que desapareceu de repente, outra voz na minha cabeça... tudo é muito estranho...) </>",
  [818107786571008] = "Um... acampamento?",
  [818107786570752] = "Amanhã... haverá uma carta amanhã.",
  [818107786570496] = "Ele deve ter se atrasado por alguma coisa.",
  [818107786570240] = "Desculpe, hoje não.",
  [818107786569984] = "Há alguma carta do Sr. Hanks?",
  [818107786569728] = "Isto é para que o Senhor da Floresta se lembre da parte que fizemos e para nos abençoar com uma colheita constante.",
  [818107786569472] = "Depois de terminar de cortar a madeira, desenhamos símbolos de olhos nos troncos com resina quando o sol se põe.",
  [818107786569216] = "Há meio mês, um suspiro veio do lago e a pobre mulher perdeu o filho.",
  [818107786568960] = "O que aconteceu com ela?",
  [818107786568704] = "A natureza fala, mas a maioria das pessoas esqueceu como ouvir.",
  [818107786568448] = "Você pode prever o tempo?",
  [818107786568192] = "Entre, jovem, vai chover.",
  [818107786567936] = "…Às vezes as pessoas deveriam ser mais conservadoras e não ficar muito curiosas sobre todas as coisas novas.",
  [818107786567680] = "Como é? É do seu gosto?",
  [818107786567424] = "<P_Heart> (Você reúne coragem para provar um pedaço) </>",
  [818107786567168] = "Realmente?! Você é um verdadeiro guerreiro.",
  [818107786566912] = "Parece único; Eu gostaria de experimentar.",
  [818107786566656] = "Isso é realmente uma pena!",
  [818107786566400] = "…É muito único, ainda prefiro o sabor normal.",
  [818107786566144] = "Gostaria de comprar alguns para experimentar? Apenas 1 soli, compre um e ganhe dez grátis! Não, compre um e ganhe vinte grátis!",
  [818107786565888] = "Exatamente. Parecem melões, mas têm gosto de mistura de truta e leite.",
  [818107786565632] = "Você está se referindo ao sabor dessas abóboras?",
  [818107786565376] = "Sabor estranho...",
  [818107786565120] = "Feito por uma fera? De qualquer forma, pegue este rifle de caça. Muitas coisas estranhas aconteceram ultimamente.",
  [818107786564864] = "As pegadas ensanguentadas no chão não parecem pertencer a um humano.",
  [818107786564608] = "Chapeuzinho Vermelho, há alguma outra pista?",
  [818107786564352] = "Eu realmente espero ter a chance de conhecer um \"figurão\". Talvez eu devesse esperar um pouco mais na estação.",
  [818107786564096] = "Talvez.",
  [818107786563328] = "Nos encontramos novamente, senhorita Delota.",
  [818107786563072] = "Louvado seja a Deusa. Desta vez vou trilhar o caminho certo.",
  [818107786562816] = "Minha bússola e minha cabeça parecem dançar flamenco, girando sem parar.",
  [818107786562560] = "Oh, estou tão feliz em ver uma pessoa viva aqui. Você sabe em que direção fica a estação Golden Autumn Lake?",
  [818107786562304] = "Há algo em que eu possa ajudá-lo?",
  [818107786562048] = "Eu claramente esculpi flechas nas árvores... Mas por que ainda estou preso no labirinto da floresta...",
  [818107786561792] = "Esses aldeões parecem estar falando sobre ocorrências estranhas recentes...",
  [818107786561536] = "Não estou interessado nesta profecia. Adeus, amigo.",
  [818107786561280] = "Se você encontrar alguma pista relevante, por favor, me diga. Claro, pagarei uma recompensa generosa.",
  [818107786561024] = "O objetivo da minha jornada é resolver esse mistério.",
  [818107786560768] = "O que esta profecia significa?",
  [818107786560512] = "Uma profecia misteriosa também circulou na vila do Lago Golden Autumn—\" <P_Yellow> Quando o suspiro do Santo soar, a muda dourada despertará aqui, e todas as coisas receberão a desolação. </> \"",
  [818107786560256] = "Há rumores de que o Lago Golden Autumn recebeu o presente da Terra, por isso está em época de colheita o ano todo. No entanto-",
  [818107786560000] = "Qual é a “misteriosa profecia do Lago Golden Autumn” que você acabou de mencionar?",
  [818107786559744] = "Cyril, me dê mais tempo... Tudo bem, não desperdice a paisagem do Lago Golden Autumn; vamos esquecer temporariamente tudo em Backlund.",
  [818107786559488] = "Eloise, por que você não o deixa? Ele não entende você de jeito nenhum; ele só quer uma máquina obediente.",
  [818107786559232] = "Ah, então ele deveria trabalhar no Backlund Court em vez de herdar uma editora.",
  [818107786558976] = "Ele sempre diz que a pontuação deve ser tão rigorosa quanto um contrato de casamento.",
  [818107786558720] = "Meu noivo pediu ao funcionário da editora que os adicionasse.",
  [818107786558464] = "A pontuação adicionada à coleção de poesia é como colocar braços em Vênus. Droga, de quem foi essa ideia?",
  [818107786558208] = "Chega de conversa, estou com pressa para pegar a próxima comissão.",
  [818107786557952] = "Você sabe, esses malditos Beyonder materiais são muito caros!",
  [818107786557696] = "Eu já disse que isso é nobre... Tudo bem, sim, estou usando Sequência habilidades para completar algumas comissões.",
  [818107786557440] = "Você está usando a habilidade de um Aprendiz para realizar tarefas?",
  [818107786557184] = "Fazendo recados? Esta é a nobre habilidade Porta Aberta de um Aprendiz!",
  [818107786556928] = "Se minha inspiração fosse maior, eu poderia usar <P_Yellow> Eyes of Mystery Prying </> para ver os traços mágicos residuais.",
  [818107786556672] = "Talvez eu tenha ficado muito animado depois de pegar os feijões mágicos e deixá-los cair no chão...",
  [818107786556416] = "Feijões mágicos, os feijões mágicos que finalmente recebi do presidente.",
  [818107786555904] = "Não só isso, a caixa está se movendo! Talvez você não consiga perceber, mas embora seja muito lento, ele está se movendo. Venho observando isso há muito tempo.",
  [818107786555648] = "Você sentiu o cheiro? Há um cheiro de vinho ao redor.",
  [818107786555392] = "Uma pequena linha de texto está gravada na base: O destino é como a expressão de um instrutor – quanto mais você quer saber, mais imprevisível ele é.",
  [818107786555136] = "Um dispositivo usado para adivinhação . Por ter suportado por muito tempo perguntas dos alunos como \"Qual é o escopo deste exame?\", ele sofreu um colapso mental e agora usa apenas a névoa para soletrar \"Vá revisar o Capítulo 4\" ou \"Sugerir mudança de curso\".",
  [818107786554880] = "O último capítulo foi arrancado, supostamente para evitar que os alunos tentassem convocar \"amigos amigáveis ​​do Mundo Espiritual\".",
  [818107786554624] = "…Olhando de perto, é apenas uma mancha deixada pelo dono anterior quando comiam ketchup.",
  [818107786554368] = "Um livro esfarrapado com 'O que fazer se estiver possuído, não ensinado pelo professor' rabiscado na página de rosto e suspeitas de manchas de sangue nas ilustrações.",
  [818107786554112] = "Deixe-me ver... \"Como coexistir pacificamente com as criaturas do mundo espiritual - do iniciante ao desistente\"?",
  [818107786553600] = "Está tudo bem, você ainda tem tempo para pensar.",
  [818107786553344] = "Eu... ainda não tenho certeza.",
  [818107786553088] = "Que tal, você vai se inscrever na competição?",
  [818107786552832] = "O que devo dizer?",
  [818107786552576] = "O efeito negativo é que fará com que a psicologia do portador fique gradualmente sombria, sempre na esperança de tomar atalhos, usar conspirações e confiar em meios desonrosos para fazer as coisas. Além disso, depois de usá-lo por mais de 3 minutos, o próprio usuário cairá em um estado de caos.",
  [818107786552320] = "Pode aumentar a dignidade e o físico, concedendo a capacidade de “distorcer” a linguagem, ações e intenções do alvo. Através do “suborno” simbólico, pode-se fazer com que o alvo desenvolva uma forte boa vontade e cause “caos” no alvo bloqueado ou na área circundante.",
  [818107786552064] = "Uma longa luva preta transparente que chega até o cotovelo, como se fosse da família real, possuindo um temperamento nobre e elegante.",
  [818107786551808] = "O efeito negativo é que enquanto você usá-lo, você nunca conseguirá se sentir fresco, estando sempre sob um calor terrível.",
  [818107786551552] = "Com ele como centro, um raio de dez metros será preenchido com poder puro e quente. Pessoas normais não conseguem perceber isso, mas monstros mortos-vivos serão continuamente danificados. Eles irão \"evaporar\" rapidamente como uma piscina sob uma bola de fogo escaldante, até mesmo Wraiths e Shadows, embora durem um pouco mais.",
  [818107786551296] = "Também conhecido como 'Solstício de Verão'. Um broche de ouro escuro em forma de pássaro solar.",
  [818107786551040] = "O efeito negativo é uma dor de cabeça constante, que dá vontade de bater a cabeça na parede.",
  [818107786550784] = "Pode causar danos mentais grandes e incontroláveis ​​aos inimigos. Fora isso, apenas fortalece o domínio de diversas armas.",
  [1143492898195712] = "A ajuda de \"Ele\"?",
  [818107786550272] = "O efeito negativo é que fará com que o usuário acumule emoções irritáveis ​​aos poucos. Isso não é um problema, desde que seja ventilado regularmente, mas tem outro efeito negativo: a pessoa que o segura tem 100% de probabilidade de ser atacada por monstros aterrorizantes nas profundezas da escuridão quando estiver em um ambiente sem luz!",
  [818107786550016] = "Pode emitir um som em batalha que deixa os inimigos aterrorizados e caóticos, como se o Deus do Trovão tivesse descido ao solo, rugindo incessantemente. Cada ataque carrega uma destrutividade intensa, e os relâmpagos aterrorizantes nunca estão ausentes.",
  [818107786549760] = "É bastante pesado, em forma de martelo gigante, com uma superfície azul profunda entrelaçada com raios branco-prateados, e suspeita-se que o cabo seja o osso da perna de uma criatura viva.",
  [818107786549504] = "O efeito negativo é que o usuário avaliará mal sua força real e sua percepção do ambiente ao redor diminuirá no curto prazo, facilitando a perda de itens.",
  [818107786549248] = "Aumenta significativamente a força do usuário e estimula sua capacidade de praticar boxe.",
  [818107786548992] = "Um par de luvas de boxe vermelhas.",
  [818107786548736] = "O efeito negativo é que depois que o usuário entra no espaço do loop, um quebra-cabeça mecânico aparece aleatoriamente em sua mão a cada ciclo. Deve ser resolvido dentro de um tempo limitado, caso contrário, serão devorados e transformados em um quebra-cabeça mecânico totalmente novo.",
  [818107786548480] = "Quando um dedo é inserido no anel, um símbolo de ciclo aparece no pulso, e a cena mais profunda da memória atual é lida, prendendo a alma em um loop infinito dessa cena. Aqueles que tocam o símbolo no pulso da vítima entram no espaço do laço como espectadores.",
  [818107786548224] = "Também conhecido como \"Labirinto Sem Fim\". Tira retangular de folha de ouro confeccionada com técnicas especiais, com uma extremidade torcida 180 graus e conectada à outra, formando um anel com apenas uma superfície.",
  [818107786547968] = "Embora eu ganhe mais soli de ouro, sempre sinto que estou sendo tratado como um cachorro farejador de drogas...",
  [818107786547712] = "Aí minha agenda ficou cada vez mais cheia!",
  [818107786547456] = "Até que um dia! Aquele maldito caçador, Bilt, descobriu que eu podia sentir o desconforto e o perigo no ambiente.",
  [818107786547200] = "Estou realmente muito cansado. Como um Caminho que não é forte em combate, poucos estudantes me convidam para participar de missões com eles...",
  [818107786546944] = "Você parece muito cansado.",
  [818107786546688] = "Pode suprimir minha inspiração até certo ponto aqui. Lá fora, sempre ouço vozes que os outros não conseguem, caindo em transe. Isso não acontece aqui; é muito confortável e tranquilo.",
  [818107786546432] = "Com licença, por que você está descansando na sala de observação do Mundo Espiritual?",
  [818107786546176] = "Descanse, eu preciso descansar...",
  [818107786545920] = "O único destino é a paz...",
  [818107786545664] = "Somente confiando em poções e deitado no chão da sala de observação do Mundo Espiritual posso entrar em um estado de semi-sonho e semi-desperto.",
  [818107786545408] = "Faz um tempo que não consigo dormir bem. Assim que fecho os olhos, melodias estranhas ecoam em meus ouvidos...",
  [818107786545152] = "Paz... Faz muito tempo que não sinto paz...",
  [818107786544896] = "Por que dormir no chão? O salão tem espaços mais confortáveis.",
  [818107786544640] = "Hehe... se você está curioso sobre esta poção, sugiro que vá direto ao salão e peça uma taça de vinho Rancy para a dona Amanda. No entanto, seu sabor é provavelmente um pouco melhor que o do vinho Rancy...",
  [818107786544384] = "Pode mantê-lo revigorado a noite toda, garantindo que você não adormecerá na sala de literatura; é um favorito entre os estudantes antes da semana de exames.",
  [818107786544128] = "Oh, esta é minha poção favorita! Faz com que as pessoas adormeçam rapidamente e tenham sonhos contínuos durante toda a noite.",
  [818107786543872] = "Ah... acordei de um sonho? Sobre qual você quer saber?",
  [818107786543616] = "Com licença, posso perguntar quais efeitos 'aquelas' poções do Joe têm?",
  [818107786543360] = "Ouvi passos, por favor não se preocupe comigo, deixe-me dormir...",
  [818107786543104] = "Na verdade, mesmo um verdadeiro “Vidente” só pode vislumbrar um canto confuso do destino.",
  [818107786542848] = "Existem muitas pessoas que afirmam investigar a verdade e mudar o destino depois de apenas aprender alguns adivinhação métodos.",
  [818107786542592] = "Não se preocupe, não se preocupe! Venha até mim a qualquer momento se tiver dúvidas!",
  [818107786542336] = "Mas não estou 'bem informado' sobre tudo. Rick sabe mais sobre fofoca.",
  [818107786542080] = "Trabalhar? Isso não conta como trabalho, haha. Sou uma pessoa que gosta de conversar. Quanto mais eu converso com todo mundo, mais eu sei, então eles gostam de me chamar de 'Pequeno Sabe-Tudo'.",
  [818107786541824] = "Ah, falei demais por acidente. Espero que você não se importe com minha importunação.",
  [818107786541568] = "Claro, se você estiver interessado em adivinhação , você também pode tentar lá...",
  [818107786541312] = "Se você quiser encontrar um lugar mais tranquilo, você pode ir até a sala de observação do Spirit World próxima ao fragmento da Barreira.",
  [818107786541056] = "Geralmente passamos muito tempo nessas áreas; é bastante animado.",
  [818107786540800] = "Perto do Salão dos Tolos, no primeiro andar da escola, ficam a Sala de Poções, o salão e a sala de literatura; mais longe fica a área de teste.",
  [818107786540544] = "Clube do Tarô 'Pequeno Informante', prazer em atendê-lo.",
  [818107786540288] = "Ansioso pelo nosso próximo encontro.",
  [818107786540032] = "Sonho em me tornar alguém como ela; ela é meu ídolo e modelo.",
  [818107786539776] = "Dona Justiça é corajosa, firme, bonita e elegante. Ela se preocupa com todos no clube e, por mais dificuldades que surjam, conversar com ela parece torná-las facilmente resolvidas.",
  [818107786539520] = "Aos olhos de um espectador, todo mundo é um bom ator.",
  [818107786539264] = "Jeremy está bebendo suas mágoas, parecendo bêbado, mas seus olhos estão muito claros... Seu olhar estava olhando secretamente para a Sra.",
  [818107786539008] = "O Sr. Oliver continua convidando outras pessoas para tocar, ele está muito entusiasmado... A amplitude do balanço do braço dele é bem grande, hmm, deveria ser para aliviar o constrangimento de ele afirmar ser pianista mas não ser reconhecido por aquele piano.",
  [818107786538752] = "A observação é uma coisa interessante, não acha?",
  [818107786538496] = "Claro, a premissa é obter sua aprovação. Você quer tentar?",
  [818107786538240] = "Ouvi dizer que o piano tem espiritualidade ; contanto que você fique sentado lá, não precisará pensar em nada para tocar uma melodia melodiosa.",
  [818107786537472] = "Porter sempre gosta de se esconder e cantar.",
  [818107786536704] = "Não, também requer espiritualidade ... Tenho uma ideia nova!",
  [818107786536448] = "Se for bem-sucedido, você só precisará dos pontos de coordenadas correspondentes para alcançar o 'Teletransporte'.",
  [818107786536192] = "…Podemos explorar e construir um modelo matemático para teletransporte espacial.",
  [818107786535936] = "Através da análise da mecânica quântica da distorção do espaço-tempo e do movimento microscópico de partículas...",
  [818107786535680] = "Louco! Eles são todos loucos! Aconselho você a ficar longe deles, ou mais cedo ou mais tarde você também se transformará em cogumelo.",
  [818107786535424] = "Quanto aos cogumelos, ah... esses são o avatar do mal! Mais cedo ou mais tarde, destruirei todos os cogumelos!",
  [818107786535168] = "Se você já tivesse sido sufocado por uma espinha de peixe, também concordaria comigo.",
  [818107786534912] = "Acredite, você virá perguntar mais cedo ou mais tarde.",
  [818107786534656] = "Adicione fogo quando estiver frio, adicione gelo quando estiver quente; é simples assim... Porém, o momento, o momento é muito importante.",
  [818107786534400] = "Isso não é algo que você possa controlar casualmente. Não recomendo para alunos que acabaram de ingressar no Clube do Tarô ; afinal, isso requer controlar o poder do gelo e do fogo.",
  [818107786533888] = "O que é? Se não houver nada, não me perturbe. O primeiro passo para se tornar um aluno qualificado é aprender a usar o forno sozinho.",
  [818107786533632] = "Dizem que alguém violou as regras e se esgueirou até lá, mas nunca mais voltou.",
  [818107786533376] = "Embora eu esteja muito curioso sobre o que há lá embaixo, permanecer vivo é mais importante.",
  [818107786533120] = "O nível do porão armazena artefatos selados de nível superior, que são muito perigosos.",
  [818107786532864] = "Expresso minha gratidão a você em nome deles.",
  [818107786532608] = "…Ei, quando você pegar emprestado um Artefato Selado, tente ser legal com eles… não deixe chover neles.",
  [818107786531840] = "…Não me olhe assim, não tenho aquele hobby especial como a Primavera. Candidatei-me para proteger este lugar porque meus amigos estão todos aqui.",
  [818107786531072] = "Alguns itens místicos possuem a característica de estarem ‘vivos’, o que atrairá as pessoas ao seu redor, tentando escapar; por favor tenha muito cuidado.",
  [818107786530816] = "Para alguns itens místicos com efeitos negativos muito graves, a escola irá selá-los para evitar que causem consequências catastróficas.",
  [818107786530560] = "Itens místicos geralmente são produtos formados pela combinação de Característica de Beyonder e outras coisas. Eles são raros em número e muitos apresentam falhas óbvias e efeitos negativos.",
  [818107786530304] = "Por favor, não se aproxime casualmente; é fácil cair no caos.",
  [818107786530048] = "A maioria dos itens místicos em Clube do Tarô são armazenados aqui, alternados pelos 'Guardiões' dentro da escola.",
  [818107786529792] = "A guarda também é uma forma de proteção; é uma coisa significativa.",
  [818107786529536] = "Talvez, se esta poção for feita, ela apareça?",
  [818107786529280] = "Parece estar desenvolvendo algum tipo de poção? Esta é a fórmula da poção que ouvi; é uma perspectiva muito nova que tenho pesquisado recentemente.",
  [818107786529024] = "Uma coisinha apareceu recentemente na Sala de Poções, bastante encrenqueira... mas sua perspectiva sobre poções ainda é interessante.",
  [818107786528768] = "Mas também permaneça vigilante em todos os momentos; alguns alunos adoram pegadinhas, então seja cauteloso ao lidar com poções que você consome.",
  [818107786528512] = "Além da preparação de poções, a Sala de Poções também é uma plataforma para discussão e troca de poções. Caso tenha interesse, você pode se comunicar com os alunos aqui; você pode ganhar alguma coisa.",
  [818107786528256] = "A escola dominou as Sequências completas de vários Caminhos; pagando um preço suficiente, pode-se trocar pelas fórmulas e materiais correspondentes.",
  [818107786528000] = "Após longos experimentos e exploração, as pessoas aperfeiçoaram o sistema de poções e formaram uma cadeia Sequência estável. Quanto menor o número Sequência, maior será a nota da poção.",
  [818107786527744] = "Os nomes das poções vêm da Blasphemy Slate, que registra um total de vinte e dois Caminhos divinos.",
  [818107786527488] = "Os humanos que desejam se tornar Beyonders e continuar no caminho do extraordinário só podem contar com poções.",
  [818107786527232] = "Este aluno, você encontrou algum problema?",
  [818107786526976] = "<P_Heart> (suspira) </> Eu disse, isso não é uma coisa boa...",
  [818107786526720] = "Spratt! Por que não pensei nisso? É brilhante! Eu tenho uma nova ideia!",
  [818107786526208] = "Adicionar um pouco não é problema; já está na poção, e não ouvi falar de ninguém morrendo por beber uma poção...",
  [818107786525952] = "Você está tentando enviar alguém diretamente para o reino divino da Deusa da Noite Eterna?",
  [818107786525696] = "Pó de múmia?",
  [818107786525440] = "<P_Heart> (balança a cabeça) </> Tentei, o efeito não foi muito bom.",
  [818107786525184] = "Flor do Sono Profundo?",
  [818107786524928] = "Existem ervas que podem acalmar as pessoas?",
  [818107786524672] = "Isso foi para verificar o efeito da respiração subaquática... Esqueça, não vamos falar sobre isso.",
  [818107786524416] = "Deixar Collette desenvolver uma poção não é uma coisa boa. Você, você esqueceu o rato branco que cresceu guelras e rabo de peixe da última vez?",
  [818107786524160] = "Oh, Jane, não se vanglorie. Seja educado e deixe Collette terminar.",
  [818107786523904] = "Existe algo tão bom?",
  [818107786523648] = "Minha pesquisa de poções atingiu um gargalo...",
  [818107786523392] = "Recentemente... ela deveria estar na sala de observação do Mundo Espiritual; o lado de fora é muito barulhento para ela.",
  [818107786523136] = "Ei, não posso dizer. Se você realmente quer saber, por que não perguntar a alguém que comprou? Deixe-me pensar, vá encontrar na escola quem mais gosta de dormir; você receberá uma avaliação honesta.",
  [818107786522880] = "O que você quer comprar? Atualmente tenho 'Angellweed's Dream', 'Night Visit of the Witch' e 'Fire-Bathed Ouroboros'.",
  [818107786522624] = "Isto... isto não é conveniente dizer. Se você subir de lá para o segundo andar, alguém lhe dará a resposta.",
  [818107786522368] = "Ei, você precisa desse tipo de poção?",
  [818107786520064] = "Isto é, isto é chá com leite! Você não vai me ensinar a preparar uma poção de hipnose?",
  [818107786518784] = "Shh! Shh... fale baixo, você pode me devolver primeiro? O tempo que combinei com o Professor Fors está quase acabando...",
  [818107786518528] = "Oh, você está falando sobre 'O Pequeno Malandro do Mundo Espiritual' que você escreveu? Gosto mais da parte em que o malandro irrita mais a Duquesa do Castelo, é...",
  [818107786518272] = "Não! <P_Heart> (sussurrando) </> Esse 'manuscrito'... você terminou de ler?",
  [818107786517760] = "Não há tempo! Não atrapalhe meus estudos!",
  [818107786517504] = "Língua gigante, Élfico, Dracônico, Antigo Hermes, Hermes, Antigo Feynapotter, Loen... por que preciso aprender tantos idiomas? Preciso me comunicar com um Dragão Gigante?",
  [818107786517248] = "Os jovens de hoje em dia... suspiro, realmente carecem de espírito empreendedor. Se você pudesse ter metade do esforço de Roselle...",
  [818107786516992] = "É Roselle! É o grande Imperador Roselle! Você sabe? Roselle inventou a máquina a vapor; ele liderou o mundo adiante...",
  [818107786516736] = "Mas você sabe quando e onde o Imperador Roselle disse isso? Você não sabe disso, não é? Deixe-me dizer, naquele dia, Roselle estava andando na estrada...",
  [818107786516480] = "Resposta correta. Parece que você se adaptou muito bem.",
  [818107786515968] = "Tenho que encontrar um lugar para me esconder primeiro... Seria terrível se descobrissem que bebi secretamente uma poção para estudar a noite toda.",
  [818107786515712] = "Aqueles dois idiotas lá embaixo, não sabem que precisam ficar quietos aqui?",
  [818107786515456] = "O que você está pensando! Estudo! Uma sessão de estudo para dois!",
  [818107786515200] = "Isso não seria bom... <P_Heart> (tímido) </>",
  [818107786514944] = "Já que você já está aqui, por que não experimentar um momento a dois hoje? Não vamos contar ao Ken e à Sarah.",
  [818107786514688] = "Uh... fui eu quem te perguntou primeiro...",
  [818107786514432] = "Então por que você está aqui? Hum?",
  [818107786514176] = "Estudando em segredo novamente! Combinamos de ir ao salão jogar jogos de tabuleiro hoje.",
  [818107786513920] = "A vida é sempre assim: há desentendimentos e reconciliações, não é?",
  [818107786513664] = "…Mas não poderia ser pior.",
  [818107786513408] = "Você a ouviu me mencionar? Isso não deve ter sido nada de bom.",
  [818107786513152] = "Peça emprestado conforme necessário e devolva no prazo.",
  [818107786512896] = "Alguns materiais com maior autorização de segurança requerem aplicações e testes adicionais. Afinal, Conhecimento é Poder, e nem todos podem suportar uma força poderosa.",
  [818107786511872] = "Ser bibliotecário não é uma profissão fácil; há muitas coisas perigosas escondidas por trás do conhecimento.",
  [1143563228286208] = "O “Anjo do Castigo”, Ele é o trovão do Senhor, a ira do Senhor, a palma do Senhor; Ele é o juiz e executor de todos os caídos e impuros.",
  [818107786511104] = "Divulgaremos comunicados dentro da escola antes da realização das atividades, aguardando a sua participação!",
  [818107786510848] = "Por exemplo, o Grupo de Pesquisa de Cogumelos Boutique de Frank, o Dragão Gigante e o Grupo de Pesquisa Gigante... liberdade de interesse, liberdade de escolha!",
  [818107786510592] = "Grupos de interesse?",
  [818107786510336] = "Possui três subassociações: Animais Mágicos, Plantas Mágicas e Criaturas do Mundo Espiritual e, mais abaixo, existem alguns grupos de interesse especial.",
  [818107786510080] = "Através dos esforços de vários membros da associação, a Associação de Proteção às Criaturas Mágicas tomou agora forma inicial.",
  [818107786509824] = "Amigo, espécies extraordinárias estão gradualmente desaparecendo neste mundo; é hora de nos unirmos e protegermos essas criaturas ameaçadas.",
  [818107786509568] = "Anteriormente, alguém andava de bicicleta e pendurava-a no Pulso da Vida; aquela bicicleta ofensiva ainda está na sala do artesão.",
  [818107786509056] = "…O que você acha?",
  [818107786508800] = "Chloe, olha, andar de bicicleta é proibido na escola, hahahaha, que regra absurda da escola... por que você não está rindo?",
  [818107786508544] = "Se não houver progresso, irei à “Associação Chave Mágica” e pedirei ajuda à Sra.",
  [818107786508288] = "Eu sei que o que dizem é certo, mas 'Bárbaro' é realmente difícil de representar...",
  [818107786508032] = "Mas os mentores da escola sugeriram que eu avançasse para Sequência 7 'Navegador' antes de sair, para que eu pudesse ter uma noção das correntes oceânicas, direções do vento e assim por diante, e os navios com um 'Navegador' nunca se perdem em alto mar.",
  [818107786507776] = "Veja bem, nosso mundo é composto por quatro continentes e cinco oceanos. E os lugares em que pisei são apenas um pouquinho. Eu realmente quero sair e me tornar um grande aventureiro como Gehrman Sparrow.",
  [818107786507520] = "Tudo bem, eu sabia que ninguém concordaria, que tentativa fracassada.",
  [818107786507264] = "Desculpe, não... não posso me desculpar, você pode me repreender duas vezes?",
  [818107786507008] = "Olá, não, você não está bem, não...",
  [818107786506752] = "No entanto, mais dados são necessários para verificá-lo.",
  [818107786506496] = "Eu também acho. Talvez todos esses contos de fadas e lendas tenham sido transmitidos deste tempo e espaço para o nosso mundo.",
  [818107786506240] = "No entanto, em nosso mundo, tudo isso são contos de fadas; não há evidências de que sejam reais. Estou mais inclinado a acreditar que o conhecimento oculto deste mundo perturbou o espaço-tempo e foi transmitido ao nosso mundo.",
  [818107786505984] = "Ah? Essa ideia também tem alguma verdade.",
  [818107786505728] = "Isso mostra que tudo nos contos de fadas é verdade, não mentira; eles realmente aconteceram. Portanto, este mundo...",
  [818107786505472] = "E aqui, toda a magia é criada pelo presidente, como a Primavera em Flor de Pessegueiro, João e o Pé de Feijão...",
  [818107786505216] = "Simplificando, é a capacidade de criar magia através de algum conhecimento oculto, e quanto menos pessoas conhecerem esse conhecimento oculto, melhor será o efeito.",
  [818107786504960] = "Peguei emprestados materiais da biblioteca de literatura e descobri que a habilidade central do Espreitador de Mistérios Caminho Sequência 4 Mysteryologist é a Reconstituição Mística.",
  [818107786504704] = "Que ideia?",
  [818107786504448] = "Tenho uma ideia ousada.",
  [818107786504192] = "Esqueça, daqui a pouco vou perguntar à Bessie... Ela está um pouco silenciosa hoje, quem a deixou com raiva?",
  [818107786503424] = "Esse tipo de vida tranquila, onde você só precisa pensar no que comer na próxima refeição, é algo que eu nem ousava imaginar antes de vir para o Clube do Tarô .",
  [818107786503168] = "Limpar, arrumar... na verdade, há muito pouco trabalho para os alunos fazerem na escola. Na maioria das vezes, apenas encontro algum trabalho para mim.",
  [818107786502912] = "As roupas do presidente fazem as pessoas se sentirem acessíveis e combinam muito com o ambiente da época, e pouquíssimas pessoas usam o mesmo estilo de roupa, então não tenho mais medo de usar as mesmas coisas que os outros!",
  [818107786502656] = "Decidi ignorar Peter. Na verdade, ele disse que minha roupa era estranha, quando eu estava claramente imitando a presidente, e ela é a líder de toda a tendência de moda da escola!",
  [818107786502400] = "Lembre-se: o nome da poção é a chave para atuar.",
  [818107786502144] = "Existem muitos Beyonders cuja digestão é lenta devido à falta de oportunidades para agir e, pior ainda, alguns caem no caos. Estabelecemos a 'Sociedade da Chave da Poção' para resolver este problema.",
  [818107786501888] = "Tudo isso é inseparável da vida concreta, da identidade e das pessoas.",
  [818107786501632] = "Você sabe sobre o 'Método de atuação', certo? O 'Método de atuação' envolve interpretar o nome da poção, obter seus símbolos centrais e imagens específicas, encaixar-se nela na vida diária e resumir as regras de atuação.",
  [818107786501376] = "Porque choveu sobre mim, quero segurar um guarda-chuva para os outros.",
  [818107786501120] = "Ao mesmo tempo, para membros que têm dificuldade em digerir poções, organizamos projetos de prática social e criamos identidades sociais convenientes para atuar.",
  [818107786500864] = "Realizamos regularmente palestras sobre história e cultura para popularizar o conhecimento comum da época.",
  [818107786500608] = "Olá, há algo em que eu possa ajudá-lo?",
  [818107786500352] = "Mas... mas ele parece tão sério que não me atrevo a me aproximar dele.",
  [818107786500096] = "Ele passa seu tempo completando missões atribuídas pelo Sr. Louco, aparentemente procurando por algo no mar, e apenas ocasionalmente retorna à escola.",
  [818107786499840] = "Na verdade, o Sr. \"O Enforcado\" é um instrutor muito bom.",
  [818107786499584] = "Finalmente encontrei... por que teve que coincidir com o retorno do Sr. Alger, suspiro...",
  [818107786499328] = "Joan me confiou isso; ela tem forte espiritualidade e foi levada à insônia, então ela se escondeu na sala de observação do Mundo Espiritual.",
  [818107786499072] = "Não entenda mal! Estou investigando o canto misterioso que apareceu na escola recentemente...",
  [818107786497792] = "Não, na verdade não...",
  [818107786497536] = "Nós dois também não podemos. Tudo bem, você pode convencer Collet a desistir da pesquisa de poções?",
  [818107786497280] = "Não posso, mas...",
  [818107786497024] = "Você consegue vencer Collet?",
  [818107786496768] = "Não fique tão indiferente! Uma sensação de crise, você deve ter uma sensação de crise!",
  [818107786496256] = "Harry! Você sabe, a equipe de fiscalização sempre vem limpar depois que as coisas terminam. Precisamos erradicar esse fenômeno pela raiz.",
  [818107786496000] = "Não encontrei as autoridades oficiais para cuidar disso? Collet até pagou uma grande quantia em dinheiro.",
  [818107786495744] = "Não podemos deixar Collette continuar assim... A poção que ele desenvolveu da última vez causou uma infestação de ratos diretamente em Tingen; aqueles ratos ficaram maiores que minha cabeça.",
  [818107786495488] = "Eles parecem estar falando sobre algo incrível.",
  [818107786495232] = "Se possível, espero que você mantenha isso em segredo de George; Quero fazer uma surpresa para ele.",
  [818107786494720] = "Por que você ainda está escondido aqui para praticar?",
  [818107786494464] = "Ah, é você! Graças à sua ajuda. Achei que cantar é muito interessante e agora sou o vocalista do grupo de canto.",
  [818107786494208] = "Oh, uh, não... você ouviu errado.",
  [818107786493696] = "A verdadeira natureza do mundo é a ordem, o retorno ao estado original é inevitável.",
  [818107786493184] = "A verdadeira natureza do mundo é a desordem, por que não fazer o que bem entendemos?",
  [818107786492928] = "Tentamos estabelecer a ordem num mundo caótico, como andar sobre um cabo de aço no ar. O que a humanidade está fazendo agora é uma mudança necessária ou um autocontrole sem sentido?",
  [818107786491904] = "Caçador.",
  [818107786491648] = "Qual é o seu Caminho ?",
  [818107786491392] = "Não despreze as pessoas com Sequência inferior ao seu; um Sequência 8 também pode derrotar um Sequência 5...",
  [818107786490880] = "Uh, desculpe, se você está procurando um parceiro de treino, é melhor perguntar a Sonya ou encontrar um boneco de madeira como eu.",
  [818107786490624] = "Se você se tornar como ele, lembre-se de procurar um \"psiquiatra\".",
  [818107786490368] = "Anteriormente, o time deles fez um missão junto e só ele voltou. Desde então, ele tem sido uma pessoa diferente.",
  [818107786490112] = "Não olhe assim para Haze, ele costumava ser um capitão muito bom.",
  [818107786489344] = "Etiqueta pré-batalha? Não entendo, mas aplaudir nunca é errado.",
  [818107786489088] = "Bond dá uma flor ao oponente antes de cada luta.",
  [818107786488832] = "Muitas vezes me sinto como uma marionete, com todos os resultados já combinados.",
  [818107786487040] = "…Chama-se \"Gulu\", é meu mensageiro, não, meu amigo.",
  [818107786486784] = "Ele manca levemente e pode cheirar a álcool.",
  [818107786486528] = "Se acontecer de você encontrar uma criatura parecida com um cofre, por favor, dê uma carona e eu lhe darei uma recompensa.",
  [818107786486272] = "Tudo bem, estou brincando, não fique tão tenso. Se o céu cair, os altos o sustentarão.",
  [818107786486016] = "Tudo bem, então vamos viver com urgência.",
  [818107786485760] = "Você não sente que o tempo é muito urgente? Digerindo poção, treinamento de combate, missão prática...",
  [818107786485504] = "Você é quem não está fazendo o seu trabalho adequado; Estou vivendo a sério, apreciando esta magnífica Barreira e a bela vista da janela.",
  [818107786485248] = "…Devemos ser tão pouco profissionais?",
  [818107786482944] = "O “Anjo do Tempo”, Ele é um anjo dos tempos antigos que eventualmente se submeteu ao meu Senhor, tocando o sino do Reino dos Céus para Ele.",
  [818107786482432] = "O “Anjo de Mercúrio” é o avatar do destino, o anjo mais favorecido por meu Senhor; o “Anjo da Morte” é a existência que há mais tempo segue meu Senhor, o administrador do Submundo; o “Anjo da Redenção” é o chifre do meu Senhor, o mensageiro do Seu oráculo; o “Anjo da Vida” é a cristalização da sabedoria, o inextinguível espiritualidade dentro de cada pessoa.",
  [818107786481664] = "Este {Sr. {EM. |}}, posso reservar um momento do seu tempo? Eu gostaria de falar-lhe sobre meu Senhor, Sr. Tolo.",
  [818107786481408] = "Velho misterioso, espaço estranho, o próximo deve ser o sistema emitindo um missão ... <P_Heart> (cai resmungando para si mesmo) </>",
  [818107786481152] = "Você também é um escolhido, certo? Sempre há algumas pessoas neste mundo que são especiais, não é mesmo?",
  [818107786480896] = "É pelo menos mais silencioso aqui, sem aqueles sons estrondosos.",
  [818107786480640] = "Sangue, caos, lamentos... o que há para perder?",
  [818107786480384] = "Heh, por que aquele grupo de pessoas sentiria falta de um lugar assim?",
  [818107786480128] = "Não, sem família... É melhor você ficar longe de mim. Dizem que o infortúnio é contagioso, a praga mais difícil de resolver.",
  [818107786479872] = "Um lugar com família também é casa, ou seja, um lugar onde estão parentes e amigos.",
  [818107786479616] = "Então eu não tenho casa.",
  [818107786479360] = "O lar é um lugar onde a pessoa se sente segura e confortável.",
  [818107786479104] = "Hehe, isso é ridículo? Ria então, eu sei que é ridículo, um fraco tentando proteger o forte.",
  [818107786478848] = "Ele me salvou, eu estou... protegendo-o.",
  [818107786478592] = "Sr. Sun é uma pessoa muito simples, calorosa, gentil... É difícil imaginar que alguém que já vivenciou o lado negro deste mundo ainda consiga manter tamanha sinceridade.",
  [818107786478336] = "Sr. Sun diz para tratar o Clube do Tarô como lar, o que é isso? Essa é a cidade natal sobre a qual o grupo de pessoas fica resmungando?",
  [818107786478080] = "<P_Heart> (suspirando) </> Pelo menos ainda temos muitos companheiros de casa.",
  [818107786477824] = "Estou com um pouco de saudade de casa... Meus amigos e familiares estão tão longe. É difícil para mim voltar para minha cidade natal, mas não consigo me integrar aqui.",
  [818107786477568] = "Se estamos em um sonho, ou ainda mais reconfortante. Sem perigo e loucura, sem sangramento e sacrifício...",
  [818107786477312] = "Às vezes me pergunto se a cena diante dos meus olhos é apenas um sonho brilhante e fugaz?",
  [818107786477056] = "Molly, vamos reconsiderar...",
  [818107786475520] = "Nós realmente temos que colocá-lo aqui? Não será um pouco estranho?",
  [818107786475264] = "Isso é algo que pode ser dito? Deus, alguém pode fazê-los calar a boca?",
  [818107786475008] = "História não oficial! De acordo com pesquisas, atualmente só pode ser comprovado que o Sr. Louco e o Imperador Roselle tiveram uma aliança, e disso podemos deduzir o papel significativo do sentimento local no processo de fundação...",
  [818107786474752] = "Claro! Esta é a pedra angular da fundação do Clube do Tarô. Tenho motivos suficientes para suspeitar que o Sr. Louco e o Presidente são tio e sobrinho...",
  [818107786473984] = "Um verdadeiro milagre! Não esperava que um objeto de tão alto nível fosse colocado no lugar mais visível.",
  [818107786473728] = "Ah? Não estava apenas repetindo a pergunta anterior de Arrodes...",
  [818107786473472] = "<P_Heart> (corando) </> Maddy! Pare, o que você está fazendo!",
  [818107786473216] = "\"Você teve algum sonho erótico ultimamente? Quem são os protagonistas dos seus sonhos eróticos?\"",
  [818107786472960] = "Sim, atacar diretamente a alma, enfrentando os assuntos mais íntimos e indesejados de todos...",
  [818107786472704] = "Golpeie diretamente na alma!",
  [818107786472448] = "Como devo dizer, as perguntas frequentes de Lord Arrodes...",
  [818107786472192] = "Morte social?",
  [818107786471936] = "Ontem, três pessoas foram atingidas por um raio, e depois ocorreu a morte social de uma, duas, três, quatro... Já perdi a conta.",
  [818107786471680] = "Mas de acordo com o princípio da equivalência, Arrodes também exigirá que a outra parte responda a uma pergunta ou aceite a punição de um Raio.",
  [818107786471424] = "Nada demais, os recém-chegados estão sempre cheios de curiosidade sobre este lugar, e então fazem perguntas a Lord Arrodes.",
  [818107786471168] = "O que ele fez?",
  [818107786470912] = "Discutindo? Discutindo sobre o azarado recém-chegado que foi enganado por Rick...",
  [818107786470656] = "O que você está discutindo?",
  [818107786470400] = "Uh, não importa então... Adeus, adeus.",
  [818107786470144] = "Se você está nervoso por enfrentá-Lo sozinho, estou disposto a ir com você!",
  [818107786469888] = "Não fique nervoso, nossa Clube do Tarô é uma família amorosa. Se encontrar dificuldades, pode consultar o grande Lorde Arrodes; Ele dará a resposta...",
  [818107786469632] = "Já faz muito tempo que não vejo um recém-chegado tão fofo.",
  [818107786469376] = "Ahem, você é novo no Clube do Tarô , certo?",
  [818107786469120] = "Se eu soubesse que você queria perguntar isso, eu não teria... suspiro...",
  [818107786468864] = "…Ele não responderá a tais problemas matemáticos não resolvidos ou paradoxos clássicos.",
  [818107786468608] = "O que devo fazer, fui, fui rejeitado...",
  [818107786468096] = "Recuso-me a responder a esta pergunta.",
  [818107786467840] = "Grande Lorde Arrodes, a conjectura de Goldbach pode ser verificada?",
  [818107786467584] = "Pergunte com ousadia, não fique nervoso.",
  [818107786467328] = "Tem uma dúvida que me incomoda há muito tempo...",
  [818107786467072] = "Tosse, tosse... Nem chegou à fase de perguntas e respostas. Parece que os dados precisam ser complementados; Lord Arrodes não encorajará comportamento oportunista...",
  [818107786466816] = "… (Arrodes lança um raio, a ser adicionado assim que o recurso for integrado)",
  [818107786466560] = "Grande Lorde Arrodes, posso perguntar quais são as questões do exame?",
  [818107786466304] = "Claro, compilei um “Guia completo para perguntas e respostas de Arrodes”, que testei várias vezes. Os dados provam que Lord Arrodes não tornará as coisas muito difíceis para os alunos.",
  [818107786466048] = "Oh? Então, de acordo com o princípio da equivalência, você está pronto para responder à Sua pergunta?",
  [818107786465792] = "A participação é o que importa... Estou preparado para pedir a Lord Arrodes, esperando a proteção do Sr. Tolo.",
  [813709740374784] = "Você quer usar aquele fogão?",
  [813709740349696] = "Você não sofrerá de insônia se passar mais algumas noites inteiras.",
  [813709740348928] = "Ferva... adicione 150 mililitros de leite puro... mexa...",
  [813709740337920] = "O que aconteceu?",
  [813709740334080] = "Aquele cara, Spring, tem um temperamento estranho, mas pelo menos se preocupa com meu amigo, então deixe-o em paz.",
  [813709740333824] = "Hehe... é que todos eles se transformaram em Artefatos Selados agora.",
  [813709740333312] = "Não, foi você quem tocou no assunto primeiro... Certo, tosse, qual é o seu propósito ao dizer isso? Qual é o seu motivo? Quem te colocou nisso? Você foi enfeitiçado por alguma existência perigosa? Venha comigo!",
  [813709740333056] = "<P_Yellow> Tosse, tosse, tosse, tosse, tosse, não, eu não disse nada! Por favor, esqueça! </>",
  [813709740332800] = "Além de fazer as pessoas crescerem com chifres e rabos, se tornarem fortes e resistentes, e serem capazes de mugir... <P_Heart> (sentindo-se gradualmente culpado) </> , há algum outro benefício em cruzar humanos e vacas?",
  [813709740332544] = "Tosse, tosse... Meu Deus, o que você está pensando? Eu, eu não pensei em uma coisa tão bizarra!",
  [813709740332288] = "Ah, isso mesmo, você realmente me entende! Este seria um avanço que marcou época!",
  [813709740332032] = "Se eu pudesse aprender as etapas operacionais detalhadas, então teria uma ideia ousada...",
  [813709740331776] = "Ouvi dizer que um grande biólogo certa vez cruzou trigo com miudezas bovinas. Este foi um enorme salto evolutivo para a espécie! Sempre fiquei curioso para saber por que não consigo encontrar nenhuma literatura relevante em lugar nenhum.",
  [813709740331008] = "Estou planejando fazer uma placa clássica, da-da-da-da! 'O vento que sente sua falta finalmente soprou para o Clube do Tarô', que tal?",
  [813709740330752] = "\"Dá uma sensação de casa.\"",
  [813709740330496] = "Ah, alguém recentemente fez uma sugestão na caixa de correio do Presidente, na esperança de adicionar algumas decorações dentro da escola...",
  [813709740330240] = "Do que vocês estão falando?",
  [813709740328960] = "Há algum sentido em discutir isso...",
  [813709740328704] = "Aterrorizante... ser capaz de esculpir um mundo no Mundo Espiritual e construir uma arquitetura tão magnífica, admiro cada vez mais o figurão por trás disso.",
  [813709740322560] = "“Os livros são a escada do progresso humano”… Deixe-me testar você, quem disse isso?",
  [813709740318464] = "Torta picante? Ensopado de borrego com ervilhas? ...Ou talvez costelinha refogada de Dargua?",
  [813709740318208] = "O que devo comer esta noite...",
  [813709740317696] = "Hum... interessante. A Grande Civilização Antiga já pereceu, mas depois que a humanidade sobreviveu, eles reconstruíram uma sociedade próspera. A ordem é um sinal de estabilidade da civilização? Obrigado pela sua resposta.",
  [813709740317184] = "Hum... interessante. Construir a ordem com base no que se considera “correção” – será isso também uma forma de desordem? Obrigado pela sua resposta.",
  [813709740316416] = "Uma ordem poderosa é incrivelmente perigosa. Isso fará com que você lute contra a dor e ao mesmo tempo só consiga duvidar de si mesmo: fiz algo errado? Você não conseguirá perceber o erro do próprio pedido.",
  [813709740316160] = "Ela escreve as regras, utiliza as regras, aprisiona os seus inimigos e leva-os a um beco sem saída.",
  [813709740315904] = "Você já ouviu falar do Trunsoest Brass Book?",
  [813709740315648] = "Eu só quero ficar com meu amigo boneco de madeira para sempre.",
  [813709740314624] = "Às vezes ele olha para a multidão rindo com uma expressão atordoada, soltando um suspiro longo e persistente...",
  [813709740314368] = "O instrutor Colin parece ser o mais singular entre todos os instrutores.",
  [813709740314112] = "Heh... você entenderá quando cair ao meu nível.",
  [813709740313600] = "Vou esperar por ele aqui.",
  [813709740313344] = "Acho que Martin está lá fora. Se você o vir, ajude-me a transmitir uma mensagem: se você deseja progredir, deve enfrentar o seu medo.",
  [813709740313088] = "Eu era um Guerreiro que evitava treinar, até...",
  [813709740308736] = "Se tiver tempo, você pode entrar e ajudar o Sr. Scharf.",
  [813709740308480] = "Cansado? Você ouviu errado. Eu quis dizer que esse cinto está um pouco apertado. Tenho a sorte de poder tocar em máquinas tão precisas e perfeitas.",
  [813709740307200] = "Por que você me chamou? Você finalmente está interessado nos \"Fundamentos da Tecnologia de Fabricação Mecânica\"?",
  [813709740304896] = "Vá para casa, vá para casa... Suspiro, se fosse assim tão fácil ir para casa, eu já teria voltado há muito tempo.",
  [813709740304640] = "O que é ainda mais ridículo é que alguns dizem que se você acertar três vezes seguidas, você pode ir para casa...",
  [813709740304384] = "Não sei de onde veio o boato de que se você ficar de costas para a Fonte da Purificação, segurar uma moeda na mão direita e jogá-la na água por cima do ombro esquerdo, poderá realizar seu desejo.",
  [813709740303872] = "Não dê ouvidos a rumores... como isso está se espalhando ainda mais?",
  [813709740303616] = "Acho que você é pior que um peixe salgado; pelo menos um peixe salgado pode ser comido! O que você pode fazer além de aumentar minha carga de trabalho!",
  [813709740303360] = "Uh, não, ainda estou tentando... As pessoas sempre têm que ter sonhos, caso contrário, qual a diferença entre eles e um peixe salgado.",
  [813709740303104] = "…Você já rolou?",
  [813709740302848] = "Role um 20! Sucesso crítico!",
  [813709740302592] = "Transbordando sorte?",
  [813709740302336] = "Não fique com raiva... Ouvi dizer que jogar uma moeda aumenta a sorte, e pessoas com muita sorte podem obter Beyonder recompensas na Fonte da Purificação!",
  [813709740301056] = "Os arquivos acolhem todos os que anseiam por conhecimento.",
  [813709740299776] = "Ele sempre trabalha tanto que isso me preocupa... Se você conhecer Potter, lembre-se de dizer a ele para vir para a sala para relaxar quando tiver tempo, e para não colocar muita pressão sobre si mesmo.",
  [813709739961856] = "Ei, aqui para melhorar novamente hoje?",
  [519109612136704] = "<P_Heart> (Pondera) </> Logicamente, deveria ser arranjado pelo Capitão, mas este caso não é complicado. Posso levar você junto; considere isso um estágio.",
  [519109612136448] = "Vi o rastreamento de casos do Mercado Negro das Lamentações no manual do funcionário; posso participar?",
  [519109612136192] = "Capitão? <P_Heart> (Balança a cabeça) </> Rozanne me deu o pacote de presente do recém-chegado e me disse para caminhar por Tingen para me familiarizar com o ambiente.",
  [519109612135936] = "Xiga. O capitão enviou você?",
  [519109612135680] = "Sim. Você é...",
  [519041161290752] = "Não poderei continuar sem ler os romances de Fors...",
  [519041161290240] = "Esses caras... eles acham que sou uma máquina de realizar desejos!",
  [519041161288704] = "Dizendo: 'Deixe-me testar você, do que são compostas as antigas ruínas da Cordilheira Hornacis'...",
  [519041161288448] = "Deve ser, certo? Caso contrário, por que alguém apareceria na Montanha Nevada em um terno trespassado, dizendo...",
  [519041161288192] = "A pessoa que vi ontem na montanha deve ter sido uma alucinação, certo?",
  [519041161287680] = "Desta vez é um machado, e seu nome está na lápide...",
  [519041161287424] = "Apenas espere! Se eu te pegar, você está acabado!",
}
